INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'Júlio e Lauro constituíram o mesmo advogado para, juntos, ajuizarem ação de interesse comum. No curso do processo, sobrevieram conflitos de interesse entre os constituintes, tendo Júlio deixado de concordar com Lauro com relação aos pedidos.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'Mário, advogado regularmente inscrito na OAB, foi condenado pela prática de crime hediondo e, após a sentença penal transitada em julgado, respondeu a processo disciplinar, tendo sofrido, como consequência, penalidade de exclusão da Ordem.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'De acordo com o Estatuto da Advocacia e da OAB, tem efeito suspensivo recurso contra', '["A) decisão não unânime proferida por conselho seccional.", "B) decisão que trate de eleições de membros dos órgãos da OAB.", "C) suspensão preventiva decidida pelo Tribunal de Ética e Disciplina.", "D) cancelamento da inscrição obtida com falsa prova."]'::jsonb, 'A', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'Assinale a opção correta de acordo com as disposições do Regulamento Geral do Estatuto da Advocacia e da OAB.', '["A) O compromisso que o requerente à inscrição nos quadros da OAB deve fazer perante o conselho seccional, a diretoria ou o conselho da subseção é indelegável, haja vista sua natureza solene e personalíssima.", "B) Toda vez que figurar como indiciado em inquérito policial, por qualquer espécie de infração, o advogado deve ser assistido por um representante da OAB, sem prejuízo da atuação de seu defensor.", "C) É vedado ao requerente pleitear inscrição nos quadros da OAB sem ter, regularmente registrado, diploma de bacharel em direito, não suprindo sua falta nenhum outro documento.", "D) O estagiário inscrito na OAB pode praticar, isoladamente, todos os atos próprios de advogado, desde que sua inscrição esteja regular."]'::jsonb, 'A', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'Acerca das infrações e sanções disciplinares, assinale a opção correta.', '["A) Considere que uma advogada inscrita na OAB receba, adiantadamente, honorários contratuais de seu cliente, mas não preste o serviço jurídico contratado. Nessa situação hipotética, a advogada tem direito à quantia recebida, visto que sua conduta não configura locupletamento à custa do cliente.", "B) Cometerá infração disciplinar o advogado que receber dinheiro de cliente para pagar parcelas de financiamento e proceder, sem autorização, à compensação com honorários que ele alegue devidos.", "C) Considere que um advogado, após ser notificado pelo juiz para devolver os autos que retenha além do prazo, não atenda ao mandado, tampouco ao de busca e apreensão. Nessa situação hipotética, embora não incida em nenhuma infração disciplinar perante a OAB, deverá o advogado arcar com o ônus processual de sua conduta.", "D) O advogado que esteja em débito com plurais contribuições e multas perante a OAB e que, mesmo regularmente intimado, mantenha-se inadimplente, deverá responder por infração disciplinar e pelo crime de charlatanismo."]'::jsonb, 'B', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'Assinale a opção correta acerca da situação do advogado como empregado, de acordo com as disposições do Estatuto da Advocacia e da OAB.', '["A) O advogado empregado não está obrigado à prestação de serviços profissionais de interesse pessoal, fora da relação de emprego.", "B) Nas causas em que for parte empregador de direito privado, os honorários de sucumbência serão devidos a ele, empregador, e não, aos advogados empregados.", "C) Considera-se jornada de trabalho o período em que o advogado esteja à disposição do empregador, aguardando ou executando ordens no âmbito do escritório, não sendo consideradas as horas trabalhadas em atividades externas.", "D) A relação de emprego, no que se refere ao advogado, não retira a isenção técnica inerente à advocacia, mas reduz a independência profissional, visto que o advogado deve atuar de acordo com as orientações de seus superiores hierárquicos."]'::jsonb, 'A', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'Referentemente à cobrança de honorários advocatícios, assinale a opção correta.', '["A) A ação de cobrança de honorários prescreve em cinco anos, sendo o prazo contado, necessariamente, a partir do vencimento do contrato, cuja juntada é imprescindível.", "B) O prazo prescricional da ação de cobrança de honorários depende do tipo de trabalho profissional contratado e é contado a partir do trânsito em julgado da decisão que os fixar.", "C) O advogado substabelecido com reserva de poderes pode cobrar honorários proporcionais ao trabalho realizado, sem a intervenção daquele que lhe conferiu o substabelecimento.", "D) A decisão judicial que arbitrar honorários e o contrato escrito que o estipular são títulos executivos e constituem crédito privilegiado na falência e na liquidação extrajudicial, entre outras situações."]'::jsonb, 'D', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'Prescinde-se de constituição de advogado regularmente inscrito na OAB para o ajuizamento de ação na 1.ª instância da justiça do trabalho, ação, no valor de até vinte salários mínimos, no juizado especial cível,', '["A) e habeas corpus.", "B) habeas corpus e ação popular.", "C) habeas corpus e mandado de segurança.", "D) e mandado de segurança."]'::jsonb, 'A', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'Em obediência ao que dispõe o Estatuto da Advocacia e da OAB, o advogado que, por motivos pessoais, não mais deseje continuar patrocinando determinada causa deve', '["A) renunciar ao mandato e continuar representando seu cliente por trinta dias, salvo se este constituir novo advogado antes do término do prazo.", "B) fazer um substabelecimento sem reservas de poderes para outro advogado e depois comunicar o fato ao cliente.", "C) comunicar ao cliente a renúncia ao mandato e funcionar no processo nos dez dias subsequentes, caso outro advogado não se habilite antes.", "D) comunicar ao cliente a desistência do mandato e indicar outro advogado para a causa, o qual deve ser, obrigatoriamente, contratado pelo cliente."]'::jsonb, 'C', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'Ao conselho da subseção compete', '["A) representar a OAB no Conselho de Segurança do MERCOSUL.", "B) fiscalizar as funções e atribuições do conselho seccional.", "C) instaurar e instruir processos disciplinares, para julgamento pelo Conselho Federal.", "D) receber pedido de inscrição nos quadros de advogado e estagiário, instruindo e emitindo parecer prévio, para decisão do conselho seccional."]'::jsonb, 'D', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Com relação à ONU, assinale a opção correta.', '["A) Poderão ser admitidos como membros da ONU todos os Estados que o desejarem, independentemente de condições de natureza política ou de qualquer outro teor.", "B) Principal órgão da ONU, a Assembleia Geral é composta de todos os membros da organização, tendo cada Estado-membro direito a apenas um representante e um voto.", "C) O secretário-geral da ONU, eleito pelo Conselho de Segurança mediante recomendação dos seus membros permanentes, tem o dever de atuar em todas as reuniões da Assembleia Geral, do Conselho de Segurança, do Conselho Econômico e Social e do Conselho de Tutela, além de desempenhar outras funções que lhe forem atribuídas por esses órgãos.", "D) O Conselho de Segurança da ONU compõe-se de cinco membros permanentes e de dez membros não permanentes, todos indicados pelo próprio Conselho, devendo estes últimos cumprir mandato de dois anos."]'::jsonb, 'C', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Acerca da condição jurídica dos estrangeiros e dos nacionais no direito brasileiro, assinale a opção correta.', '["A) A CF dispõe expressamente sobre a possibilidade de expulsão do estrangeiro que praticar atividade nociva à ordem pública e ao interesse nacional, salvo se estiverem presentes, simultaneamente, os seguintes requisitos: cônjuge brasileiro e filho brasileiro dependente da economia paterna.", "B) O Brasil, por ter ratificado integralmente o Estatuto de Roma, que criou o Tribunal Penal Internacional, tem o compromisso de entregar ao tribunal os indivíduos contra os quais tenham sido expedidos pedidos de detenção e entrega, mesmo que eles possuam, originariamente, nacionalidade brasileira.", "C) Os estrangeiros de qualquer nacionalidade residentes na República Federativa do Brasil há mais de quinze anos ininterruptos são automaticamente considerados brasileiros naturalizados, independentemente de qualquer outra condição ou exigência.", "D) É vedada a extradição de nacionais, salvo em caso de comprovado envolvimento em tráfico ilícito de entorpecentes, em terrorismo ou em crimes definidos, em lei, como hediondos."]'::jsonb, 'B', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Assinale a opção correta a respeito da medida cautelar em sede de ação direta de inconstitucionalidade, de acordo com o que dispõe a Lei n.º 9.868/1999.', '["A) Tal medida não poderá ser apreciada em período de recesso ou férias, visto que é imperioso que seja concedida por decisão da maioria absoluta dos membros do STF, após a audiência dos órgãos ou autoridades dos quais emanou a lei ou ato normativo impugnado.", "B) Essa medida cautelar só poderá ser concedida se ouvidos, previamente, o advogado-geral da União e o procurador-geral da República.", "C) A decisão proferida em sede de cautelar, seja ela concessiva ou não, será dotada de eficácia contra todos, com efeito ex nunc, salvo se o STF entender que deva conceder-lhe eficácia retroativa.", "D) O relator, em face da relevância da matéria e de seu especial significado para a ordem social e a segurança jurídica, poderá, após a prestação das informações e a manifestação do advogado-geral da União e do procurador-geral da República, sucessivamente, submeter o processo diretamente ao STF, que terá a faculdade de julgar definitivamente a ação."]'::jsonb, 'D', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Assinale a opção correta com relação ao sigilo bancário.', '["A) A quebra do sigilo bancário está submetida à chamada reserva de jurisdição, podendo somente os juízes determiná-la e, ainda assim, de forma fundamentada.", "B) Conforme a lei complementar que rege a matéria, constitui quebra ilegal de sigilo bancário a comunicação, às autoridades competentes, da prática de ilícitos administrativos, mesmo quando do fornecimento de informações sobre operações que envolvam recursos provenientes de qualquer prática criminosa.", "C) As comissões parlamentares de inquérito poderão determinar a quebra de sigilo bancário sem a interferência do Poder Judiciário, desde que o façam de forma fundamentada.", "D) A quebra do sigilo bancário pode ser determinada diretamente pelo Tribunal de Contas da União."]'::jsonb, 'C', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Acerca da distribuição de competências dos entes federativos prevista na CF, assinale a opção correta.', '["A) Compete à União explorar, diretamente ou mediante autorização, concessão ou permissão, o aproveitamento energético dos cursos de água, em articulação com os estados onde se situem os potenciais hidroenergéticos.", "B) No âmbito da legislação concorrente, compete à União legislar sobre normas gerais ou especiais, sem prejuízo da competência suplementar dos estados, do DF e dos municípios.", "C) A competência residual, ainda que em matéria tributária, como a instituição de novos impostos, é dos estados e do DF.", "D) A competência privada da União para legislar sobre certos temas, como os de direito penal, por exemplo, impede que os estados legislem sobre questões específicas, ainda que, para isso, haja, prevista em lei complementar, autorização da União."]'::jsonb, 'A', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Com relação à organização do Poder Legislativo e ao regime jurídico constitucional dos congressistas, assinale a opção correta.', '["A) Os deputados federais e os senadores, todos eles eleitos pelo sistema majoritário, representam o povo dos seus respectivos estados.", "B) A criação de cargos públicos no âmbito das casas do Congresso Nacional deve ser feita por meio de lei ordinária.", "C) Os deputados federais e os senadores não podem assumir cargo de confiança na direção de empresas públicas ou sociedades de economia mista da União.", "D) Desde a expedição do diploma, deputados federais e senadores estão sujeitos a julgamento perante o STF, o qual, ao receber a denúncia contra congressista, deverá solicitar autorização à respectiva Casa para prosseguir com a ação penal."]'::jsonb, 'C', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'No que diz respeito à ordem social, assinale a opção correta.', '["A) É lícita a decisão que, provinda de diretor de escola pública, impeça aluno de frequentar, temporariamente, aulas do ensino fundamental em razão do não pagamento de contribuição instituída pela associação de pais e mestres para custear despesas, de pequena monta, da escola.", "B) Por gozarem de autonomia didático-científica, administrativa e de gestão financeira e patrimonial, as universidades públicas não estão sujeitas ao controle do tribunal de contas.", "C) Será impedido de concluir o curso fundamental o aluno que, matriculado em escola pública ou particular, não curse, pelo menos, um semestre de disciplina voltada para a educação religiosa.", "D) Entre os deveres do Estado para com o ensino fundamental, incluem-se as garantias de acesso gratuito do educando a material didático-escolar, transporte, alimentação e assistência à saúde."]'::jsonb, 'D', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A respeito dos princípios gerais da atividade econômica, assinale a opção correta com base na CF.', '["A) Como agente normativo e regulador da atividade econômica, o Estado exerce, na forma da lei, as funções de fiscalização, incentivo e planejamento, que são determinantes tanto para o setor público quanto para o privado.", "B) Para todos os efeitos, os potenciais de energia hidráulica constituem propriedade do solo e, por isso, consideram-se pertencentes ao respectivo estado da Federação.", "C) O aproveitamento do potencial de energia renovável de capacidade reduzida depende de autorização do Estado.", "D) Constitui monopólio da União o transporte, por meio de conduto, de gás natural, qualquer que seja a sua origem."]'::jsonb, 'D', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Acerca da edição de súmulas vinculantes pelo STF, assinale a opção correta.', '["A) Ainda que inexistam reiteradas decisões sobre determinada matéria constitucional, o STF poderá criar súmula vinculante acerca do tema caso o julgue relevante.", "B) O enunciado da súmula deve versar sobre normas determinadas, quando exista, com relação a elas, controvérsia atual, entre órgãos judiciários ou entre esses e a administração pública, que acarrete grave insegurança jurídica e relevante multiplicação de processos.", "C) O procurador-geral da República manifestar-se-á acerca da edição de enunciado de súmula vinculante apenas nos casos em que o propuser.", "D) O Conselho Federal da OAB e os conselhos seccionais são legitimados a propor a edição de enunciado de súmula vinculante."]'::jsonb, 'B', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Assinale a opção correta com relação à garantia constitucional do habeas corpus.', '["A) Caso uma decisão de turma recursal de juizados especiais criminais constitua ato coator da liberdade de locomoção de um acusado, será cabível habeas corpus dirigido ao STJ.", "B) Caso a sentença penal condenatória emanada de juiz militar imponha pena de exclusão de militar ou de perda de patente, será cabível a utilização do habeas corpus.", "C) Caso ocorra, ao fim de um processo penal, a fixação de pena de multa em sentença penal condenatória, ficará prejudicada a utilização do habeas corpus, haja vista a sua destinação exclusiva à tutela do direito de ir e vir.", "D) Ainda que já extinta a pena privativa de liberdade, é cabível a utilização de habeas corpus para pedido de reabilitação de paciente."]'::jsonb, 'C', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Considerando as repercussões processuais das garantias constitucionais, assinale a opção correta.', '["A) Impõe-se, por ser norma de processo civil, de aplicação imediata, a legislação superveniente à impetração do mandado de segurança.", "B) A ausência de decisão administrativa em prazo razoável não enseja mandado de segurança, pois o Poder Judiciário não pode fixar prazo para decisões do Poder Executivo.", "C) Estrangeiro residente no exterior não pode impetrar mandado de segurança no Brasil.", "D) Mandado de segurança coletivo impetrado pela OAB deve ser ajuizado perante a justiça federal, ainda que não se trate de postulação de direito próprio."]'::jsonb, 'D', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Assinale a opção correta no que se refere às limitações estabelecidas no texto constitucional ao cargo de presidente da República.', '["A) O presidente da República pode escolher e nomear livremente os ministros de Estado, com exceção do ministro das Relações Exteriores, cuja indicação deve ser aprovada pelo Senado Federal, assim como ocorre com os candidatos ao cargo de embaixador.", "B) A nomeação, pelo presidente da República, do advogado-geral da União depende da prévia aprovação do Senado Federal, que o fará em escrutínio secreto.", "C) Embora nomeado pelo presidente da República para um mandato de dois anos, o procurador-geral da República poderá ser destituído do cargo, de ofício, antes do término do mandato, por decisão da maioria absoluta dos senadores.", "D) Os ministros de Estado são nomeados livremente pelo presidente da República, podendo o Congresso Nacional, por deliberação da maioria absoluta de seus membros, exonerá-los a qualquer tempo."]'::jsonb, 'C', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'De acordo com o que dispõe a Lei das Sociedades por Ações, as ações, conforme a natureza dos direitos ou vantagens que confiram a seus titulares, podem ser ordinárias, preferenciais ou de fruição. As ações de fruição', '["A) constituem títulos que podem ser atribuídos aos acionistas após suas ações serem integralmente amortizadas.", "B) conferem aos titulares apenas os direitos comuns de acionista sem quaisquer privilégios ou vantagens.", "C) conferem ao titular algum privilégio ou vantagem de ordem patrimonial, sem que, entretanto, o acionista tenha direito de participação nos lucros reais.", "D) são tipicamente usadas por acionistas especuladores, ou por aqueles que não têm interesse na gestão da sociedade."]'::jsonb, 'A', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Acerca da disciplina normativa do cheque, assinale a opção correta.', '["A) A lei admite a emissão de cheque contra banco, instituição financeira ou cooperativa de crédito.", "B) Assim como os demais títulos de crédito, o cheque deve ser apresentado para aceite.", "C) A lei veda ao banco sacado a prestação de aval para garantir o pagamento do cheque.", "D) Admite-se, excepcionalmente, a estipulação de cláusula de juros inserida no cheque."]'::jsonb, 'C', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Suponha que Maria tenha ajuizado ação de cobrança contra a pessoa jurídica Y, a qual, no curso da referida ação de conhecimento, teve sua falência decretada pelo juízo competente. Considerando essa situação hipotética, assinale a opção correta com base na legislação de regência.', '["A) A decretação da falência de Y não pode suspender o curso da ação proposta por Maria.", "B) Caso a sede de Y esteja localizada fora do país, o juízo competente para a decretação da falência será o do local de sua filial no Brasil.", "C) O juízo competente para processar a ação proposta por Maria, poderá determinar, de imediato, a reserva da importância que estimar devida na falência.", "D) Se a habilitação do crédito de Maria ocorrer após a homologação do quadro geral de credores e for recebida como retardatária, Maria perderá o direito aos rateios eventualmente realizados, mas o valor de seu crédito será acrescido de juros e atualizado monetariamente até a data de sua integral satisfação."]'::jsonb, 'B', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Acerca da disciplina jurídica da proteção contratual do consumidor, assinale a opção correta.', '["A) A lei confere ao consumidor a possibilidade de desistir do contrato, no prazo máximo de quinze dias a contar do recebimento do produto, no caso de contratação de fornecimento de produtos ocorrida fora do estabelecimento empresarial.", "B) Reputam-se nulas de pleno direito as cláusulas contratuais relativas ao fornecimento de produtos e serviços que infrinjam normas ambientais ou possibilitem a violação dessas normas.", "C) A garantia contratual exclui a garantia legal, desde que conferida mediante termo escrito que discipline, de maneira adequada, a constituição daquela garantia, bem como a forma, o prazo e o lugar para o seu exercício.", "D) A lei limita a 10% do valor da prestação as multas de mora decorrentes do inadimplemento de obrigações no seu termo, no caso de fornecimento de produtos que envolva concessão de financiamento ao consumidor."]'::jsonb, 'B', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Assinale a opção correta a respeito da disciplina normativa da defesa, em juízo, do consumidor.', '["A) É lícita às associações legalmente constituídas há mais de um ano a propositura de ação coletiva para a defesa dos direitos de seus associados, desde que haja prévia autorização em assembleia.", "B) Na hipótese de ação coletiva para a defesa de interesses individuais homogêneos, é exclusivamente competente para a execução coletiva o juízo da liquidação da sentença ou o da ação condenatória.", "C) Tratando-se de ações coletivas para a defesa de direitos individuais homogêneos, a sentença fará coisa julgada erga omnes, no caso de procedência ou improcedência do pedido, para beneficiar todas as vítimas.", "D) De acordo com o Código de Defesa do Consumidor, as ações coletivas para a defesa de interesses ou de direitos coletivos não induzem litispendência para as ações individuais."]'::jsonb, 'D', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Acerca das obrigações de dar, fazer e não fazer, assinale a opção correta.', '["A) No caso de entrega de coisa incerta, se houver, antes da escolha, perda ou deterioração do bem, ainda que decorrente de caso fortuito ou força maior, a obrigação ficará resolvida para ambas as partes.", "B) Em caso de obrigação facultativa, o perecimento da coisa devida não implica a liberação do devedor do vínculo obrigacional, podendo-se dele exigir a realização da obrigação devida.", "C) É divisível a obrigação de prestação de coisa indeterminada.", "D) Tratando-se de obrigação de entrega de coisa certa, a obrigação será extinta caso a coisa se perca sem culpa do devedor, antes da tradição ou mediante condição suspensiva."]'::jsonb, 'D', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Assinale a opção correta de acordo com o Código Civil brasileiro.', '["A) A sub-rogação objetiva ou real ocorre pela substituição de uma das partes, sem a extinção do vínculo obrigacional.", "B) Caso o sub-rogado não consiga receber a importância devida, ele poderá cobrá-la do credor original.", "C) Aplica-se à dação em pagamento o regime jurídico dos vícios redibitórios.", "D) Opera-se novação quando o devedor oferece nova garantia ao credor."]'::jsonb, 'C', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Assinale a opção correta com relação à responsabilidade civil.', '["A) O dano deve ser certo, por essa razão não é possível a indenização por dano eventual, decorrente da perda de uma chance.", "B) Tratando-se de responsabilidade subjetiva contratual, a responsabilidade do agente pode subsistir mesmo nos casos de força maior e de caso fortuito, desde que a lei não coíba a sua previsão.", "C) De acordo com o regime da responsabilidade civil traçado no Código Civil brasileiro, inexistem causas excludentes da responsabilidade civil objetiva.", "D) A extinção da punibilidade criminal sempre obsta a propositura de ação civil indenizatória."]'::jsonb, 'B', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Acerca do direito de família, assinale a opção correta.', '["A) O casamento religioso com efeitos civis passa a produzir efeitos somente a partir da data em que é efetivado o seu registro perante o oficial competente.", "B) A existência de impedimentos dirimentes absolutos acarreta a ineficácia do casamento.", "C) O casamento inexistente não pode ser declarado putativo.", "D) É inválido o casamento contraído por coação a qualquer dos cônjuges."]'::jsonb, 'C', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A respeito da vigência, aplicação, eficácia e interpretação da lei, assinale a opção correta.', '["A) A derrogação torna sem efeito uma parte de determinada norma, não perdendo esta a sua vigência.", "B) A interpretação da norma presta-se a preencher as lacunas existentes no sistema normativo.", "C) O regime de bens obedece à lei do país em que for celebrado o casamento.", "D) Em regra, caso a lei revogadora venha a perder a vigência, restaura-se a lei revogada."]'::jsonb, 'A', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'No que diz respeito à extinção dos contratos, assinale a opção correta.', '["A) Na resolução por onerosidade excessiva, não é necessária a existência de vantagem da outra parte, bastando que a prestação de uma das partes se torne excessivamente onerosa.", "B) A resolução por inexecução voluntária do contrato produz efeitos ex tunc se o contrato for de execução continuada.", "C) Ainda que a inexecução do contrato seja involuntária, a resolução ensejará o pagamento das perdas e danos para a parte prejudicada.", "D) A eficácia da resolução unilateral de determinado contrato independe de pronunciamento judicial e produz efeitos ex nunc."]'::jsonb, 'D', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Assinale a opção correta com relação ao registro, exigido na transmissão da propriedade de bens imóveis.', '["A) Realizado o registro do título translativo, este produzirá efeitos ex tunc, o que torna o adquirente proprietário desde a formalização do título.", "B) Sendo o registro, no âmbito do direito nacional, meio necessário para a transmissão da propriedade de bem imóvel, sua realização importa presunção absoluta de propriedade.", "C) Vendido o imóvel a duas pessoas diferentes, será válido o registro ainda que realizado pelo adquirente que possua o título de data mais recente.", "D) Se uma pessoa vender imóvel seu a outra e esta, por sua vez, o vender a terceiro, será possível, provada a regularidade dos negócios, o registro desse último título translativo sem que se registre o primeiro."]'::jsonb, 'C', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Considere que o filho de Mário Lins de Souza e de Luna Ferreira de Melo tenha sido registrado com o nome de Paulo de Souza. Nessa situação hipotética,', '["A) Paulo, se assim o desejar, poderá, no prazo de até um ano após atingir a maioridade, introduzir em seu nome um patronímico materno, sem que precise justificar sua vontade.", "B) é obrigatória, em razão da abolição do traço patriarcal da legislação civil brasileira, a adoção do sobrenome materno, de modo que o registro de nascimento de Paulo poderá ser alterado a qualquer momento e, até mesmo, de ofício.", "C) apenas por meio do casamento será possível a Paulo alterar seu nome, o que será feito com a inclusão de sobrenome da esposa.", "D) Paulo poderá, se assim o desejar, incluir em seu nome apelido que seja notório, o que deverá ocorrer por meio de pedido devidamente instruído e dirigido ao oficial do cartório de registro civil."]'::jsonb, 'A', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A respeito dos defeitos dos negócios jurídicos, assinale a opção correta.', '["A) A lesão é um defeito que surge concomitantemente à realização do negócio e enseja a sua anulabilidade. Entretanto, permite-se a revisão contratual para evitar a anulação, aproveitando-se, assim, o negócio.", "B) Se, na celebração do negócio, uma das partes induzir a erro a outra, levando-a a concluir o negócio e a assumir uma obrigação desproporcional à vantagem obtida pelo outro, esse negócio será nulo porque a manifestação de vontade emana de erro essencial e escusável.", "C) O dolo acidental, a despeito do qual o negócio seria realizado, embora por outro modo, acarreta a anulação do negócio jurídico.", "D) Tratando-se de negócio jurídico a título gratuito, somente se configura fraude quando a insolvência do devedor seja notória ou haja motivo para ser conhecida, admitindo-se a anulação do negócio pelo credor."]'::jsonb, 'A', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Assinale a opção correta acerca da prestação de alimentos.', '["A) Somente os filhos têm o direito de pedir alimentos.", "B) O direito a alimentos é recíproco entre pais e filhos.", "C) Após a separação judicial do casal, mesmo que o cônjuge venha a necessitar de alimentos, ele não mais poderá pleitear ao outro cônjuge a prestação alimentícia.", "D) Os créditos alimentares prescrevem em cinco anos."]'::jsonb, 'B', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Considere que Laura, menor absolutamente incapaz, representada por sua mãe, ajuíze ação de investigação de paternidade no foro de seu domicílio. Nessa situação hipotética, caso more em outro estado da Federação, o réu poderá', '["A) apenas contestar a ação, visto que a competência para o conhecimento da ação, nessa hipótese, é do foro do domicílio de Laura, haja vista ser absolutamente incapaz.", "B) alegar a incompetência do juízo, mediante simples petição, a qualquer tempo, independentemente de exceção, haja vista tratar-se de incompetência absoluta.", "C) apresentar exceção de incompetência de juízo, no prazo da resposta, uma vez que a competência para o conhecimento da ação, nesse caso, é do foro do domicílio do réu.", "D) apresentar exceção de incompetência de juízo, a qualquer tempo, desde que o faça antes da sentença, visto que a competência, na referida hipótese, é do foro do domicílio do réu."]'::jsonb, 'C', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Com relação aos atos processuais, assinale a opção correta.', '["A) Comparecendo o réu apenas para arguir a nulidade da citação e sendo esta decretada, será considerada feita a citação na data em que for juntado aos autos o mandado de nova citação, devidamente cumprido, com os requisitos legais.", "B) São requisitos da citação por edital, entre outros, a determinação, pelo juiz, do prazo, que variará entre vinte e quarenta dias, a partir da data da primeira publicação.", "C) Tratando-se de ações de estado, a citação será feita pelo correio, nas localidades atendidas pela entrega domiciliar de correspondência.", "D) Para a fixação do termo inicial da contagem de prazo processual, se a comunicação for feita por edital, o prazo para a prática do ato processual terá início a partir do termo final do prazo previsto no próprio edital para aperfeiçoamento da citação."]'::jsonb, 'D', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Fabrício ajuizou ação de interdição contra José, seu pai, alegando, em síntese, que este sofria de demência senil. José foi, então, citado para comparecer ao interrogatório, ocasião em que respondeu às perguntas feitas pelo juiz e externou seu inconformismo com a ação ajuizada pelo filho. Aberto o prazo de cinco dias, após o interrogatório, para o interditando impugnar o pedido de sua interdição, este se quedou inerte, em que pese não ser portador de doença mental alguma, além de não haver, nos autos, prova da suposta demência.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Considere que, ajuizada ação de cobrança, entre partes capazes, para recebimento de dívida já prescrita, o juiz, ao analisar a exordial, a indefira, de pronto, devido à consumação da prescrição. Em face dessa situação hipotética, assinale a opção correta a respeito da decisão do magistrado.', '["A) Sendo a prescrição preliminar de mérito, o momento processual de sua apreciação deveria ocorrer na sentença final.", "B) A prescrição não poderia ser declarada de ofício visto que a ação trata de direitos patrimoniais.", "C) A petição inicial deve ser indeferida quando o juiz verificar, desde logo, a decadência ou a prescrição.", "D) O juiz não pode reconhecer de ofício a prescrição."]'::jsonb, 'C', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Ajuizada ação de indenização por danos morais, o autor foi devidamente intimado para apresentar emenda à inicial, haja vista não estarem presentes os requisitos exigidos nos arts. 282 e 283 do CPC. O autor, contudo, não apresentou a devida emenda, tendo sido indeferida a petição inicial.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'No que se refere ao procedimento cautelar, assinale a opção correta.', '["A) Salvo decisão judicial em contrário, a medida cautelar cessa a sua eficácia durante o período de suspensão do processo.", "B) Tratando-se de medida cautelar, o indeferimento da medida não obsta a que a parte intente a ação nem influi no julgamento desta, salvo se o juiz, no procedimento cautelar, acolher a alegação de decadência do direito do autor.", "C) Cabe ao requerente da cautelar propor ação principal no prazo prescricional de trinta dias, contado da data da efetivação da medida, quando esta tiver sido concedida em procedimento preparatório.", "D) Somente quando admitido recurso, eventual medida cautelar será requerida diretamente ao tribunal."]'::jsonb, 'B', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Paulo ajuizou ação contra Aldo. Ao receber a inicial, o juiz verificou que a matéria controvertida era unicamente de direito e que já havia sido proferida sentença de total improcedência em casos idênticos, e, por isso, proferiu sentença reproduzindo o teor das anteriormente prolatadas, sem a citação de Aldo.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A ação rescisória', '["A) não pode ser ajuizada por terceiro, ainda que juridicamente interessado.", "B) será admitida no âmbito dos juizados especiais cíveis quando houver sentença transitada em julgado.", "C) deverá ser ajuizada até dois anos após o trânsito em julgado da última decisão, sob pena de prescrição.", "D) é admitida ainda que não se tenham esgotado todos os recursos contra a sentença transitada em julgado."]'::jsonb, 'D', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'João ajuizou ação em que pretende a anulação de título de crédito emitido em favor de sua ex-esposa. Ao despachar a inicial, o juiz descobriu que a ré já havia ajuizado, em outro juízo da mesma comarca, ação cautelar de arresto fundada no mesmo título.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Assinale a opção correta no que diz respeito aos embargos à execução.', '["A) No prazo para embargos, reconhecido o crédito do exequente e comprovado o depósito de 30% do valor em execução, incluindo-se custas e honorários de advogado, deve o juiz parcelar o referido valor em seis parcelas mensais, acrescidas apenas de correção monetária.", "B) Pode o executado, no prazo de cinco dias, contados da adjudicação, alienação ou arrematação, oferecer embargos fundados em nulidade da execução, ou em causa extintiva da obrigação, desde que superveniente à penhora.", "C) Sendo vários os executados, o prazo para oposição de embargos é comum a todos eles.", "D) O efeito suspensivo concedido em favor de apenas um dos executados a todos aproveita, razão por que a execução deve ficar suspensa."]'::jsonb, 'B', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Manoel estava no interior de um ônibus da concessionária de serviço público municipal, empresa não integrante da administração pública, quando o veículo derrapou em uma curva e capotou. Em razão desse acidente, Manoel sofreu dano material e moral.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Com relação ao regime disciplinar dos servidores públicos federais, previsto na Lei n.º 8.112/1990, assinale a opção correta.', '["A) Em caso de processo administrativo disciplinar contra servidor público, a lei autoriza, como medida cautelar, que a autoridade instauradora do processo determine o seu afastamento do cargo, pelo prazo de até sessenta dias, sem prejuízo da remuneração, para evitar que esse servidor possa influir na apuração do fato a ele imputado.", "B) Servidor aposentado não pode ser punido em razão de infração administrativa praticada na ativa e cuja penalidade prevista seja a de demissão.", "C) A penalidade de demissão não impede, em nenhuma hipótese, que o servidor venha a ocupar outro cargo público.", "D) As penalidades de suspensão aplicadas aos servidores públicos não poderão ter seus registros cancelados."]'::jsonb, 'A', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Assinale a opção correta no que se refere à revogação dos atos administrativos.', '["A) A revogação do ato administrativo produz efeitos ex tunc.", "B) Atos vinculados não podem ser objeto de revogação.", "C) A revogação pode atingir certidões e atestados.", "D) Atos que gerarem direitos adquiridos poderão ser revogados."]'::jsonb, 'B', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Acerca da desapropriação e dos institutos a ela relacionados, assinale a opção correta.', '["A) Tratando-se de desapropriação por utilidade pública para a realização de obra, as áreas contíguas necessárias à execução da obra poderão ser abrangidas pela desapropriação, independentemente da inclusão dessas áreas na declaração de utilidade pública.", "B) A fase declaratória, durante a qual o poder público manifesta sua vontade na futura desapropriação, é iniciada com a declaração expropriatória e formalizada por meio de ato exclusivo do chefe do Poder Executivo federal, estadual ou municipal; por isso, não pode o dirigente máximo de autarquia ou de agência reguladora, por exemplo, expedir declaração expropriatória.", "C) O decreto expropriatório caduca no prazo de cinco anos caso a desapropriação por utilidade pública não seja efetivada mediante acordo ou judicialmente, sendo o termo final desse prazo, para as desapropriações que correrem na via judicial, o do trânsito em julgado da ação de desapropriação.", "D) No caso de imissão prévia na posse, na desapropriação por necessidade ou utilidade pública e interesse social, havendo divergência entre o preço ofertado em juízo e o valor do bem, os juros moratórios destinam-se a recompor a perda decorrente do atraso no efetivo pagamento da indenização fixada na sentença; desse modo, só serão devidos esses juros se o pagamento não for feito até 1.º de janeiro do exercício seguinte àquele em que o pagamento deveria ter sido feito."]'::jsonb, 'D', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Com relação aos bens públicos, assinale a opção correta.', '["A) Por terem caráter tipicamente patrimonial, os bens de uso comum do povo podem ser alienados.", "B) Os bens dominicais são indisponíveis.", "C) A lei que institui normas para licitações e contratos da administração pública (Lei n.º 8.666/1993) define regras para a alienação dos bens públicos móveis e imóveis.", "D) Ocorre a desafetação quando um bem público passa a ter uma destinação pública especial de interesse direto ou indireto da administração."]'::jsonb, 'C', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Mauro, chefe do setor de compras de um órgão do Instituto Nacional do Seguro Social, recebeu pedido de abertura de procedimento licitatório para a aquisição de grande quantidade dos seguintes itens: impressoras, cartuchos para impressoras, monitores LCD e licença para uso de sistema operacional a ser utilizado nos computadores da autarquia. A solicitação estava de acordo com todas as normas aplicáveis, incluindo-se a justificativa do quantitativo e da necessidade dos referidos itens. Antes de promover a abertura de qualquer procedimento de compra, Mauro procedeu a análise técnico-econômica e concluiu que a compra dos cartuchos para impressoras, se realizada separadamente da dos demais itens, implicaria uma ampliação da concorrência, sem perda da economia de escala. Constatou, também, que era a terceira vez no ano que a administração encaminhava pedido para a compra de cartuchos para impressora. Por fim, verificou que a estimativa do valor total que seria gasto na contratação era de R$ 700.000,00.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Acerca do contrato administrativo, assinale a opção correta.', '["A) Mediante acordo entre as partes, pode a supressão de um objeto contratado ser superior a 25% do valor atualizado do contrato.", "B) O contratado fica obrigado a aceitar, nas mesmas condições contratuais, os acréscimos que se fizerem nas obras, serviços, compras ou reforma de edifício, até o limite de 25% do valor inicial atualizado do contrato.", "C) Em atenção ao princípio da supremacia do interesse público, a majoração dos encargos do contratado advinda de alteração unilateral do contrato não implica o restabelecimento do equilíbrio econômico-financeiro inicial.", "D) A responsabilidade do contratado pela reparação ou correção dos vícios encontrados no objeto contratado somente ocorrerá se houver previsão expressa nesse sentido no contrato firmado entre a administração pública e o fornecedor."]'::jsonb, 'A', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Em cada uma das opções abaixo, é apresentada uma situação hipotética, seguida de uma assertiva a ser julgada com relação à organização da administração pública. Assinale a opção em que a assertiva está correta.', '["A) Hélio pretende ingressar com ação ordinária de repetição de indébito, visando à devolução do imposto de renda que fora pago, conforme alega, indevidamente. Nessa situação, a ação deverá ser proposta em face da Receita Federal do Brasil.", "B) A União qualificou uma instituição privada como organização social. Nessa situação, essa instituição passará a integrar a administração indireta da União.", "C) Jorge ingressou com reclamação trabalhista contra sociedade de economia mista federal exploradora de atividade econômica, em regime de ampla concorrência. Nessa situação, conforme o regime constitucional, os bens dessa empresa não podem ser penhorados, já que ela integra a administração indireta da União.", "D) Mediante previsão do contrato de consórcio público, foi firmado contrato de programa entre a União e entidade que integra a administração indireta de um estado consorciado. Nessa situação, esse contrato de programa será automaticamente extinto caso o contratado deixe de integrar a administração indireta do estado consorciado."]'::jsonb, 'D', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Com relação ao processo administrativo federal, assinale a opção correta.', '["A) Não se admite a legitimidade de associação para a defesa de direitos ou interesses difusos.", "B) Não pode uma autoridade hierárquica superior delegar a uma autoridade inferior o poder de decidir, em primeira instância, os processos administrativos de sua competência não exclusiva.", "C) Não se admite a intimação fictícia.", "D) Ao processo em apreço não se aplica o princípio que veda a reformatio in pejus."]'::jsonb, 'D', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Júlia, que está desempregada, não conseguiu pagar a tarifa de energia elétrica de sua residência, referente ao mês de janeiro de 2010. Por esse motivo, o fornecimento de energia foi suspenso por ordem da diretoria da concessionária de energia elétrica, sociedade de economia mista.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Acerca da disciplina constitucional da repartição das receitas tributárias, assinale a opção correta.', '["A) Ao DF cabe metade da arrecadação do imposto que a União instituir no exercício de sua competência residual ou extraordinária.", "B) Cabe aos municípios, em qualquer hipótese, a integralidade do imposto sobre a propriedade territorial rural.", "C) Aos municípios pertence a integralidade do produto da arrecadação do imposto de renda incidente na fonte sobre os rendimentos pagos, a qualquer título, por eles.", "D) A União deve repassar aos estados 25% do produto da arrecadação do IPI."]'::jsonb, 'C', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Assinale a opção correta acerca das garantias e privilégios do crédito tributário.', '["A) De acordo com o CTN, as garantias atribuídas ao crédito tributário alteram a sua natureza bem como a da obrigação tributária correspondente.", "B) A cobrança judicial do crédito tributário, embora não se subordine a concurso de credores, está sujeita à habilitação em falência, recuperação judicial, inventário ou arrolamento.", "C) Denominam-se concursais os créditos tributários decorrentes de fatos geradores acontecidos durante processo falimentar, bem como após a extinção deste.", "D) No processo falimentar, o crédito tributário não prefere às importâncias passíveis de restituição, nos termos da lei falimentar, nem aos créditos com garantia real, no limite do valor do bem gravado."]'::jsonb, 'D', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Caso ocorra a fusão de duas grandes indústrias alimentícias brasileiras que, juntas, detenham mais de 60% do mercado nacional de certo item de alimentação, de acordo com o que dispõe a CF, para prevenir os desequilíbrios da concorrência causados pela citada fusão,', '["A) a União, os estados, o DF e os municípios poderão estabelecer critérios especiais de tributação, além de outras normas com os mesmos objetivos.", "B) somente a União poderá estabelecer critérios especiais de tributação, podendo os estados, o DF e os municípios estabelecer outras normas com os mesmos objetivos.", "C) a União, os estados, o DF e os municípios poderão estabelecer critérios especiais de tributação, todavia apenas a União detém competência para estabelecer outras normas com os mesmos objetivos.", "D) somente a União poderá estabelecer critérios especiais de tributação, além de outras normas com os mesmos objetivos."]'::jsonb, 'D', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Contribuição cobrada de servidor público estadual e destinada ao custeio de seu plano de aposentadoria público deve ser recolhida', '["A) à União, independentemente de qualquer situação e do ente com o qual o servidor mantenha o vínculo empregatício.", "B) ao estado, se o servidor for mero detentor de cargo efetivo estadual e se o estado não tiver regime previdenciário próprio.", "C) à União, se o servidor for mero detentor de cargo em comissão estadual (declarado em lei de livre nomeação e exoneração), independentemente de o estado ter, ou não, regime previdenciário próprio.", "D) ao estado, se o servidor for mero detentor de cargo temporário estadual, no caso de o estado possuir regime previdenciário próprio."]'::jsonb, 'C', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Caso determinada empresa se dedique exclusivamente à produção de manufaturados destinados à exportação, a ela se imputa a obrigação de pagar', '["A) a contribuição social sobre o faturamento, destinada à seguridade social (COFINS).", "B) a contribuição social destinada ao Programa de Integração Social (PIS).", "C) o IPI.", "D) o imposto sobre a renda e proventos de qualquer natureza."]'::jsonb, 'D', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Consoante o princípio tributário da reserva legal, é vedado à União, aos estados, ao DF e aos municípios exigir ou aumentar tributo sem lei que o estabeleça. Todavia, admite-se, constitucionalmente, que', '["A) a União e os estados criem ou aumentem tributo por meio de decreto.", "B) a União aumente determinados tributos por meio de decreto.", "C) a União crie ou aumente tributo por meio de decreto.", "D) os estados aumentem tributo por meio de decreto."]'::jsonb, 'B', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Suponha que um decreto trate integralmente sobre relações jurídicas pertinentes aos tributos e que uma lei disponha parcialmente sobre tributos. Nessa situação, de acordo com o CTN,', '["A) nem o decreto nem a lei se inserem no conceito de legislação tributária.", "B) o decreto insere-se no conceito de legislação tributária; a lei, não.", "C) tanto o decreto quanto a lei se inserem no conceito de legislação tributária.", "D) a lei se insere no conceito de legislação tributária; o decreto, não."]'::jsonb, 'C', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Um fiscal federal, em processo de auditoria, verificou que uma empresa estava em dívida para com o fisco em relação ao imposto de renda. Ao autuar a empresa para pagamento do imposto, o fiscal impôs-lhe, ainda, uma multa por atraso no pagamento e outra, por não ter entregue a declaração anual de rendimentos da pessoa jurídica.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Vera e Mara são contribuintes obrigados, solidariamente, por lei, a pagar, mensalmente, certo tributo. Em determinado mês, foi publicada lei que isentou do imposto, pessoalmente, as pessoas que sofriam de certa enfermidade, da qual Vera é portadora.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Certo contribuinte foi notificado, em 31 de outubro de determinado ano, para pagamento de um tributo, sem que a lei ou a notificação tenha determinado o vencimento daquela obrigação.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Com relação às normas de proteção ao trabalho da mulher, inseridas na CLT, assinale a opção correta.', '["A) O trabalho noturno terá salário superior ao diurno, com percentual de acréscimo de, no mínimo, 25%.", "B) Em caso de prorrogação do horário normal de trabalho, é obrigatória a concessão de descanso de, no mínimo, quinze minutos antes do início do horário extraordinário do trabalho.", "C) Na admissão ao emprego, é facultado ao empregador exigir atestado ou exame para a comprovação de gravidez.", "D) Entre duas jornadas de trabalho, deve haver um intervalo de, no mínimo, doze horas consecutivas destinadas ao repouso."]'::jsonb, 'B', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Com relação ao contrato de trabalho, assinale a opção correta.', '["A) Constitui motivo para alteração do contrato de trabalho pelo empregador o afastamento do empregado em virtude das exigências do serviço militar.", "B) O empregado poderá deixar de comparecer ao serviço sem prejuízo do salário nos dias em que estiver comprovadamente realizando prova de exame vestibular para ingresso em estabelecimento de ensino superior.", "C) A suspensão do empregado por mais de quinze dias consecutivos importa na rescisão injusta do contrato de trabalho.", "D) Constitui justa causa para rescisão do contrato de trabalho pelo empregador a condenação criminal do empregado proferida pelo juiz de primeiro grau."]'::jsonb, 'B', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Considerando o disposto na CLT a respeito do aviso prévio, assinale a opção correta.', '["A) O valor das horas extraordinárias habituais integra o aviso prévio indenizado.", "B) Na despedida indireta, é incabível o aviso prévio.", "C) O aviso prévio é exigido somente do empregado, pois o empregador pode rescindir o contrato livremente, arguindo a subordinação existente na relação de emprego.", "D) O período de aviso prévio não integra o tempo de serviço para os devidos efeitos legais."]'::jsonb, 'A', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Assinale a opção correta relativamente à resposta do reclamado.', '["A) Quando forem notificados para a ação vários reclamados, com diferentes procuradores, o prazo para a contestação será contado em dobro.", "B) De acordo com a CLT, o fato de o juiz ter parentesco por consanguinidade ou afinidade até o terceiro grau civil em relação à pessoa dos litigantes é causa de suspeição, devendo ser questionada, via exceção, no caso de não pronunciamento pelo próprio magistrado.", "C) A perempção, a conexão e a falta de caução ou de outra prestação, que a lei exige como preliminar, podem ser alegadas quando da discussão de mérito.", "D) Cabe ao reclamado manifestar-se precisamente sobre os fatos narrados na petição inicial, presumindo-se verdadeiros os fatos não impugnados, ainda que em contradição com a defesa, considerada em seu conjunto."]'::jsonb, 'B', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Os requisitos necessários à caracterização do vínculo de emprego abrangem', '["A) onerosidade, exclusividade, subordinação jurídica e alteridade.", "B) eventualidade, pessoalidade, onerosidade e subordinação jurídica.", "C) subordinação, não eventualidade, onerosidade e pessoalidade.", "D) dependência econômica, continuidade, subordinação e alteridade."]'::jsonb, 'C', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Fábio, empregado da empresa Transportar Ltda., firmou, com seu empregador, acordo escrito em que ficou estabelecido que o excesso de horas trabalhadas em um dia seria compensado pela correspondente diminuição em outro dia, sem acréscimo salarial.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Paula firmou contrato de trabalho, por prazo indeterminado, com uma empresa, onde trabalhou pelo período de três anos. Em 10/10/2008, foi sumariamente demitida, sem justa causa e sem receber qualquer valor rescisório ou indenizatório, embora estivesse com dois meses de gestação.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Assinale a opção correta no que diz respeito às decisões na justiça do trabalho.', '["A) A sentença deverá conter o nome das partes, o resumo do pedido e da defesa, a apreciação das provas, os fundamentos da decisão e a respectiva conclusão.", "B) Não há necessidade de menção das custas que devam ser pagas pela parte vencida na sentença, pois o seu valor será apurado na fase de liquidação.", "C) Erros evidentes de datilografia ou de cálculo existentes na sentença somente poderão ser corrigidos a requerimento da parte e antes de iniciada a execução.", "D) A União não será intimada das decisões homologatórias de acordos que contenham parcela indenizatória, cabendo sempre a execução de ofício."]'::jsonb, 'A', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Com relação aos atos, termos e prazos processuais na justiça trabalhista, assinale a opção correta.', '["A) Os atos processuais devem ser públicos, salvo quando o interesse social determinar o contrário, e terão de realizar-se nos dias úteis, no horário de expediente forense habitual.", "B) No processo trabalhista, os prazos são contados com a inclusão do dia em que se iniciam e do dia em que vencem.", "C) Os documentos juntados aos autos podem ser desentranhados sempre que a parte assim o requerer.", "D) Presume-se recebida, 48 horas após a sua postagem, a notificação para a prática de ato processual, sendo possível a produção de prova em contrário."]'::jsonb, 'D', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Acerca dos recursos no processo do trabalho, assinale a opção correta.', '["A) Nas execuções, cabe agravo de instrumento, no prazo de oito dias, contra as decisões do juiz ou presidente.", "B) Nas causas sujeitas ao procedimento sumaríssimo, somente será admitido recurso de revista por violação direta da CF.", "C) Contra as decisões definitivas ou terminativas das varas e juízos cabe recurso ordinário para a instância superior, no prazo de oito dias.", "D) Nas reclamações sujeitas ao procedimento sumaríssimo, o recurso ordinário terá de ser imediatamente distribuído, devendo o relator liberá-lo no prazo máximo de trinta dias."]'::jsonb, 'C', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Determinada empresa, ao apresentar contestação em processo trabalhista, formulou pedido de concessão da justiça gratuita, alegando dificuldades financeiras, sem a devida comprovação de incapacidade, e anexou, apenas, declaração de miserabilidade firmada por seu representante legal.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Em reclamação trabalhista, o advogado do reclamante interpôs recurso ordinário contra a sentença proferida pelo juiz de primeiro grau, que julgou improcedente o pedido de condenação em horas extras formulado pelo reclamante e indeferiu a oitiva das testemunhas arroladas, por entender que o depoimento do reclamante era suficiente para o julgamento da demanda. Argumentando a tese do cerceamento de defesa, o advogado formulou pedido de anulação dos atos processuais, sem requerer expressamente a análise, pelo tribunal, das horas extras negadas. Ao se julgar o recurso ordinário no TRT, foi reconhecido o cerceamento de defesa e condenada a empresa a pagar ao reclamante as horas extras pleiteadas.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Considere que, em processo trabalhista, as empresas Delta e Echo sejam condenadas, de forma solidária, pelo juiz do trabalho, que ambas interponham recurso ordinário, que apenas Delta efetue o depósito recursal, e nenhuma delas pleiteie a exclusão da lide. Nessa situação hipotética, o recurso apresentado pela empresa Echo', '["A) será deserto, em razão de não ter sido efetuado o depósito recursal.", "B) será intempestivo, em razão de não ter sido efetuado o depósito recursal.", "C) deverá ser conhecido, mas improvido, em razão de não ter sido efetuado o depósito recursal.", "D) estará apto a ser conhecido, visto que, sendo a condenação solidária, o depósito efetuado pela empresa Delta aproveita à empresa Echo."]'::jsonb, 'D', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Em determinada reclamação trabalhista, o preposto da empresa reclamada não soube responder às perguntas formuladas pelo juiz e pelo advogado do reclamante na audiência de instrução e argumentou que não possuía conhecimento específico a respeito dos fatos que estavam sendo tratados no processo. O advogado da empresa juntou à contestação diversos documentos na audiência inaugural.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Na hipótese de um empregado desejar mover ação de reparação de perdas e danos causados pelo cálculo incorreto do benefício previdenciário por omissão ou equívoco do empregador, processamento e o julgamento da demanda competirão', '["A) à justiça do trabalho.", "B) à justiça federal.", "C) à justiça comum estadual.", "D) ao Ministério da Previdência Social."]'::jsonb, 'A', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Assinale opção correta de acordo com as normas constitucionais sobre zoneamento ambiental.', '["A) Os estados podem, por lei complementar, instituir regiões metropolitanas, aglomerações urbanas e microrregiões, com a finalidade de integrar a organização, o planejamento e a execução de funções públicas de interesse comum. Para isso, precisam da concordância dos municípios envolvidos, os quais devem aprovar leis municipais com o mesmo teor e conteúdo da lei estadual.", "B) Compete à União elaborar planos nacionais e regionais de ordenação do território e de desenvolvimento econômico e social.", "C) As zonas de uso predominantemente industrial destinam-se, preferencialmente, à localização de estabelecimentos industriais cujos resíduos sólidos, líquidos e gasosos, ruídos, vibrações e radiações possam causar danos à saúde, ao bem-estar e à segurança das populações, mesmo depois da aplicação de métodos adequados de combate e tratamento de efluentes.", "D) É da competência dos estados a promoção, no que couber, do adequado ordenamento territorial mediante planejamento e controle do uso, do parcelamento e da ocupação do solo urbano."]'::jsonb, 'B', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Relativamente à tutela penal do meio ambiente, assinale a opção correta.', '["A) Não constitui crime o abate de animal quando realizado, entre outras hipóteses, em estado de necessidade, para saciar a fome do agente ou de sua família.", "B) Constitui crime matar, perseguir, caçar, apanhar ou utilizar espécimes da fauna silvestre sem a devida permissão, licença ou autorização da autoridade competente. Tal proibição não alcança, entretanto, os espécimes em rota migratória que não sejam nativos.", "C) Comprovada a responsabilidade de pessoa jurídica na prática de crime ambiental, ficará automaticamente excluída a responsabilidade das pessoas físicas, autoras, coautoras ou partícipes do mesmo fato.", "D) Os animais ilegalmente caçados que forem apreendidos deverão ser libertados em seu habitat, não podendo ser entregues a jardins zoológicos ou a entidades similares."]'::jsonb, 'A', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'No que se refere às penas restritivas de direitos e à de multa, assinale a opção correta.', '["A) Se o condenado for reincidente, o juiz não poderá aplicar a substituição da pena privativa de liberdade, apesar de, em face de condenação anterior, a medida ser socialmente recomendável e a reincidência não se ter operado em virtude da prática do mesmo crime.", "B) A prestação de serviços à comunidade ou a entidades públicas consiste na atribuição de tarefas gratuitas ao condenado, sendo aplicável às condenações superiores a seis meses de privação da liberdade, atendidos os demais requisitos legais.", "C) A limitação de fim de semana consiste na obrigação de permanência, aos sábados, domingos e feriados, por oito horas diárias, em casa de albergado ou em outro estabelecimento adequado.", "D) A pena de multa consiste no pagamento, ao fundo penitenciário, da quantia determinada na sentença e calculada em dias-multa, sendo, no mínimo, de dez e, no máximo, de trezentos e sessenta e cinco dias-multa, a ser fixada pelo juiz, não podendo ser inferior a um trigésimo do maior salário mínimo mensal vigente ao tempo do fato, nem superior a cinco vezes esse salário."]'::jsonb, 'B', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Com relação à pena de multa, assinale a opção correta.', '["A) Transitada em julgado a sentença condenatória, a multa será considerada dívida de valor, aplicando-se-lhe as normas da legislação relativa à dívida ativa da fazenda pública, exceto no que concerne às causas interruptivas e suspensivas da prescrição, incidindo, nesse caso, as normas do CP.", "B) Sobrevindo ao condenado doença mental, é suspensa a execução da pena de multa.", "C) Transitada em julgado a sentença condenatória, a multa deverá ser paga no prazo de dez dias e será convertida em pena privativa de liberdade caso o condenado não realize o pagamento.", "D) É vedado o pagamento da pena de multa em parcelas mensais, dada a natureza jurídica de tal espécie de sanção."]'::jsonb, 'B', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Em relação à imputabilidade penal, assinale a opção correta.', '["A) Quanto à aferição da inimputabilidade, o CP adota, como regra, o critério psicológico, segundo o qual importa saber se o agente, no momento da ação ou da omissão delituosa, tem ou não condições de avaliar o caráter criminoso do fato e de orientar-se de acordo com esse entendimento.", "B) A pena poderá ser reduzida se o agente, em virtude de perturbação de saúde mental ou por desenvolvimento mental incompleto ou retardado, não for inteiramente capaz de entender o caráter ilícito do fato ou de determinar-se de acordo com esse entendimento.", "C) A pena imposta ao semi-imputável não pode ser substituída por medida de segurança.", "D) A embriaguez não acidental, seja voluntária ou culposa, completa ou incompleta, exclui a imputabilidade do agente que, ao tempo da ação ou omissão delituosa, for inteiramente incapaz de entender o caráter ilícito do fato ou de determinar-se de acordo com esse entendimento."]'::jsonb, 'B', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Com relação aos crimes contra o patrimônio, assinale a opção correta.', '["A) A conduta da vítima não é fator de distinção entre os delitos de roubo e extorsão.", "B) O crime de extorsão mediante sequestro consuma-se no momento em que o resgate é exigido, independentemente do momento da privação da liberdade da vítima.", "C) Ocorre crime de extorsão indireta quando alguém, abusando da situação de outro, exige, como garantia de dívida, documento que pode dar causa a procedimento criminal contra a vítima ou terceiro.", "D) No crime de apropriação indébita, o fato de o agente praticá-lo em razão de ofício, emprego ou profissão não interfere na imposição da pena, por se tratar de elementar do tipo."]'::jsonb, 'C', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Considere que Charles, funcionário público no exercício de suas funções, tenha desviado dolosamente valores particulares de que tinha a posse em razão do cargo. Nessa situação hipotética,', '["A) Charles praticou crime de furto, e não de peculato, haja vista que os valores de que tinha a posse em razão do cargo eram particulares, e não, públicos.", "B) se Charles reparar o dano antes do recebimento da denúncia, sua punibilidade será extinta; se o fizer posteriormente, sua pena será diminuída.", "C) a pena de Charles não seria alterada na eventualidade de ser ele ocupante de cargo em comissão de órgão da administração direta, visto que a tipificação do crime já considera o fato de ser o agente funcionário público como elementar do tipo.", "D) Charles praticou peculato-desvio, podendo eventual reparação do dano ser considerada arrependimento posterior ou circunstância atenuante genérica, a depender do momento em que for efetivada."]'::jsonb, 'D', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Assinale a opção correta acerca da pena cumprida no estrangeiro e da eficácia da sentença estrangeira.', '["A) É possível a homologação, pelo STJ, de sentença penal condenatória proferida pela justiça de outro país, para obrigar o condenado residente no Brasil à reparação do dano causado pelo crime que cometeu.", "B) A competência para a homologação de sentença estrangeira é do STF, restringindo-se a referida homologação a casos que envolvam cumprimento de pena privativa de liberdade no Brasil.", "C) Apenas nas hipóteses de infração penal de menor potencial ofensivo, admite-se que a pena cumprida no estrangeiro atenue a pena imposta, no Brasil, pelo mesmo crime.", "D) A pena cumprida no estrangeiro não atenua nem compensa a pena imposta, no Brasil, pelo mesmo crime, dado o caráter independente das justiças nacional e estrangeira."]'::jsonb, 'A', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Admite-se a suspensão condicional da pena (sursis)', '["A) em casos de condenação a pena restritiva de direito ou privativa de liberdade, desde que não superior a quatro anos.", "B) a reincidente em crime doloso, desde que a condenação anterior tenha sido exclusivamente à pena de multa.", "C) para o condenado que, na data do fato, tenha idade acima de setenta anos, desde que a pena não seja superior a dois anos.", "D) para o condenado em estado de saúde grave ou portador de doença incurável, desde que ele tenha reparado o dano."]'::jsonb, 'B', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Acerca da competência no âmbito do direito processual penal, assinale a opção correta.', '["A) Caso um policial militar cometa, em uma mesma comarca, dois delitos conexos, um cujo processo e julgamento seja de competência da justiça estadual militar e o outro, da justiça comum estadual, haverá cisão processual.", "B) Os desembargadores dos tribunais de justiça dos estados e dos tribunais regionais federais possuem prerrogativa de foro especial, devendo ser processados e julgados criminalmente no STF.", "C) A competência para processo e julgamento por crime de contrabando ou descaminho define-se pela prevenção do juízo federal do local por onde as mercadorias sejam indevidamente introduzidas no Brasil.", "D) Caso um indivíduo tenha cometido, em uma mesma comarca, dois delitos conexos, um cujo processo e julgamento seja da competência da justiça federal e o outro, da justiça comum estadual, a competência para o julgamento unificado dos dois crimes será determinada pelo delito considerado mais grave."]'::jsonb, 'A', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Maurício foi denunciado pela prática do delito de estelionato perante a 1.ª Vara Criminal de Justiça de Belo Horizonte – MG. Por entender que não havia justa causa para a ação penal, o advogado contratado pelo réu impetrou habeas corpus perante o TJ/MG, que, por maioria de votos, denegou a ordem.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Acerca da ação civil ex delicto, assinale a opção correta.', '["A) A execução da sentença penal condenatória no juízo cível é ato personalíssimo do ofendido e não se estende aos seus herdeiros.", "B) Ao proferir sentença penal condenatória, o juiz fixará valor mínimo para a reparação dos danos causados pela infração, considerando os prejuízos sofridos pelo ofendido, sem prejuízo da liquidação para apuração do dano efetivamente sofrido.", "C) Segundo o CPP, a sentença absolutória no juízo criminal impede a propositura da ação civil para reparação de eventuais danos resultantes do fato, uma vez que seria contraditório absolver o agente na esfera criminal e processá-lo no âmbito cível.", "D) O despacho de arquivamento do inquérito policial e a decisão que julga extinta a punibilidade são causas impeditivas da propositura da ação civil."]'::jsonb, 'B', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Márcio foi denunciado pelo crime de bigamia. O advogado de defesa peticionou ao juízo criminal requerendo a suspensão da ação penal, por entender que o primeiro casamento de Márcio padecia de nulidade, fato que gerou ação civil anulatória, em trâmite perante o juízo cível da mesma comarca.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Com relação aos meios de prova no processo penal, assinale a opção correta de acordo com o CPP.', '["A) Se o juiz tiver notícia da existência de documento relativo a ponto relevante da acusação ou da defesa, não poderá providenciar, independentemente de requerimento das partes, a juntada aos autos, uma vez que é mero espectador do processo, sem atuação de oficio na gestão da prova.", "B) Em regra, a testemunha não pode eximir-se da obrigação de depor. No entanto, o cônjuge do acusado à época do fato criminoso, ainda que dele se encontre separado judicialmente, pode recusar-se a testemunhar.", "C) Em regra, as partes deverão apresentar os documentos necessários à comprovação de suas alegações na primeira oportunidade que falarem nos autos, sob pena de preclusão.", "D) O procedimento de acareação só será admitido entre acusados, sendo vedada a acareação entre acusado e testemunha."]'::jsonb, 'B', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Considerando as disposições processuais penais previstas na Lei federal n.º 9.099/1995 (Lei dos Juizados Especiais), assinale a opção correta.', '["A) Os processos referentes aos juizados especiais criminais devem orientar-se pelos critérios de oralidade, documentação, simplicidade, formalidade, economia processual e celeridade, em busca, sempre que possível, da conciliação ou da transação.", "B) O juizado especial criminal, provido por juízes togados ou togados e leigos, tem competência apenas para a conciliação e o julgamento das infrações penais de menor potencial ofensivo, respeitadas as regras de conexão e continência.", "C) Na reunião de processos, perante o juízo comum ou o tribunal do júri, decorrente da aplicação das regras de conexão e continência, serão observados os institutos da transação penal, excluindo-se os da composição dos danos civis.", "D) Os atos processuais serão públicos e poderão realizar-se em horário noturno e em qualquer dia da semana, conforme dispuserem as normas de organização judiciária."]'::jsonb, 'D', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Carlos, empresário reconhecidamente bem-sucedido, foi denunciado por crime contra a ordem tributária. No curso da ação penal, seu advogado constituído renunciou ao mandato procuratório. Devidamente intimado para constituir novo advogado, Carlos não o fez, tendo o juiz nomeado defensor dativo para patrocinar sua defesa.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Considerando o que dispõe o Estatuto da Criança e do Adolescente, assinale a opção correta.', '["A) O vínculo da adoção constitui-se por sentença judicial, que será inscrita no registro civil mediante mandado, do qual se fornecerá, administrativamente, certidão somente ao adotado e aos pais, biológicos e adotivos, à vista de documentação comprobatória.", "B) É dever do Estado assegurar atendimento gratuito, em creche e pré-escola, às crianças de zero a sete anos de idade.", "C) É proibida a venda de bilhetes da Mega-Sena a crianças e adolescentes.", "D) Criança ou adolescente desacompanhados dos pais ou do responsável estão proibidos de viajar para fora da comarca onde residem, sem expressa autorização judicial."]'::jsonb, 'C', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Assinale a opção correta no que se refere à família substituta.', '["A) A colocação em família substituta ocorrerá mediante guarda, tutela, curatela ou adoção, conforme a situação jurídica da criança ou adolescente, o que só poderá ser reconhecido e determinado pelo juiz da vara da infância e da adolescência.", "B) Sempre que possível, a criança ou adolescente deverá ser previamente ouvido, e a sua opinião, devidamente considerada.", "C) Na apreciação do pedido de adoção, o grau de parentesco e a relação de afinidade ou de afetividade devem ser considerados, a fim de que sejam evitadas ou minoradas as consequências decorrentes da medida, o que não ocorre nos casos de guarda provisória e tutela, para cuja concessão o conselho tutelar considera requisito apenas a certidão de bons antecedentes da família substituta.", "D) Não se deferirá a colocação da criança ou do adolescente em família substituta à pessoa que apresente, por prazo superior a 180 dias, limitações em sua capacidade laborativa."]'::jsonb, 'B', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'O Congresso Nacional e suas respectivas Casas se reúnem anualmente para a atividade legislativa. Com relação ao sistema constitucional brasileiro, assinale a alternativa correta.', '["A) Legislatura: o período compreendido entre 2 de fevereiro a 17 de julho e 1º de agosto a 22 de dezembro.", "B) Sessão legislativa: os quatro anos equivalentes ao mandato dos parlamentares.", "C) Sessão conjunta: a reunião da Câmara dos Deputados e do Senado Federal destinada, por exemplo, a conhecer do veto presidencial e sobre ele deliberar.", "D) Sessão extraordinária: a que ocorre por convocação ou do Presidente do Senado Federal ou do Presidente da Câmara dos Deputados ou do Presidente da República e mesmo por requerimento da maioria dos membros de ambas as Casas para, excepcionalmente, inaugurar a sessão legislativa e eleger as respectivas mesas diretoras."]'::jsonb, 'C', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A obrigatoriedade ou necessidade de deliberação plenária dos tribunais, no sistema de controle de constitucionalidade brasileiro, significa que:', '["A) somente pelo voto da maioria absoluta de seus membros ou dos membros do respectivo órgão especial poderão os tribunais declarar a inconstitucionalidade de lei ou ato normativo do Poder Público.", "B) a parte legitimamente interessada pode recorrer ao respectivo Tribunal Pleno das decisões dos órgãos fracionários dos Tribunais Federais ou Estaduais que, em decisão definitiva, tenha declarado a inconstitucionalidade de lei ou ato normativo.", "C) somente nas sessões plenárias de julgamento dos Tribunais Superiores é que a matéria relativa a eventual inconstitucionalidade da lei ou ato normativo pode ser decidida.", "D) a competência do Supremo Tribunal Federal para processar e julgar toda e qualquer ação que pretenda invalidar lei ou ato normativo do Poder Público pode ser delegada a qualquer tribunal, condicionada a delegação a que a decisão seja proferida por este órgão jurisdicional delegado em sessão plenária."]'::jsonb, 'A', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A respeito do Conselho Nacional de Justiça é correto afirmar que:', '["A) é órgão integrante do Poder Judiciário com competência administrativa e jurisdicional.", "B) pode rever, de ofício ou mediante provocação, os processos disciplinares de juízes e membros de Tribunais julgados há menos de um ano.", "C) seus atos sujeitam-se ao controle do Supremo Tribunal Federal e do Superior Tribunal de Justiça.", "D) a presidência é exercida pelo Ministro do Supremo Tribunal Federal que o integra e que exerce o direito de voto em todas as deliberações submeti das àquele órgão."]'::jsonb, 'B', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Em relação aos Ministros de Estado, a Constituição do Brasil estabelece que:', '["A) como delegatários do Presidente da República, podem, desde que autorizados, extinguir cargos públicos.", "B) podem expedir instruções para a execução de leis e editarem medidas provisórias.", "C) somente os brasileiros natos poderão exercer a função.", "D) respondem, qualquer que seja a infração cometida, perante o Superior Tribunal de Justiça."]'::jsonb, 'A', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Considerando que nos termos dispostos no art. 133 da Constituição do Brasil, o advogado é indispensável à administração da justiça, sendo até mesmo inviolável por seus atos e manifestações no exercício da profissão, é correto afirmar que:', '["A) a imunidade profissional não pode sofrer restrições de qualquer natureza.", "B) nenhuma demanda judicial, qualquer que seja o órgão do Poder Judiciário pelo qual tramite, independentemente de sua natureza, objeto e partes envolvidas, pode receber a prestação jurisdicional se não houver atuação de advogado.", "C) a inviolabilidade do escritório ou local de trabalho é assegurada nos termos da lei, não sendo vedadas, contudo, a busca e a apreensão judicialmente decretadas, por decisão motivada, desde que realizada na presença de representante da OAB, salvo se esta, devidamente notificada ou solicitada, não proceder à indicação.", "D) a prisão do advogado, por motivo de exercício da profissão, somente poderá ocorrer em flagrante, mesmo em caso de crime afiançável."]'::jsonb, 'C', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Sabe-se a polêmica ainda existente na doutrina constitucionalista pátria no que se refere à eventual hierarquia da Lei Complementar sobre a Lei Ordinária. Todavia, há diferenças entre essas duas espécies normativas que podem até gerar vícios de inconstitucionalidade caso não respeitadas durante o processo legislativo.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Em relação à inovação da ordem constitucional que instituiu a nominada Súmula Vinculante, é correto afirmar que:', '["A) somente os Tribunais Superiores podem editá-la.", "B) podem ser canceladas, mas vedada a mera revisão.", "C) a proposta para edição da Súmula pode ser provocada pelos legitimados para a propositura da ação direta de inconstitucionalidade.", "D) desde que haja reiteradas decisões sobre matéria constitucional, o Supremo Tribunal Federal poderá, de ofício ou por provocação, aprovar a Súmula mediante decisão da maioria absoluta de seus membros."]'::jsonb, 'C', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Um determinado Estado-membro editou lei estabelecendo disciplina uniforme para a data de vencimento das mensalidades das instituições de ensino sediadas no seu território.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Sobre o instrumento jurídico denominado Medida Provisória que não é lei, mas tem força de lei, assinale a afirmativa correta.', '["A) A sua eficácia dura sessenta dias contados da publicação, podendo a medida ser prorrogada apenas duas vezes, ambas por igual período.", "B) Se a Medida Provisória perder eficácia por decurso de prazo ou, em caráter expresso, for rejeitada pelo Congresso Nacional, vedada será sua reedição na mesma sessão legislativa.", "C) A não apreciação pela Câmara dos Deputados e, após, pelo Senado Federal, no prazo de 45 dias contados da publicação, tem como consequência apenas o sobrestamento da deliberação dos projetos de emenda à Constituição.", "D) A edição de Medida Provisória torna prejudicado o projeto de lei que disciplina o mesmo assunto e que, a par de já aprovado pelo Congresso Nacional, está pendente de sanção ou veto do Presidente da República."]'::jsonb, 'B', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Declarando o Supremo Tribunal Federal, incidentalmente, a inconstitucionalidade de lei ou ato normativo federal em face da Constituição do Brasil, caberá', '["A) ao Procurador-Geral da República, como chefe do Ministério Público da União, expedir atos para o cumprimento da decisão pelos membros do Ministério Público Federal e dos Estados.", "B) ao Presidente da República editar decreto para tornar inválida a lei no âmbito da administração pública.", "C) ao Senado Federal suspender a execução da lei, total ou parcialmente, conforme o caso, desde que a decisão do Supremo Tribunal Federal seja definitiva.", "D) ao Advogado-Geral da União interpor o recurso cabível para impedir que a União seja compelida a cumprir a referida decisão."]'::jsonb, 'C', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A doutrina costuma afirmar que certas prerrogativas postas à Administração encerram verdadeiros poderes, que são irrenunciáveis e devem ser exercidos sempre que o interesse público clamar. Por tal razão são chamados poder-dever. A esse respeito é correto afirmar que:', '["A) o poder regulamentar é amplo, e permite, sem controvérsias, a edição de regulamentos autônomos e executórios.", "B) o poder disciplinar importa à administração o dever de apurar infrações e aplicar penalidades, mesmo não havendo legislação prévia.", "C) o poder de polícia se coloca discricionário, conferindo ao administrador ilimitada margem de opções quanto à sanção a ser, eventualmente, aplicada.", "D) o poder hierárquico é inerente à ideia de verticalização administrativa, e revela as possibilidades de controlar atividades, delegar competência, avocar competências delegáveis e invalidar atos, dentre outros."]'::jsonb, 'D', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Em determinado procedimento administrativo disciplinar, a Administração federal impôs, ao servidor, a pena de advertência, tendo em vista a comprovação de ato de improbidade. Inconformado, o servidor recorre, vindo a Administração, após lhe conferir o direito de manifestação, a lhe impor a pena de demissão, nos termos da Lei nº 8112/90 e da Lei 9784/98.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Acerca do tombamento, como uma das formas de o Estado intervir na propriedade privada, os proprietários passam a ter obrigações negativas que estão relacionadas nas alternativas a seguir, à exceção de uma. Assinale-a.', '["A) Os proprietários são obrigados a colocar os seus imóveis tombados à disposição da Administração Pública para que possam ser utilizados como repartições públicas, quando da necessidade imperiosa de utilização, afim de suprir a prestação de serviços pelo Estado de forma eficiente.", "B) Os proprietários são obrigados a suportar a fiscalização dos órgãos administrativos competentes.", "C) Os proprietários não podem destruir, demolir ou mutilar o bem imóvel e somente poderão restaurá-lo, repará-lo ou pintá-lo após a obtenção de autorização especial do órgão administrativo competente.", "D) Os proprietários não podem alienar os bens, ressalvada a possibilidade de transferência para uma entidade pública."]'::jsonb, 'A', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'O poder de polícia, conferindo a possibilidade de o Estado limitar o exercício da liberdade ou das faculdades de proprietário, em prol do interesse público', '["A) gera a possibilidade de cobrança, como contrapartida, de preço público.", "B) se instrumentaliza sempre por meio de alvará de autorização.", "C) afasta a razoabilidade, para atingir os seus objetivos maiores, em prol da predominância do interesse público.", "D) deve ser exercido nos limites da lei, gerando a possibilidade de cobrança de taxa."]'::jsonb, 'D', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'No Direito Público brasileiro, o grau de autonomia das Agências Reguladoras é definido por uma independência', '["A) administrativa total e absoluta, uma vez que a Constituição da República de 1988 não lhes exige qualquer liame, submissão ou controle administrativo dos órgãos de cúpula do Poder Executivo.", "B) administrativa mitigada, uma vez que a própria lei que cria cada uma das Agências Reguladoras define e regulamenta as relações de submissão e controle, fundado no poder de supervisão dos Ministérios a que cada uma se encontra vinculada, em razão da matéria, e na superintendência atribuída ao chefe do Poder Executivo, como chefe superior da Administração Pública.", "C) legislativa total e absoluta, visto que gozam de poder normativo regulamentar, não se sujeitando assim às leis emanadas pelos respectivos Poderes legislativos de cada ente da federação brasileira.", "D) política decisória, pois não estão obrigadas a seguir as decisões de políticas públicas adotadas pelos Poderes do Estado (executivo e legislativo)."]'::jsonb, 'B', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Nas hipóteses de desapropriação, em regra geral, os requisitos constitucionais a serem observados pela Administração Pública são os seguintes:', '["A) comprovação da necessidade ou utilidade pública ou de interesse social; pagamento de indenização prévia ao ato de imissão na posse pelo Poder Público, e que seja justa e em dinheiro; e observância de ato administrativo, sem contraditório por parte do proprietário.", "B) comprovação da necessidade ou utilidade pública ou de interesse social; pagamento de indenização prévia ao ato de imissão na posse pelo Poder Público, e que seja justa e em dinheiro; e observância de procedimento administrativo, com respeito ao contraditório e ampla defesa por parte do proprietário.", "C) comprovação da necessidade ou utilidade pública ou de interesse social; pagamento de indenização prévia ao ato de imissão na posse pelo Poder Público, e que seja justa e em títulos da dívida pública ou quaisquer outros títulos públicos, negociáveis no mercado financeiro; e observância de procedimento administrativo, com respeito ao contraditório e ampla defesa por parte do proprietário.", "D) comprovação da necessidade ou utilidade pública ou de interesse social; pagamento de indenização, posteriormente ao ato de imissão na posse pelo Poder Público, e que seja justa e em dinheiro; e observância de procedimento administrativo, com respeito ao contraditório e ampla defesa por parte do proprietário."]'::jsonb, 'B', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Uma das características dos contratos administrativos é a “instabilidade” quanto ao seu objeto que decorre', '["A) do poder conferido à Administração Pública de alterar, unilateralmente, algumas cláusulas do contrato, no curso de sua execução, na forma do artigo 58, inciso I da Lei n. 8.666/93, a fim de adequar o objeto do contrato às finalidades de interesse público, respeitados os direitos do contratado.", "B) da possibilidade do contratado (particular) alterar, unilateralmente, a qualquer tempo, algumas cláusulas do contrato, no curso de sua execução, de forma a atender aos seus próprios interesses em face das prerrogativas da Administração Pública.", "C) do poder conferido à Administração Pública de alterar, unilateralmente, algumas cláusulas do contrato, no curso de sua execução, na forma do artigo 58, inciso I da Lei n. 8.666/93, afim de adequar o objeto do contrato aos interesses do contratado (particular) em face das prerrogativas da Administração Pública.", "D) de não haver qualquer possibilidade de alteração do objeto do contrato administrativo, quer pela Administração Pública, quer pelo contratado (particular), tendo em vista o princípio da vinculação ao edital licitatório, do qual o contrato e seu objeto fazem parte integrante; e o princípio da juridicidade, do qual aquele primeiro decorre."]'::jsonb, 'A', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Determinada Administração Pública realiza concurso para preenchimento de cargos de detetive, categoria I. Ao final do certame, procede à nomeação e posse de 400 (quatrocentos) aprovados. Os vinte primeiros classificados são desviados de suas funções e passam a exercer as atividades de delegado. Com o transcurso de 4 (quatro) anos, estes vinte agentes postulam a efetivação no cargo.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'No âmbito do Poder discricionário da Administração Pública, não se admite que o agente público administrativo exerça o Poder discricionário', '["A) quando estiver diante de conceitos legais e jurídicos parcialmente indeterminados, que se tornam determinados à luz do caso concreto e à luz das circunstâncias de fato.", "B) quando estiver diante de conceitos legais e jurídicos técnico-científicos, sendo, neste caso, limitado às escolhas técnicas, por óbvio possíveis.", "C) quando estiver diante de conceitos valorativos estabelecidos pela lei, que dependem de concretização pelas escolhas do agente, considerados o momento histórico e social.", "D) em situações em que a redação da Lei se encontra insatisfatória ou ultrapassada."]'::jsonb, 'D', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Uma determinada empresa concessionária transfere o seu controle acionário para uma outra empresa privada, sem notificar, previamente, o Poder concedente, parte no contrato de concessão.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A respeito das diferenças e semelhanças entre prescrição e decadência, no Código Civil, é correto afirmar que:', '["A) a prescrição acarreta a extinção do direito potestativo, enquanto a decadência gera a extinção do direito subjetivo.", "B) os prazos prescricionais podem ser suspensos e interrompidos, enquanto os prazos decadenciais legais não se suspendem ou interrompem, com exceção da hipótese de titular de direito absolutamente incapaz, contra o qual não corre nem prazo prescricional nem prazo decadencial.", "C) não se pode renunciar à decadência legal nem à prescrição, mesmo após consumadas.", "D) a prescrição é exceção que deve ser alegada pela parte a quem beneficia, enquanto a decadência pode ser declarada de ofício pelo juiz."]'::jsonb, 'B', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Com relação ao regime da solidariedade passiva, é correto afirmar que:', '["A) cada herdeiro pode ser demandado pela dívida toda do devedor solidário falecido.", "B) com a perda do objeto por culpa de um dos devedores solidários, a solidariedade subsiste no pagamento do equivalente pecuniário, mas pelas perdas e danos somente poderá ser demandado o culpado.", "C) se houver atraso injustificado no cumprimento da obrigação por culpa de um dos devedores solidários, a solidariedade subsiste no pagamento do valor principal, mas pelos juros da mora somente poderá ser demandado o culpado.", "D) as exceções podem ser aproveitadas por qualquer dos devedores solidários, ainda que sejam pessoais apenas a um deles."]'::jsonb, 'B', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Durante dez anos, empregados de uma fabricante de extrato de tomate distribuíram, gratuitamente, sementes de tomate entre agricultores de uma certa região. A cada ano, os empregados da fabricante procuravam os agricultores, na época da colheita, para adquirir a safra produzida. No ano de 2009, a fabricante distribuiu as sementes, como sempre fazia, mas não retornou para adquirir a safra. Procurada pelos agricultores, a fabricante recusou-se a efetuar a compra. O tribunal competente entendeu que havia responsabilidade pré-contratual da fabricante. A responsabilidade pré-contratual é aquela que:', '["A) deriva da violação à boa-fé objetiva na fase das negociações preliminares à formação do contrato.", "B) deriva da ruptura de um pré-contrato, também chamado contrato preliminar.", "C) surgiu, como instituto jurídico, em momento histórico anterior à responsabilidade contratual.", "D) segue o destino da responsabilidade contratual, como o acessório segue o principal."]'::jsonb, 'A', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Em 2004, Joaquim, que não tinha herdeiros necessários, lavrou um testamento contemplando como sua herdeira universal Ana. Em 2006, arrependido, Joaquim revogou o testamento de 2004, nomeando como seu herdeiro universal Sérgio. Em 2008, Sérgio faleceu, deixando uma filha Catarina. No mês de julho de 2010, faleceu Joaquim. O único parente vivo de Joaquim era seu irmão, Rubens.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Sobre o constituto possessório, assinale a alternativa correta.', '["A) Trata-se de modo originário de aquisição da propriedade.", "B) Trata-se de modo originário de aquisição da posse.", "C) Representa uma tradição ficta.", "D) É imprescindível para que se opere a transferência da posse aos herdeiros na sucessão universal."]'::jsonb, 'C', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Passando por dificuldades financeiras, Alexandre instituiu uma hipoteca sobre imóvel de sua propriedade, onde reside com sua família. Posteriormente, foi procurado por Amanda, que estaria disposta a adquirir o referido imóvel por um valor bem acima do mercado. Consultando seu advogado, Alexandre ouviu dele que não poderia alienar o imóvel, já que havia uma cláusula na escritura de instituição da hipoteca que o proibia de alienar o bem hipotecado.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Jane e Carlos constituíram uma união estável em julho de 2003 e não celebraram contrato para regular as relações patrimoniais decorrentes da aludida entidade familiar. Em março de 2005, Jane recebeu R$ 100.000,00 (cem mil reais) a título de doação de seu ti o Túlio. Com os R$ 100.000,00 (cem mil reais), Jane adquiriu em maio de 2005 um imóvel na Barra da Tijuca. Em 2010, Jane e Carlos se separaram. Carlos procura um advogado, indagando se tem direito a partilhar o imóvel adquirido por Jane na Barra da Tijuca em maio de 2005.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Por meio de uma promessa de compra e venda, celebrada por instrumento particular registrada no cartório de Registro de Imóveis e na qual não se pactuou arrependimento, Juvenal foi residir no imóvel objeto do contrato e, quando quitou o pagamento, deparou-se com a recusa do promitente-vendedor em outorgar-lhe a escritura definitiva do imóvel. Diante do impasse, Juvenal poderá', '["A) requerer ao juiz a adjudicação do imóvel, a despeito de a promessa de compra e venda ter sido celebrada por instrumento particular.", "B) usucapir o imóvel, já que não faria jus à adjudicação compulsória na hipótese.", "C) desisti r do negócio e pedir o dinheiro de volta.", "D) exigir a substituição do imóvel prometi do à venda por outro, muito embora inexistisse previsão expressa a esse respeito no contrato preliminar."]'::jsonb, 'A', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'João prometeu transferir a propriedade de uma coisa certa, mas antes disso, sem culpa sua, o bem foi deteriorado. Segundo o Código Civil, ao caso de João aplica-se o seguinte regime jurídico:', '["A) a obrigação fica resolvida, com a devolução de valores eventualmente pagos.", "B) a obrigação subsiste, com a entrega da coisa no estado em que se encontra.", "C) a obrigação subsiste, com a entrega da coista no estado em que se encontra e abati mento no preço proporcional à deterioração.", "D) a obrigação poderá ser resolvida, com a devolução de valores eventualmente pagos, ou subsisti r, com a entrega da coisa no estado em que se encontra e abati mento no preço proporcional à deterioração, cabendo ao credor a escolha de uma dentre as duas soluções."]'::jsonb, 'D', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Assinale a alternativa que contemple exclusivamente obrigação propter rem:', '["A) a obrigação de indenizar decorrente da aluvião e aquela decorrente da avulsão.", "B) a hipoteca e o dever de pagar as cotas condominiais.", "C) o dever que tem o servidor da posse de exercer o desforço possessório e o dever de pagar as cotas condominiais.", "D) a obrigação que tem o proprietário de um terreno de indenizar o terceiro que, de boa-fé, erigiu benfeitorias sobre o mesmo."]'::jsonb, 'D', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A capacidade é um dos pressupostos processuais. Caso o juiz verifique que uma das partes é incapaz ou há irregularidade em sua representação, deverá suspender o processo e marcar prazo razoável para que o defeito seja sanado.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A incompetência do juízo, tal como prevista no CPC, pode assumir duas feições, de acordo com a natureza do vício e ainda com as consequências advindas de tal reconhecimento. O Código trata, então, da incompetência absoluta e da relativa. A respeito dessas modalidades de incompetência, assinale a afirmativa correta.', '["A) A incompetência relativa pode ser alegada a qualquer tempo.", "B) A incompetência relativa sempre pode ser conhecida de ofício pelo juiz.", "C) A incompetência absoluta gera a nulidade de todos os atos praticados no processo até seu reconhecimento.", "D) A incompetência absoluta é alegada como preliminar da contestação ou por petição nos autos."]'::jsonb, 'D', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Com relação ao procedimento da execução por quantia certa, contra devedor solvente, fundado em título extrajudicial, é correto afirmar que:', '["A) o executado é citado para, no prazo de três dias, apresentar embargos.", "B) o credor só pode indicar os bens a serem penhorados se o executado não se manifestar no prazo legal, após ser citado.", "C) o juiz pode, de ofício, e a qualquer tempo, determinar a intimação do executado para indicar bens passíveis de penhora.", "D) o juiz somente fixará os honorários de advogado a serem pagos pelo executado ao fim do processo de execução."]'::jsonb, 'C', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'As medidas cautelares estão expressamente previstas no CPC como forma de instrumentalizar a tutela, tendo natureza eminentemente acessória.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A Lei n. 9.099/95 disciplina os chamados Juizados Especiais Cíveis no âmbito Estadual. Nela é possível encontrar diversas regras especiais, que diferenciam o procedimento dos Juizados do procedimento comum do CPC.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'O Mandado de Segurança Coletivo, previsto no art. 5º, inciso LXX da Constituição da República, foi regulamentado pelos artigos 21 e 22 da Lei Federal n. 12.016/09.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Acerca da revelia, é correto afirmar que:', '["A) a revelia se dá com a não apresentação de exceção ou de reconvenção no prazo da resposta.", "B) ainda que o litígio verse sobre direitos indisponíveis, a revelia produz seus efeitos normalmente.", "C) contra o revel, ainda que tenha patrono constituído nos autos, correrão os prazos independentemente de intimação.", "D) o revel pode intervir no processo em qualquer fase, recebendo-o no estado em que se encontrar."]'::jsonb, 'D', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Se, durante a audiência de instrução e julgamento, um advogado, exercendo seu mister de bem defender os interesses de seu cliente, entende que a testemunha arrolada pela parte contrária mantém com essa vínculo estreito de amizade e que seu depoimento pode ser tendencioso, esse advogado deverá:', '["A) contraditar a testemunha, devendo a audiência, nesse caso, ser necessária e imediatamente interrompida.", "B) contraditar a testemunha, que mesmo assim poderá ser ouvida como informante do juízo, desde que o magistrado fundamente sua decisão de ouví-la.", "C) contraditar a testemunha, hipótese em que estará o juiz obrigado a dispensá-la.", "D) contraditar a testemunha, que será ouvida após a audiência, sem a presença das partes."]'::jsonb, 'B', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Com relação ao procedimento da curatela dos interditos, é correto afirmar que:', '["A) na ausência dos pais, do tutor e do cônjuge, um parente próximo pode requerer a interdição.", "B) a sentença proferida pelo juiz faz coisa julgada material.", "C) a realização de prova pericial, consistente no exame do interditando, é facultativa, podendo o juiz dispensá-la.", "D) o Ministério Público não tem legitimidade para requerer a interdição."]'::jsonb, 'A', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Um advogado é procurado em seu escritório por um cliente que lhe narra que a empresa da qual ele é diretor foi citada pelo poder judiciário, em decorrência de um conflito surgido em razão de contrato de compra e venda no qual inseriram cláusula compromissória cheia, estabelecendo que em caso de eventual conflito entre as partes, o mesmo será apreciado por um tribunal arbitral.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A respeito do regime de compensação de jornada do banco de horas, assinale a alternativa correta.', '["A) Pode ser instituído mediante acordo, verbal ou por escrito, entre empresa e empregado, facultando-se a participação dos sindicatos representantes das categorias.", "B) Não admite compensação de jornada que ultrapassar o limite máximo de 10 horas diárias.", "C) Pode ser compensado após a rescisão do contrato de trabalho, se houver crédito em favor do trabalhador, respeitado o limite de validade do acordo.", "D) O excesso de jornada a ser compensada não pode exceder, no prazo legal máximo de um semestre, a soma das jornadas semanais previstas para o período."]'::jsonb, 'B', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'No contexto da teoria das nulidades do contrato de trabalho, assinale a alternativa correta.', '["A) Configurado o trabalho ilícito, é devido ao empregado somente o pagamento da contraprestação salarial pactuada.", "B) Os trabalhos noturno, perigoso e insalubre do menor de 18 dezoito) anos de idade são modalidades de trabalho proibido ou irregular.", "C) O trabalho do menor de 16 (dezesseis) anos de idade, que não seja aprendiz, é modalidade de trabalho ilícito, não gerando qualquer efeito.", "D) A falta de anotação da Carteira de Trabalho e Previdência Social do empregado invalida o contrato de trabalho."]'::jsonb, 'B', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Com relação ao Direito Coletivo do Trabalho, assinale a alternativa correta.', '["A) Acordo coletivo do trabalho é o acordo de caráter normativo pelo qual dois ou mais sindicatos representativos de categorias econômicas e profissionais estipulam condições de trabalho aplicáveis, no âmbito das respectivas representações, às relações individuais de trabalho.", "B) Na greve em serviços ou atividades essenciais, ficam as entidades sindicais ou os trabalhadores, conforme o caso, obrigados a comunicar a decisão aos empregadores e aos usuários com antecedência mínima de 72 (setenta e duas) horas da paralisação.", "C) As centrais sindicais, por força de lei, podem celebrar acordos e convenções coletivos de trabalho.", "D) O recolhimento da contribuição sindical obrigatória (“imposto sindical”) somente é exigido dos empregados sindicalizados, em face do princípio da liberdade sindical."]'::jsonb, 'B', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'O empregado João foi contratado para trabalhar como caixa de um supermercado. No ato de admissão, foi-lhe entregue o regulamento da empresa, onde constava a obrigatoriedade do uso do uniforme para o exercício do trabalho. Entretanto, cerca de cinco meses após a contratação, João compareceu para trabalhar sem o uniforme e, por isso, foi adverti do. Um mês depois, o fato se repeti u e João foi suspenso por 3 dias. Passados mais 2 meses, João compareceu novamente sem uniforme, tendo sido suspenso por 30 dias. Ao retornar da suspensão foi encaminhado ao departamento de pessoal, onde tomou ciência da sua dispensa por justa causa (indisciplina – art. 482, h da CLT).
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Com relação ao regime de férias, é correto afirmar que:', '["A) as férias devem ser pagas ao empregado com adicional de 1/3 até 30 dias antes do início do seu gozo.", "B) salvo para as gestantes e os menores de 18 anos, as férias podem ser gozadas em dois períodos.", "C) o empregado que pede demissão antes de completado seu primeiro período aquisitivo faz jus a férias proporcionais.", "D) as férias podem ser converti das integralmente em abono pecuniário, por opção do empregado."]'::jsonb, 'C', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Marcos foi contratado para o cargo de escriturário de um banco privado. Iniciada sua atividade, Marcos percebeu que o gerente lhe estava repassando tarefas alheias à sua função. A rigor, conforme constava do quadro de carreira da empresa devidamente registrado no Ministério do Trabalho e Emprego, as atribuições que lhe estavam sendo exigidas deveriam ser destinadas ao cargo de tesoureiro, cujo nível e cuja remuneração eram bem superiores.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Joana foi contratada para trabalhar de segunda a sábado na residência do Sr. Demétrius, de 70 anos, como sua acompanhante, recebendo salário mensal.  Ao exato término do terceiro mês de prestação de serviços, o Sr. Demétrius descobre que a Sra. Joana está grávida, rescindindo a prestação de serviços.  Joana, inconformada, ajuíza ação trabalhista para que lhe seja reconhecida a condição de empregada doméstica e garanti do o seu emprego mediante reconhecimento da estabilidade provisória pela gestação. Levando-se em consideração a situação de Joana, assinale a alternativa correta.', '["A) A função de acompanhante é incompatível com o reconhecimento de vínculo de emprego doméstico.", "B) Joana faz jus ao reconhecimento de vínculo de emprego como empregada doméstica.", "C) Joana não fará jus à estabilidade gestacional, pois este não é um direito garanti do à categoria dos empregados domésticos.", "D) Joana não fará jus à estabilidade gestacional, pois o contrato de três meses é automaticamente considerado de experiência para o Direito do Trabalho e pode ser rescindido ao atingir o seu termo final."]'::jsonb, 'B', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Paulo, empregado de uma empresa siderúrgica, sofreu acidente do trabalho, entrando em gozo de auxílio-doença acidentário, a partir do décimo sexto dia de seu afastamento. Durante este período de percepção do benefício previdenciário, ele foi dispensado sem justa causa por seu empregador.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Com relação às provas no processo do trabalho, assinale a alternativa correta.', '["A) As testemunhas devem ser necessariamente arroladas pelas partes dentro do prazo estabelecido pelo juiz, a fim de que sejam notificadas para comparecimento à audiência.", "B) Cada uma das partes não pode indicar mais de três testemunhas, inclusive nas causas sujeitas ao procedimento sumaríssimo, salvo quando se tratar de inquérito para apuração de falta grave, caso em que este número pode ser elevado a seis.", "C) Na hipótese de deferimento de prova técnica, é vedada às partes a apresentação de peritos assistentes.", "D) Nas causas sujeitas ao procedimento sumaríssimo, somente quando a prova do fato o exigir, ou for legalmente imposta, será deferida prova técnica, incumbindo ao juiz, desde logo, fixar o prazo, o objeto da perícia e nomear perito."]'::jsonb, 'D', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Com relação às despesas processuais na Justiça do Trabalho, assinale a afirmativa correta.', '["A) As entidades fiscalizadoras do exercício profissional, em face de sua natureza autárquica, são isentas do pagamento de custas.", "B) As custas devem ser pagas pelo vencido, após o trânsito em julgado da decisão. No caso de recurso, estas devem ser pagas e comprovado o recolhimento dentro do prazo recursal.", "C) O benefício da gratuidade de justiça não pode ser concedido de ofício pelo juiz, devendo ser necessariamente requerido pela parte interessada.", "D) A responsabilidade pelo pagamento dos honorários periciais é da parte sucumbente na pretensão objeto da perícia, ainda que beneficiária da gratuidade de justiça."]'::jsonb, 'B', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Com relação à execução trabalhista, assinale a afirmativa correta.', '["A) A execução deve ser impulsionada pela parte interessada, sendo vedado ao juiz promovê-la de ofício.", "B) O termo de compromisso de ajustamento de conduta firmado perante o Ministério Público do Trabalho, para que possa ser executado no processo do trabalho, depende de prévia homologação pelo juiz que teria competência para o processo de conhecimento relativo à matéria.", "C) Conforme disposição expressa na Consolidação das Leis do Trabalho, considera-se inexigível o título judicial fundado em lei ou ato normativo declarados inconstitucionais pelo Supremo Tribunal Federal ou em aplicação ou interpretação ti das por incompatíveis com a Constituição Federal.", "D) Garanti da a execução ou penhorados os bens, é de 10 (dez) dias o prazo para o executado apresentar embargos à execução, cabendo igual prazo ao exequente para impugnação."]'::jsonb, 'C', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Assinale a alternativa que apresente requisitos intrínsecos genéricos de admissibilidade recursal.', '["A) Capacidade, legitimidade e interesse.", "B) Preparo, interesse e representação processual.", "C) Representação processual, preparo e tempestividade.", "D) Legitimidade, tempestividade e preparo."]'::jsonb, 'A', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Pedro ajuizou ação em face de seu empregador objetivando a satisfação dos pedidos de horas extraordinárias, suas integrações e consectárias. O seu pedido foi julgado improcedente. Recorre ordinariamente, pretendendo a substituição da decisão por outra de diverso teor, tempestivamente.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Segundo a legislação e a jurisprudência sobre a ação rescisória no Processo do Trabalho, assinale a afirmativa correta.', '["A) A decisão que extingue o processo sem resolução de mérito, uma vez transitada em julgado, é passível de corte rescisório.", "B) É ajuizada independente de depósito prévio, em razão da previsão específica do Processo do Trabalho.", "C) Quando for de competência originária de Tribunal Regional do Trabalho, admitirá o recurso de revista para o Tribunal Superior do Trabalho.", "D) A sentença de mérito proferida por prevaricação, concussão ou corrupção do juiz, uma vez transitada em julgado, é passível de corte rescisório."]'::jsonb, 'D', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'No dia 23.05.2003, Paulo apresentou reclamação verbal perante o distribuidor do fórum trabalhista, o qual, após livre distribuição, o encaminhou para a 132ª Vara do Trabalho do Rio de Janeiro. Entretanto, Paulo mudou de ideia e não compareceu à secretaria da Vara para reduzi-la a termo. No dia 24.12.2003, Paulo retornou ao distribuidor da Justiça do Trabalho e, decidido, apresentou novamente a sua reclamação verbal, cuja livre distribuição o encaminhou para a 150ª Vara do Trabalho do Rio de Janeiro. Desta vez, o trabalhador se dirigiu à secretaria da Vara, reduziu a reclamação a termo e saiu de lá ciente de que a audiência inaugural seria no dia 01.02.2004. Contudo, ao chegar o dia da audiência, Paulo mudou de ideia mais uma vez e não compareceu, gerando o arquivamento dos autos.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Com relação ao concurso de delitos, é correto afirmar que:', '["A) no concurso de crimes as penas de multa são aplicadas distintamente, mas de forma reduzida.", "B) o concurso material ocorre quando o agente, mediante mais de uma ação ou omissão, pratica dois ou mais crimes com dependência fática e jurídica entre estes.", "C) o concurso formal perfeito, também conhecido como próprio, ocorre quando o agente, por meio de uma só ação ou omissão, pratica dois ou mais crimes idênticos, caso em que as penas serão somadas.", "D) o Código Penal Brasileiro adotou o sistema de aplicação de pena do cúmulo material para os concursos material e formal imperfeito, e da exasperação para o concurso formal perfeito e crime continuado."]'::jsonb, 'D', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Paula Rita convenceu sua mãe adotiva, Maria Aparecida, de 50 anos de idade, a lhe outorgar um instrumento de mandato para movimentar sua conta bancária, ao argumento de que poderia ajudá-la a efetuar pagamento de contas, pequenos saques, pegar talões de cheques etc., evitando assim que a mesma tivesse que se deslocar para o banco no dia a dia. De posse da referida procuração, Paula Rita compareceu à agência bancária onde Maria Aparecida possuía conta e sacou todo o valor que a mesma possuía em aplicações financeiras, no total de R$ 150.000,00 (cento e cinquenta mil reais), apropriando-se do dinheiro antes pertencente a sua mãe. Considerando tal narrativa, assinale a alternativa correta.', '["A) Paula Rita praticou crime de estelionato em detrimento de Maria Aparecida e, pelo fato de ser sua filha adotiva, é isenta de pena.", "B) Paula Rita praticou crime de furto mediante fraude em detrimento de Maria Aparecida e, pelo fato de ser sua filha adotiva, é isenta de pena.", "C) Paula Rita praticou crime de estelionato em detrimento de Maria Aparecida e, apesar de ser sua filha adotiva, não é isenta de pena.", "D) Paula Rita praticou crime de furto mediante fraude em detrimento de Maria Aparecida e, apesar de seu sua filha adotiva, não é isenta de pena."]'::jsonb, 'A', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A respeito do regime legal da prescrição no Código Penal, tendo por base ocorrência do fato na data de hoje, assinale a alternativa correta.', '["A) A prescrição, depois da sentença condenatória com trânsito em julgado para a acusação, regula-se pela pena aplicada, não podendo, em nenhuma hipótese, ter por termo inicial data anterior à da denúncia ou queixa.", "B) A prescrição da pena de multa ocorrerá em 2 (dois) anos, independentemente do prazo estabelecido para a prescrição da pena de liberdade aplicada cumulativamente.", "C) Se o réu citado por edital permanece revel e não constitui advogado, fica suspenso o processo, mantendo-se em curso o prazo prescricional, que passa a ser computado pelo dobro da pena máxima cominada ao crime.", "D) São causas interruptivas do curso da prescrição previstas no Código Penal, dentre outras, o recebimento da denúncia ou da queixa, a pronúncia, a publicação da sentença condenatória ou absolutória recorrível."]'::jsonb, 'A', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Assinale a alternativa que preencha corretamente as lacunas do texto:
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Arlete, em estado puerperal, manifesta a intenção de matar o próprio filho recém nascido. Após receber a criança no seu quarto para amamentá-la, a criança é levada para o berçário. Durante a noite, Arlete vai até o berçário, e, após conferir a identificação da criança, a asfixia, causando a sua morte. Na manhã seguinte, é constatada a morte por asfixia de um recém nascido, que não era o filho de Arlete.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Relativamente à legislação sobre lavagem de capitais (Lei n. 9.613/98), assinale a alternativa correta.', '["A) O crime de lavagem só ocorre quando os bens, direitos ou valores provenientes, direta ou indiretamente, de um dos crimes antecedentes completam todo o processo de lavagem ocultação, dissimulação e integração).", "B) Não constitui lavagem de dinheiro, mas crime de descaminho, a importação ou exportação de bens com valores não correspondentes aos verdadeiros, feita com o propósito de ocultar ou dissimular a utilização de bens, direitos ou valores provenientes de qualquer dos crimes antecedentes referidos na Lei n. 9.613/98.", "C) O processo e julgamento dos crimes previstos na Lei n. 9613/98 dependem do processo e julgamento dos crimes antecedentes.", "D) Pratica crime de lavagem de dinheiro quem utiliza, na atividade econômica ou financeira, bens, direitos ou valores que sabe serem provenientes de qualquer dos crimes antecedentes previstos na Lei n. 9613/98."]'::jsonb, 'D', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Fundação Pública Federal contrata o técnico de informática Abelardo Fonseca para que opere o sistema informatizado destinado à elaboração da folha de pagamento de seus funcionários. Abelardo, ao elaborar a referida folha de pagamento, altera as informações sobre a remuneração dos funcionários da Fundação no sistema, descontando a quantia de cinco reais de cada um deles. A seguir, insere o seu próprio nome e sua própria conta bancária no sistema, atribuindo-se a condição de funcionário da Fundação e destina à sua conta o total dos valores desviados dos demais. Terminada a elaboração da folha, Abelardo remete as informações à seção de pagamentos, a qual efetua os pagamentos de acordo com as informações lançadas no sistema por ele.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'João da Silva, José da Silva e Maria da Silva são os acionistas controladores do Banco Silva’s e Família, cada um com 30% das ações com direito a voto e exercendo respectivamente os cargos de Diretor-Presidente, Diretor Comercial e Diretora de Contabilidade. Em razão das dificuldades financeiras que afetaram o Banco Silva’s e Família, os diretores decidem por em curso as seguintes práticas: (1) adquirir no mercado títulos do tesouro nacional já caducos (portanto sem valor algum) e, utilizando-os como simulacro de lastro, emitir títulos do banco para captar recursos financeiros junto aos investi dores; 2) forjar negócios com pessoas jurídicas inexistentes a fim de simular ganhos; e, por fim, (3) fraudar o balanço da instituição simulando lucros no exercício ao invés dos prejuízos efetivamente sofridos.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'João da Silva foi denunciado por homicídio qualificado por motivo fútil. Nos debates orais ocorridos na primeira fase do procedimento de júri, a Defesa alegou que João agira em estrito cumprimento de dever legal, postulando sua absolvição sumária. Ao proferir sua decisão, o juiz rejeitou a tese de estrito cumprimento de dever legal e o pedido de absolvição sumária, e pronunciou João por homicídio simples, afastando a qualificadora contida na denúncia. A decisão de pronúncia foi confirmada pelo Tribunal de Justiça, operando-se a preclusão.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Em uma briga de bar, Joaquim feriu Pedro com uma faca, causando-lhe sérias lesões no ombro direito. O promotor de justiça ofereceu denúncia contra Joaquim, imputando-lhe a prática do crime de lesão corporal grave contra Pedro, e arrolou duas testemunhas que presenciaram o fato. A defesa, por sua vez, arrolou outras duas testemunhas que também presenciaram o fato.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Em processo sujeito ao rito ordinário, ao apresentar resposta escrita, o advogado requer a absolvição sumária de seu cliente e não propõe provas. O juiz, rejeitando o requerimento de absolvição sumária, designa audiência de instrução e julgamento, destinada à inquirição das testemunhas arroladas pelo Ministério Público e ao interrogatório do réu. Ao final da audiência, o advogado requer a oitiva de duas testemunhas de defesa e que o juiz designe nova data para que sejam inquiridas.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Antônio Ribeiro foi denunciado pela prática de homicídio qualificado, pronunciado nos mesmos moldes da denúncia e submeti do a julgamento pelo Tribunal do Júri em 25/05/2005, tendo sido condenado à pena de 15 anos de reclusão em regime integralmente fechado. A decisão transita em julgado para o Ministério Público, mas a defesa de Antônio apela, alegando que a decisão dos Jurados é manifestamente contrária à prova dos autos. A apelação é provida, sendo o réu submeti do a novo Júri. Neste segundo Júri, Antônio é novamente condenado e sua pena é agravada, mas fixado regime mais vantajoso (inicial fechado).
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Relativamente às regras sobre ação civil fixadas no Código de Processo Penal, assinale a alternativa correta.', '["A) São fatos que impedem a propositura da ação civil: o despacho de arquivamento do inquérito ou das peças de informação, a decisão que julgar extinta a punibilidade e a sentença absolutória que decidir que o fato imputado não constitui crime.", "B) Sobrevindo a sentença absolutória no juízo criminal, a ação civil não poderá ser proposta em nenhuma hipótese.", "C) Transitada em julgado a sentença penal condenatória, a execução só poderá ser efetuada pelo valor fixado na mesma, não se admitindo, neste caso, a liquidação para a apuração do dano efetivamente sofrido.", "D) Transitada em julgado a sentença penal condenatória, poderão promover-lhe a execução, no juízo cível, para o efeito da reparação do dano, o ofendido, seu representante legal ou seus herdeiros."]'::jsonb, 'D', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'João foi denunciado pela prática do crime de furto (CP, art. 155), pois segundo narra a denúncia ele subtraiu colar de pedras preciosas da vítima. No decorrer da instrução processual, a testemunha Antônio relata fato não narrado na denúncia: a subtração do objeto furtado se deu mediante “encontrão” dado por João no corpo da vítima. Na fase de sentença, sem antes tomar qualquer providência, o Juiz decide, com base no sobredito testemunho de Antônio, condenar João nas penas do crime de roubo (CP, art. 157), por entender que o “encontrão” relatado caracteriza emprego de violência contra a vítima. A sentença condenatória transita em julgado para o Ministério Público.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Ao final da audiência de instrução e julgamento, o advogado do réu requer a oitiva de testemunha inicialmente não arrolada na resposta escrita, mas referida por outra testemunha ouvida na audiência. O juiz indefere a diligência alegando que o número máximo de testemunhas já havia sido atingido e que, além disso, a diligência era claramente protelatória, já que a prescrição estava em vias de se consumar se não fosse logo prolatada a sentença. A sentença é proferida em audiência, condenando-se o réu à pena de 6 anos em regime inicial semi-aberto.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Mauro Ricardo decidiu não pagar o imposto de renda do último ano, pois sua esposa Ana, servidora pública, sofreu acidente de carro e foi declarada absolutamente incapaz, em virtude de traumatismo craniano gravíssimo.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Em Direito Tributário, cumpre à lei ordinária:', '["A) estabelecer a cominação ou dispensa de penalidades para as ações ou omissões contrárias a seus dispositivos.", "B) estabelecer a forma e as condições como isenções, incentivos e benefícios fiscais serão concedidos em matéria de ISS.", "C) estabelecer normas gerais em matéria tributária, especialmente sobre adequado tratamento tributário ao ato cooperativo praticado pelas sociedades cooperativas.", "D) estabelecer normas gerais em matéria tributária, especialmente sobre a definição de tratamento diferenciado e favorecido para as microempresas e empresas de pequeno porte."]'::jsonb, 'A', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Pizza Aqui Ltda., empresa do ramo dos restaurantes, adquiriu o estabelecimento empresarial Pizza Já Ltda., continuando a exploração deste estabelecimento, porém sob razão social diferente – Pizza Aqui Ltda. Neste caso, é correto afirmar que:', '["A) a Pizza Aqui responde solidariamente pelos tributos devidos pela Pizza Já, até a data do ato de aquisição do estabelecimento empresarial, se a Pizza Já cessar a exploração da atividade.", "B) caso a Pizza Já prossiga na exploração da mesma atividade dentro de 6 (seis) meses contados da data de alienação, a Pizza Aqui responde subsidiariamente pelos tributos devidos pela Pizza Já Ltda. até a data do ato de aquisição do estabelecimento.", "C) caso a Pizza Já mude de ramo de comércio dentro de 6 (seis) meses contados da data de alienação, então a Pizza Aqui será integralmente responsável pelos tributos devidos pela Pizza Já até a data do ato de aquisição desta.", "D) caso o negócio jurídico não fosse a aquisição, mas a incorporação da Pizza Já pela Pizza Aqui, esta última estaria isenta de qualquer responsabilidade referente aos tributos devidos pela Pizza Já até a data da incorporação."]'::jsonb, 'B', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Delta Ltda. teve sua falência decretada em 11/01/2010. Delta possuía um imóvel hipotecado ao Banco Junior S/A, em garanti a de dívida no valor de R$ 1.000.000,00 O imóvel está avaliado em R$ 1.200.000,00.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Semprônio dos Santos é proprietário de um sítio de recreio, local destinado ao lazer, na área de expansão urbana, na região serrana de Paraíso do Alto.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'De acordo com o Código Tributário Nacional, aplica-se retroativamente a lei tributária na hipótese de:', '["A) analogia, quando esta favorecer o contribuinte.", "B) extinção do tributo, ainda não definitivamente constituído.", "C) graduação quanto à natureza de tributo aplicável, desde que não seja hipótese de crime.", "D) ato não definitivamente julgado, quando a lei nova lhe comine penalidade menos severa que a prevista na lei vigente ao tempo de sua prática."]'::jsonb, 'D', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Caso determinado município venha a atualizar o valor monetário da base de cálculo do IPTU, tal hipótese', '["A) deve vir regulada por lei.", "B) deve vir regulada por lei complementar.", "C) enquadra-se como majoração de tributo.", "D) poderá ser disciplinada mediante decreto."]'::jsonb, 'D', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'O emprego da analogia, em matéria tributária, resultará na', '["A) majoração de tributo.", "B) instituição de tributo.", "C) exclusão do crédito tributário.", "D) impossibilidade de exigência de tributo não previsto em lei."]'::jsonb, 'D', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Considere a seguinte situação hipotética: lei federal fixou alíquotas aplicáveis ao ITR e estabeleceu que a alíquota relativa aos imóveis rurais situados no Rio de Janeiro seria de 5% e a relativa aos demais Estados do Sudeste de 7%.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A Cia. de Limpeza do Município de Trás os Montes, empresa pública municipal, vendeu um imóvel de sua titularidade situado na rua Dois, da quadra 23, localizado no nº 06.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'Renato, advogado em início de carreira, é contactado para defender os interesses de Rodrigo que está detido em cadeia pública. Dirige-se ao local onde seu cliente está retido e busca informações sobre sua situação, recebendo como resposta do servidor público que estava de plantão que os autos do inquérito estariam conclusos com a autoridade policial e, por isso, indisponíveis para consulta e que deveria o advogado retornar quando a autoridade tivesse liberado os autos para realização de diligências.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'Mauro, advogado com larga experiência profissional, resolve contratar com emissora de televisão, um novo programa, incluído na grade normal de horários da empresa, cujo titulo é “o Advogado na TV”, com o fito de proporcionar informações sobre a carreira, os seus percalços, suas angústias, alegrias e comprovar a possibilidade de sucesso profissional.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'Fábio, advogado com mais de dez anos de efetiva atividade, obtém a indicação da OAB para concorrer pelo quinto constitucional à vaga reservada no âmbito de Tribunal de Justiça.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'João Vítor e Ana Beatriz, ambos advogados, contraem núpcias, mantendo o estado de casados por longos anos. Paralelamente, também mantêm sociedade em escritório de advocacia. Por motivos vários, passam a ter seguidas altercações, com acusações mútuas de descumprimento dos deveres conjugais.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'Francisco, advogado, dirige-se, com seu cliente, para participar de audiência em questão cível, designada para a colheita de provas e depoimento pessoal. O ato fora designado para iniciar às 13 horas. Como é de praxe, adentraram o recinto forense com meia hora de antecedência, sendo comunicados pelo Oficial de Justiça que a pauta de audiências continha dez eventos e que a primeira havia iniciado às dez horas, já caracterizado um atraso de uma hora, desde a audiência inaugural.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'Dentre as sanções cabíveis no processo disciplinar realizado pela OAB no concernente aos advogados estão a censura, a suspensão, a exclusão e a multa.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'Eduardo, advogado, é contratado para defender os interesses de Otávio, próspero fazendeiro, em diversas ações, de natureza civil, empresarial, criminal, bem como em processos administrativos que tramitam em numerosos órgãos públicos.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'Caio, advogado, inscrito na OAB-SP, após aprovação em concorrido Exame de Ordem, atua em diversos ramos do Direito. Um dos seus clientes possui causa em curso perante a Comarca de Tombos/MG, tendo o profissional comparecido à sede do Juízo para praticar ato em prol do seu constituinte. Estando no local, foi surpreendido por designação do Juiz Titular da Comarca para representar Tício, pessoa de parcos recursos financeiros, diante da ausência de Defensor Público designado para prestar serviços no local, por falta de efetivo sufi ciente de profissionais. Não tendo argumentos para recusar o encargo, Caio participou do ato.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'Michel, Philippe e Lígia, bacharéis em Direito recém-formados e colegas de bancos universitários, comprometem-se a empreender a atividade advocatícia de forma conjunta logo após a aprovação no Exame de Ordem. Para gáudio dos bacharéis, todos são aprovados no certame e obtém sua inscrição no Quadro de Advogados da OAB.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'Joel é experiente advogado, inscrito há muitos anos nos quadros da OAB. Em atividade profissional, comparece à sessão de tribunal com o fito de sustentar, oralmente, recurso apresentado em prol de determinado cliente. Iniciada a sessão de julgamento, após a leitura do relatório, pelo magistrado designado para tal função no processo, dirige-se à tribuna e, regularmente, apresenta sua defesa oral. No curso do julgamento há menção, pelo Relator de data e fl s. constantes dos autos processuais que se revelam incorretas.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Antônio e Joana casaram-se pelo regime da comunhão parcial de bens. Após o casamento, Antônio tornou-se sócio de sociedade simples com 1.000 quotas representativas de 20% do capital da sociedade. Passados alguns anos, o casal veio a se separar judicialmente.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'No que se refere à cessão de quotas de sociedade empresária limitada, assinale a alternativa correta.', '["A) O cedente responde solidariamente com o cessionário perante a sociedade e terceiros pelas obrigações que tinha como sócio até 3 anos após averbado no registro competente a modificação do contrato social.", "B) Na omissão do contrato, o sócio pode ceder sua quota, total ou parcialmente, a quem já seja sócio, independentemente da audiência dos demais.", "C) A cessão de quotas, consubstanciada na respectiva alteração contratual, terá eficácia entre cedente e cessionário somente após a sua averbação perante o órgão competente.", "D) Na omissão do contrato, o sócio pode ceder sua quota, total ou parcialmente, para terceiro, estranho ao quadro de sócios, somente se houver a concordância da unanimidade dos demais sócios."]'::jsonb, 'B', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Jogador de futebol de um importante time espanhol e titular da seleção brasileira é filmado por um celular em uma casa noturna na Espanha, em avançado estado de embriaguez. O vídeo é veiculado na internet e tem grande repercussão no Brasil. Temeroso de ser cortado da seleção brasileira, o jogador ajuíza uma ação no Brasil contra o portal de vídeos, cuja sede é na Califórnia, Estados Unidos. O juiz brasileiro', '["A) não é competente, porque o réu é pessoa jurídica estrangeira.", "B) terá competência porque os danos à imagem ocorreram no Brasil.", "C) deverá remeter o caso, por carta rogatória, à justiça norte-americana.", "D) terá competência porque o autor tem nacionalidade brasileira."]'::jsonb, 'B', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Um contrato internacional entre um exportador brasileiro de laranjas e o comprador americano, previu que em caso de litígio fosse utilizada a arbitragem, realizada pela Câmara de Comércio Internacional. O exportador brasileiro fez a remessa das laranjas, mas estas não atingiram a qualidade estabelecida no contrato. O comprador entrou com uma ação no Brasil para discutir o cumprimento do contrato. O juiz decidiu:', '["A) extinguir o feito sem julgamento de mérito, em face da cláusula arbitral.", "B) deferir o pedido, na forma requerida.", "C) indeferir o pedido porque o local do cumprimento do contrato é nos Estados Unidos.", "D) deferir o pedido, em razão da competência concorrente da justiça brasileira."]'::jsonb, 'A', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Dentre os direitos de toda criança ou todo adolescente, o ECA assegura o de ser criado e educado no seio de sua família e, excepcionalmente, a colocação em família substituta, assegurando-lhe a convivência familiar e comunitária.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Tendo por substrato legal as alterações promovidas pela Lei n. 12.010, de 2009 no tocante à adoção, assinale a afirmativa correta.', '["A) A morte dos adotantes não restabelece o poder familiar dos pais naturais.", "B) Para viabilizar a celeridade no processo de adoção, a legislação específica – ECA – admite a representação do adotante por procuração.", "C) Uma vez falecido o adotante no curso do procedimento de adoção e antes de prolatada a sentença, não poderá o juiz deferir a adoção, mesmo que tenha havido inequívoca manifestação de vontade do adotante.", "D) Os cartórios de registros públicos de pessoas naturais deverão fornecer certidão a qualquer requisitante, independentemente, de justificativa de seu interesse, em que conste o vínculo da adoção constituído por sentença judicial."]'::jsonb, 'A', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Considerando a repartição de competências ambientais estabelecida na Constituição Federal, assinale a alternativa correta.', '["A) Deverá ser editada lei ordinária com as normas para a cooperação entre a União e os Estados, o Distrito Federal e os Municípios para o exercício da competência comum de defesa do meio ambiente.", "B) A exigência de apresentação, no processo de licenciamento ambiental, de certidão da Prefeitura Municipal sobre a conformidade do empreendimento com a legislação de uso e ocupação do solo decorre da competência do município para o planejamento e controle do uso, do parcelamento e da ocupação do solo urbano.", "C) Legislar sobre proteção do meio ambiente e controle da poluição é de competência concorrente da União, dos Estados, do Distrito Federal e dos Municípios, com fundamento no artigo 24 da Constituição Federal.", "D) A competência executiva em matéria ambiental não alcança a aplicação de sanções administrativas por infração à legislação de meio ambiente."]'::jsonb, 'B', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Diante das disposições estabelecidas pela Lei n. 9.605/98 sobre as sanções penais e administrativas derivadas de condutas e atividades lesivas ao meio ambiente, assinale a alternativa correta.', '["A) A desconsideração da pessoa jurídica somente será admiti da se a pena restritiva de direitos se revelar inócua para os fins a que se destina.", "B) A pena restritiva de direitos da pessoa jurídica, no que tange a proibição de contratar com o poder público, terá duração equivalente ao tempo de permanência dos efeitos negativos da conduta delituosa sobre o meio ambiente.", "C) Constitui inovação da lei de crimes ambientais a excludente de anti juridicidade relativamente ao comércio não autorizado de animais da fauna silvestre voltado exclusivamente à subsistência da entidade familiar.", "D) Os tipos penais ambientais, em regra, descrevem crimes de perigo abstrato, que se consumam com a própria criação do risco, efetivo ou presumido, independentemente de qualquer resultado danoso."]'::jsonb, 'D', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Sobre o tratamento da publicidade no Código de Defesa do Consumidor, é correto afirmar que:', '["A) a publicidade somente vincula o fornecedor se contiver informações falsas.", "B) a publicidade que não informa sobre a origem do produto é considerada enganosa, mesmo quando não essencial para o produto.", "C) o ônus da prova da veracidade da mensagem publicitária cabe ao veículo de comunicação.", "D) é abusiva a publicidade que desrespeita valores ambientais."]'::jsonb, 'D', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Nas ações coletivas, o efeito da coisa julgada material será:', '["A) Tratando-se de direitos individuais homogêneos, efeito erga omnes, se procedente, mas só aproveita aquele que se habilitou até o trânsito em julgado.", "B) Tratando-se de direitos individuais homogêneos, julgados improcedentes, o consumidor, que não ti ver conhecimento da ação, não poderá intentar ação individual.", "C) Tratando-se de direitos difusos, no caso de improcedência por insuficiência de provas, não faz coisa julgada material, podendo, qualquer prejudicado, intentar nova ação com os mesmo fundamentos, valendo-se de novas provas.", "D) Tratando-se de direitos coletivos, no caso de improcedência do pedido de nulidade de cláusula contratual, o efeito é ultra partes e impede a propositura de ação individual."]'::jsonb, 'C', 'Questão do Exame da OAB 2010.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'O prefeito de um determinado município resolve, por decreto municipal, alterar unilateralmente as vias de transporte de ônibus municipais, modificando o que estava previsto nos contratos de concessão pública de transportes municipais válidos por vinte anos. O objetivo do prefeito foi favorecer duas empresas concessionárias específicas, com que mantém ligações políticas e familiares, ao lhes conceder os trajetos e linhas mais rentáveis. As demais três empresas concessionárias que também exploram os serviços de transporte de ônibus no município por meio de contratos de concessão sentem-se prejudicadas.  Na qualidade de advogado dessas últimas três empresas, qual deve ser a providência tomada?', '["A) Ingressar com ação judicial, com pedido de liminar para que o Poder Judiciário exerça o controle do ato administrativo expedido pelo prefeito e decrete a sua nulidade ou suspensão imediata, já que eivado de vício e nulidade, por configurar ato fraudulento e atentatório aos princípios que regem a Administração Pública.", "B) Ingressar com ação judicial, com pedido de indenização em face do Município pelos prejuízos de ordem financeira causados.", "C) Nenhuma medida merece ser tomada na hipótese, tendo em vista que um dos poderes conferidos à Administração Pública nos contratos de concessão é a modificação unilateral das suas cláusulas.", "D) Ingressar com ação judicial, com pedido para que os benefícios concedidos às duas primeiras empresas também sejam extensivos às três empresas clientes."]'::jsonb, 'A', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'São considerados agentes públicos todas as pessoas físicas incumbidas, sob remuneração ou não, definitiva ou transitoriamente, do exercício de função ou atividade pública. Assim, é correto afirmar que os notários e registradores são', '["A) agentes públicos ocupantes de cargo efetivo e se aposentam aos 70 (setenta) anos de idade.", "B) agentes públicos vitalícios, ocupantes de cargo efetivo, e não se aposentam compulsoriamente.", "C) delegatários de serviços públicos aprovados em concurso público.", "D) os notários e registradores são delegatários de serviços públicos, investidos em cargos efetivos após aprovação em concurso."]'::jsonb, 'C', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A revogação da licitação pressupõe', '["A) mero juízo de conveniência e oportunidade da Administração, podendo se dar a qualquer tempo.", "B) mero juízo de conveniência e oportunidade da Administração, podendo ocorrer até antes da assinatura do contrato.", "C) prévia, integral e justa indenização, podendo, por isso, se dar por qualquer motivo e a qualquer tempo.", "D) razões de interesse público decorrentes de fato superveniente, devidamente comprovado, pertinente e suficiente para justificar essa conduta."]'::jsonb, 'D', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Sendo o contrato administrativo nulo, é correto afirmar que', '["A) a declaração de nulidade não opera retroativamente, obrigando o contratado a indenizar a Administração pelos danos por esta sofridos.", "B) seu reconhecimento não exonera a Administração do dever de indenizar o contratado de boa-fé, por tudo o que este houver executado e por outros prejuízos comprovados.", "C) a declaração não opera retroativamente, respeitando o direito adquirido ao término do contrato, caso tenha o contratado iniciado sua execução.", "D) que essa nulidade só produzirá efeitos se o contrato for de valor superior a 100 (cem) salários mínimos, caso o contratado tenha iniciado a sua execução."]'::jsonb, 'B', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Um policial militar, de nome Norberto, no dia de folga, quando estava na frente da sua casa, de bermuda e sem camisa, discute com um transeunte e acaba desferindo tiros de uma arma antiga, que seu avô lhe dera. Com base no relatado acima, é correto afirmar que o Estado', '["A) será responsabilizado, pois Norberto é agente público pertencente a seus quadros.", "B) será responsabilizado, com base na teoria do risco integral.", "C) somente será responsabilizado de forma subsidiária, ou seja, caso Norberto não tenha condições financeiras.", "D) não será responsabilizado, pois Norberto, apesar de ser agente público, não atuou nessa qualidade; sua conduta não pode, pois, ser imputada ao Ente Público."]'::jsonb, 'D', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Determinado servidor público foi acusado de ter recebido vantagens indevidas valendo-se de seu cargo público, sendo denunciado à justiça criminal e instaurado, no âmbito administrativo, processo administrativo disciplinar por ter infringindo seu estatuto funcional pela mesma conduta.  Ocorre que o servidor foi absolvido pelo Poder Judiciário em razão de ter ficado provada a inexistência do ato ilícito que lhe fora atribuído.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'É correto afirmar que a desconcentração administrativa ocorre quando um ente político', '["A) cria, mediante lei, órgãos internos em sua própria estrutura para organizar a gestão administrativa.", "B) cria, por lei específica, uma nova pessoa jurídica de direito público para auxiliar a administração pública direta.", "C) autoriza a criação, por lei e por prazo indeterminado, de uma nova pessoa jurídica de direito privado para auxiliar a administração pública.", "D) contrata, mediante concessão de serviço público, por prazo determinado, uma pessoa jurídica de direito público ou privado para desempenhar uma atividade típica da administração pública."]'::jsonb, 'A', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Com relação à intervenção do Estado na propriedade, assinale a alternativa correta.', '["A) A requisição administrativa é uma forma de intervenção supressiva do Estado na propriedade que somente recai em bens imóveis, sendo o Estado obrigado a indenizar eventuais prejuízos, se houver dano.", "B) A limitação administrativa é uma forma de intervenção restritiva do Estado na propriedade que consubstancia obrigações de caráter específico e individualizados a proprietários determinados, sem afetar o caráter absoluto do direito de propriedade.", "C) A servidão administrativa é uma forma de intervenção restritiva do Estado na propriedade que afeta as faculdades de uso e gozo sobre o bem objeto da intervenção, em razão de um interesse público.", "D) O tombamento é uma forma de intervenção do Estado na propriedade privada que possui como característica a conservação dos aspectos históricos, artísticos, paisagísticos e culturais dos bens imóveis, excepcionando-se os bens móveis."]'::jsonb, 'C', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Maria celebrou contrato de compra e venda do carro da marca X com Pedro, pagando um sinal de R$ 10.000,00. No dia da entrega do veículo, a garagem de Pedro foi invadida por bandidos, que furtaram o referido carro. A respeito da situação narrada, assinale a alternativa correta.', '["A) Haverá resolução do contrato pela falta superveniente do objeto, sendo restituído o valor já pago por Maria.", "B) Não haverá resolução do contrato, pois Pedro pode alegar caso fortuito.", "C) Maria poderá exigir a entrega de outro carro.", "D) Pedro poderá entregar outro veículo no lugar no automóvel furtado."]'::jsonb, 'A', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Mathias, solteiro e capaz, com 65 anos de idade, e Tânia, solteira e capaz, com 60 anos de idade, conheceram-se há um ano e, agora, pretendem se casar.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Josefina e José, casados pelo regime da comunhão universal de bens, tiveram três filhos: Mário, Mauro e Moacir. Mário teve dois filhos: Paulo e Pedro. Mauro teve três filhos: Breno, Bruno e Brian. Moacir teve duas filhas: Isolda e Isabel. Em um acidente automobilístico, morreram Mário e Mauro. José, muito triste com a perda dos filhos, faleceu logo em seguida, deixando um patrimônio de R$ 900.000,00. Nesse caso hipotético, como ficaria a divisão do monte?', '["A) Josefina receberia R$ 450.000,00. Os filhos de Mário receberiam cada um R$ 75.000,00. Os filhos de Mauro receberiam R$ 50.000,00 cada um. E, por fim, as filhas de Moacir receberiam R$ 75.000,00 cada uma.", "B) A herança seria dividida em três partes de R$ 300.000,00. Paulo e Pedro receberiam cada um R$ 150.000,00. Breno, Bruno e Brian receberiam, cada um, R$ 100.000,00. E, por fim, Isabel e Isolda receberiam cada uma a importância de R$ 150.000,00.", "C) Paulo e Pedro receberiam cada um R$ 150.000,00. Breno, Bruno e Brian receberiam, cada um, R$ 100.000,00. E, por fim, Moacir receberia R$ 300.000,00.", "D) Josefina receberia R$ 450.000,00. Paulo e Pedro receberiam cada um R$ 75.000,00. Breno, Bruno e Brian receberiam cada um R$ 50.000,00. Moacir receberia R$ 150.000,00."]'::jsonb, 'D', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Ricardo, buscando evitar um atropelamento, realiza uma manobra e atinge o muro de uma casa, causando um grave prejuízo.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'João foi registrado ao nascer com o gênero masculino. Em 2008, aos 18 anos, fez cirurgia para correção de anomalia genética e teve seu registro retificado para o gênero feminino, conforme sentença judicial. No registro não constou textualmente a indicação de retificação, apenas foi lavrado um novo termo, passando a adotar o nome de Joana. Em julho de 2010, casou-se com Antônio, homem religioso e de família tradicional interiorana, que conheceu em janeiro de 2010, por quem teve uma paixão fulminante e correspondida. Joana omitiu sua história registral por medo de não ser aceita e perdê-lo. Em dezembro de 2010, na noite de Natal, a tia de Joana revela a Antônio a verdade sobre o registro de Joana/João. Antônio, não suportando ter sido enganado, deseja a anulação do casamento.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Danilo celebrou contrato por instrumento particular com Sandro, por meio do qual aquele prometera que seu irmão, Reinaldo, famoso cantor popular, concederia uma entrevista exclusiva ao programa de rádio apresentado por Sandro, no domingo seguinte. Em contrapartida, caberia a Sandro efetuar o pagamento a Danilo de certa soma em dinheiro. Todavia, chegada a hora do programa, Reinaldo não compareceu à rádio. Dias depois, Danilo procurou Sandro, a fim de cobrar a quantia contratualmente prevista, ao argumento de que, embora não tenha obtido êxito, envidara todos os esforços no sentido de convencer o seu irmão a comparecer. A respeito da situação narrada, é correto afirmar que Sandro', '["A) não está obrigado a efetuar o pagamento a Danilo, pois a obrigação por este assumida é de resultado, sendo, ainda, autorizado a Sandro obter ressarcimento por perdas e danos de Danilo.", "B) não está obrigado a efetuar o pagamento a Danilo, por ser o contrato nulo, tendo em vista que Reinaldo não é parte contratante.", "C) está obrigado a efetuar o pagamento a Danilo, pois a obrigação por este assumida é de meio, restando a Sandro o direito de cobrar perdas e danos diretamente de Reinaldo.", "D) está obrigado a efetuar o pagamento a Danilo, pois a obrigação por este assumida é de meio, sendo incabível a cobrança de perdas e danos de Reinaldo."]'::jsonb, 'A', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Félix e Joaquim são proprietários de casas vizinhas há cinco anos e, de comum acordo, haviam regularmente delimitado as suas propriedades pela instalação de uma singela cerca viva. Recentemente, Félix adquiriu um cachorro e, por essa razão, o seu vizinho, Joaquim, solicitou-lhe que substituísse a cerca viva por um tapume que impedisse a entrada do cachorro em sua propriedade. Surpreso, Félix negou-se a atender ao pedido do vizinho, argumentando que o seu cachorro era adestrado e inofensivo e, por isso, jamais lhe causaria qualquer dano.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Em relação aos alimentos, assinale a alternativa correta.', '["A) Eles não servem apenas para garantir as necessidades básicas do alimentando, mas também para preservar a condição social de quem os pleiteia.", "B) No atual Código Civil, o cônjuge eventualmente declarado culpado pela separação não sofre qualquer restrição em seu direito de pedir alimentos ao outro cônjuge.", "C) A obrigação alimentar possui como característica básica ser irrenunciável, não poder ser restituída ou compensável e ser intransmissível.", "D) A possibilidade de os filhos maiores pedirem alimentos aos pais continua a existir após se atingir a maioridade, em razão da continuação do poder familiar que esses exercem sobre os filhos necessitados."]'::jsonb, 'A', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'João deverá entregar quatro cavalos da raça X ou quatro éguas da raça X a José. O credor, no momento do adimplemento da obrigação, exige a entrega de dois cavalos da raça X e de duas éguas da raça X.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Sônia, maior e capaz, decide doar, por instrumento particular, certa quantia em dinheiro em favor se seu sobrinho, Fernando, maior e capaz, caso ele venha a se casar com Leila. Sônia faz constar, ainda, cláusula de irrevogabilidade da doação por eventual ingratidão de seu sobrinho. Fernando, por sua vez, aceita formalmente a doação e, poucos meses depois, casa-se com Leila, conforme estipulado. No dia seguinte ao casamento, ao procurar sua tia para receber a quantia estabelecida, Fernando deflagra uma discussão com Sônia e lhe dirige grave ofensa física. A respeito da situação narrada, é correto afirmar que Fernando', '["A) não deve receber a quantia em dinheiro, tendo em vista que a doação é nula, pois deveria ter sido realizada por escritura pública.", "B) deve receber a quantia em dinheiro, em razão de o instrumento de doação prever cláusula de irrevogabilidade por eventual ingratidão.", "C) não deve receber a quantia em dinheiro, pois dirigiu grave ofensa física à sua tia Sônia.", "D) deve receber a quantia em dinheiro, em razão de ter se casado com Leila e independentemente de ter dirigido grave ofensa física a Sônia."]'::jsonb, 'D', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A ação popular é um importante instrumento para a promoção da tutela coletiva de direitos. Acerca da coisa julgada formada pelas sentenças de mérito proferidas em tais ações, é correto afirmar que', '["A) só se forma coisa julgada em ações populares julgadas procedentes, após a aplicação do duplo grau de jurisdição, medida que tem por objetivo preservar os interesses da Fazenda Pública eventualmente condenada.", "B) a produção de efeitos erga omnes não ocorre se o pedido for julgado improcedente por insuficiência de provas.", "C) produz efeitos erga omnes, exclusivamente nos casos de procedência meritória, ficando seus efeitos, em todos os casos de improcedência, limitados às partes do processo.", "D) produz, como regra, efeitos inter partes, cabendo aos interessados em se beneficiarem de eventual procedência na ação requererem sua habilitação até a prolação da sentença."]'::jsonb, 'B', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Em um processo que observa o rito comum ordinário, o juiz profere decisão interlocutória contrária aos interesses do réu. É certo que, se a decisão em questão não for rapidamente apreciada e revertida, sofrerá a parte dano grave, de difícil ou impossível reparação. Assim sendo, o advogado do réu prepara o recurso de agravo de instrumento, cuja petição de interposição contém a exposição dos fundamentos de fato e de direito, as razões do pedido de reforma da decisão agravada, além do nome e endereço dos advogados que atuam no processo. A petição está, ainda, instruída com todas as peças obrigatórias que irão formar o instrumento do agravo. Contudo, o agravante deixou de requerer a juntada, no prazo legal, aos autos do processo, de cópia da petição do agravo de instrumento e do comprovante de sua interposição, assim como a relação dos documentos que instruíram o recurso, fato que foi arguido e provado pelo agravado. Com base no relatado acima, assinale a alternativa correta a respeito da consequência processual decorrente.', '["A) Haverá prosseguimento normal do recurso, pois tal juntada caracteriza mera faculdade do agravante.", "B) Não será admitido o agravo de instrumento.", "C) O agravo de instrumento será julgado pelo tribunal, inviabilizando-se, apenas, o exercício do juízo de retratação pelo magistrado.", "D) Estará caracterizada a litigância de má-fé, por força de prática de ato processual manifestamente protelatório, devendo a parte agravante ser sancionada, e o feito, extinto sem resolução do mérito."]'::jsonb, 'B', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'O mandado de segurança é um importante instrumento de proteção a direitos líquidos e certos, individuais ou coletivos, que não estejam amparados por habeas corpus ou habeas data, sempre que, ilegalmente ou com abuso de poder, qualquer pessoa física ou jurídica sofrer violação ou tiver justo receio de sofrê-la por parte de autoridade. Acerca do mandado de segurança coletivo, é correto afirmar que', '["A) pode ser impetrado em defesa de direitos líquidos e certos que pertençam a apenas parte dos membros de uma categoria ou associação, substituídos pelo impetrante.", "B) a sentença de procedência produz efeitos erga omnes, não limitando seus efeitos aos membros da categoria substituídos pelo impetrante.", "C) não induz litispendência para as ações individuais, de forma que os efeitos da coisa julgada beneficiam o impetrante individual, ainda que não requeira a desistência de seu mandado de segurança.", "D) a interposição de embargos infringentes é admitida para fins de exercício da ampla defesa."]'::jsonb, 'A', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Na ação proposta por Jofre em face de Catarina, em trâmite sob o rito comum ordinário, devidamente citada, a ré oferece contestação e reconvenção. Em preliminar de contestação, Catarina informa a existência de causa que poderá produzir a extinção do processo sem resolução do mérito.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'O Código de Processo Civil regulamenta como se dará a atuação das partes e dos procuradores em juízo. Além de dispor sobre a capacidade processual e dos deveres de cada um, disciplina sobre a constituição de representante processual e substituição das partes e dos procuradores.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A inspeção judicial está prevista no Código de Processo Civil como uma das modalidades de produção de provas no processo de conhecimento.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A sentença liminar, acrescida à legislação processual civil por meio da Lei 11.277/06, assegura ao juiz a possibilidade de dispensar a citação e proferir desde logo sentença, nas hipóteses em que o juízo já tenha proferido sentença de total improcedência em casos idênticos.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Nos autos de ação indenizatória ajuizada por Alfredo em face de Thales, é prolatada sentença de procedência do pleito autoral, condenando o réu ao pagamento de determinada quantia em dinheiro. Ainda na pendência do julgamento da apelação interposta contra a sentença, Alfredo constata que Thales está adotando uma série de providências destinadas a alienar todos os seus bens, o que poderá frustrar o cumprimento da sentença, caso esta seja confirmada pelo tribunal.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Ronaldo passeava com seu carro novo, na cidade onde reside, quando bateu em um buraco deixado pela Prefeitura. O prejuízo ficou em R$ 2.500,00 (dois mil e quinhentos reais), e ele pretende ser ressarcido. Com base no problema apresentado, assinale a alternativa correta.', '["A) Ronaldo pode escolher entre propor a ação no Juizado Especial da Fazenda Pública ou uma Vara da Fazenda Pública, ambos existentes na comarca onde reside e ocorreu o evento.", "B) Após o trânsito em julgado da sentença de procedência do pedido, Ronaldo deverá inscrever seu título para pagamento na forma de precatório.", "C) Eventual sentença de procedência proferida em primeira instância será submetida ao reexame necessário, pois sucumbente a Fazenda Pública.", "D) O Município não gozará de prazo em dobro para recorrer na demanda proposta por Ronaldo."]'::jsonb, 'D', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'O Governador de um Estado membro da Federação pretende se insurgir contra lei de seu Estado editada em 1984 que vincula a remuneração de servidores públicos estaduais ao salário mínimo. Os fundamentos de índole material a serem invocados são a ofensa ao princípio federativo e a vedação constitucional de vinculação do salário mínimo para qualquer fim.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'O controle externo financeiro da União e das entidades da administração federal direta e indireta é atribuição do Congresso Nacional, que o exerce com o auxílio do Tribunal de Contas da União.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A respeito da disciplina constitucional da Administração Pública, é correto afirmar que', '["A) as funções de confiança e os cargos em comissão se destinam apenas às atribuições de direção, chefia e assessoramento.", "B) os atos de improbidade administrativa importarão a cassação de direitos políticos, a perda da função pública, a indisponibilidade de bens e o ressarcimento ao erário, na forma e gradação previstas em lei, sem prejuízo da ação penal cabível.", "C) a vinculação de espécies remuneratórias no serviço público é vedada, mas admite-se a equiparação salarial entre carreiras públicas.", "D) o direito de greve é assegurado ao servidor público civil, devendo ser exercido nos termos e nos limites definidos em lei complementar."]'::jsonb, 'A', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A Constituição da República de 1988 reclama lei complementar para dispor sobre', '["A) o estatuto jurídico das empresas públicas e sociedades de economia mista.", "B) as formas de participação do usuário na administração pública.", "C) finanças públicas.", "D) contratação por tempo determinado na administração pública."]'::jsonb, 'C', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Assinale a alternativa que contemple matéria para cuja disciplina é vedada a edição de medida provisória.', '["A) Instituição ou majoração de impostos.", "B) Abertura de crédito extraordinário, ainda que para atendimento a despesas imprevisíveis e urgentes.", "C) Normas gerais de licitações e contratos administrativos.", "D) Partidos políticos e direito eleitoral."]'::jsonb, 'D', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Leia com atenção a afirmação a seguir, que apresenta uma INCORREÇÃO.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Projeto de lei estadual de iniciativa parlamentar concede aumento de remuneração a servidores públicos estaduais da área da saúde e vem a ser convertido em lei após a sanção do Governador do Estado. A referida lei é', '["A) compatível com a Constituição da República, desde que a Constituição do Estado-membro não reserve à Chefia do Poder Executivo a iniciativa de leis que disponham sobre aumento de remuneração de servidores públicos estaduais.", "B) constitucional, em que pese o vício de iniciativa, pois a sanção do Governador do Estado ao projeto de lei teve o condão de sanar o defeito de iniciativa.", "C) inconstitucional, uma vez que os projetos de lei de iniciativa dos Deputados Estaduais não se submetem à sanção do Governador do Estado, sob pena de ofensa à separação de poderes.", "D) inconstitucional, uma vez que são de iniciativa privativa do Governador do Estado as leis que disponham sobre aumento de remuneração de servidores públicos da administração direta e autárquica estadual."]'::jsonb, 'D', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A Constituição garante a plena liberdade de associação para fins lícitos, vedada a de caráter paramilitar (art. 5°, XVII). A respeito desse direito fundamental, é correto afirmar que a criação de uma associação', '["A) depende de autorização do poder público e pode ter suas atividades suspensas por decisão administrativa.", "B) não depende de autorização do poder público, mas pode ter suas atividades suspensas por decisão administrativa.", "C) depende de autorização do poder público, mas só pode ter suas atividades suspensas por decisão judicial transitada em julgado.", "D) não depende de autorização do poder público, mas só pode ter suas atividades suspensas por decisão judicial."]'::jsonb, 'D', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'De acordo com a Constituição da República, são inalistáveis e inelegíveis', '["A) somente os analfabetos e os conscritos.", "B) os estrangeiros, os analfabetos e os conscritos.", "C) somente os estrangeiros e os analfabetos.", "D) somente os estrangeiros e os conscritos."]'::jsonb, 'D', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Um juiz federal proferiu uma sentença em processo relativo a crime político e outra sentença em processo movido por Estado estrangeiro contra pessoa residente no Brasil. Os recursos interpostos contra essas duas sentenças serão julgados pelo', '["A) STF, no primeiro caso, e pelo TRF, no segundo caso.", "B) TRF em ambos os casos.", "C) STF, no primeiro caso, e pelo STJ, no segundo caso.", "D) TRF, no primeiro caso, e pelo STF, no segundo caso."]'::jsonb, 'C', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', '“É a operação que consiste na tomada de uma posição no mercado futuro aproximadamente igual – mas em sentido contrário – àquela que se detém ou que se pretende vir a tomar no mercado à vista. É uma forma de o investidor se proteger contra os feitos da oscilação de preço.” O conceito acima, extraído do Vocabulário do Mercado de Capitais, expedido pela Comissão Nacional de Bolsas de Valores em 1990, corresponde a que tipo de contrato relacionado à compra e venda empresarial?', '["A) Hedging ou hedge.", "B) Contrato estimatório.", "C) Venda com reserva de domínio.", "D) Preempção."]'::jsonb, 'A', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'As Sociedades Anônimas têm uma pesada estrutura, necessitando, assim, de vários órgãos para atingir seu desiderato, cada um com sua função específica. Um desses órgãos é a Diretoria, sendo seus diretores efetivamente os administradores da companhia. Esses diretores possuem alguns deveres para com a sociedade empresarial e para com o mercado.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A sociedade empresária denominada KLM Fábrica de Móveis Ltda. teve a sua falência decretada. No curso do processo, restou apurado que a sociedade, pouco antes do ajuizamento do requerimento que resultou na decretação de sua quebra, havia promovido a venda de seu estabelecimento, independentemente do pagamento de todos os credores ao tempo existentes, ou do consentimento destes, de modo expresso ou tácito, e sem que lhe restassem bens suficientes para solver o seu passivo. Diante desse quadro, é correto afirmar que a alienação é', '["A) revogável por iniciativa do administrador judicial.", "B) ineficaz em relação à massa falida.", "C) nula de pleno direito.", "D) anulável por iniciativa do administrador judicial."]'::jsonb, 'B', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Com relação à exclusão do sócio da sociedade por justa causa, assinale a alternativa correta.', '["A) Como o sócio majoritário possui a maioria do capital social, ele não poderá ser expulso em razão da vontade dos demais sócios, ainda que haja justo motivo para tal expulsão.", "B) A deliberação para exclusão do sócio majoritário não remisso deve ocorrer por assembleia convocada especificamente para tal fim, sendo a deliberação comunicada ao sócio que se visa excluir, e este deverá, em 48 horas, deixar a sociedade, podendo após esse prazo ser feita a devida alteração contratual.", "C) Se for ajuizada ação para se efetivar a expulsão do sócio, o juiz somente poderá verificar os aspectos formais que levaram à exclusão, como, por exemplo, se se respeitou o quórum necessário, não podendo examinar o mérito do ato expulsório.", "D) A justa causa é a violação ou falta de cumprimento das obrigações sociais, sendo que o sócio excluído não perde o valor patrimonial de sua participação societária."]'::jsonb, 'D', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A Lei das Sociedades por Ações estabelece responsabilidades para os administradores, membros do Conselho Fiscal e para o acionista controlador. A violação a tais deveres pode causar responsabilidade civil, administrativa e penal.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Em relação aos Títulos de Crédito, é correto afirmar que, quando', '["A) presente na letra de câmbio, a cláusula “não à ordem” impede a circulação do crédito.", "B) insuficientes os fundos disponíveis, o portador de um cheque pode requerer a responsabilidade cambiária do banco sacado pelo seu não pagamento.", "C) firmado em branco, o aval na nota promissória é entendido como dado em favor do sacador.", "D) não aceita a duplicata, o protesto do título é a providência suficiente para o ajuizamento da ação de execução contra o sacado."]'::jsonb, 'C', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'Homero, advogado especializado em Direito Público, após longos anos, obtém sentença favorável contra a Fazenda Pública Estadual. Requer a execução especial e apresenta, após o decurso normal do processo, requerimento de expedição de precatório, estabelecendo a separação do principal, direcionado ao seu cliente, dos honorários de sucumbência e postulando o desconto no principal de vinte por cento a título de honorários contratuais, cujo contrato anexa aos autos. O pedido é deferido pelo Juiz, mas há recurso do Ministério Público, que não concorda com tal desconto. De acordo com as normas estatutárias aplicáveis, é correto afirmar que', '["A) os honorários devidos no processo judicial se resumem aos sucumbenciais, vedado o desconto de quaisquer outros valores a esse título.", "B) os honorários advocatícios, que gozam de autonomia, quer sucumbenciais, quer contratuais, devem ser cobrados em via própria diretamente ao cliente.", "C) é possível o pagamento de honorários advocatícios contratuais no processo em que houve condenação, havendo precatório, desde que o contrato seja escrito.", "D) seja o contrato escrito ou verbal, pode o advogado requerer o pagamento dos seus honorários contratuais mediante desconto no valor da condenação."]'::jsonb, 'C', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'Tertúlio, advogado, testemunha a ocorrência de um acidente de trânsito sem vítimas, envolvendo quatro veículos automotores. Seus dados e sua qualificação profissional constam nos registros do evento. Posteriormente, em ação de responsabilidade civil, o advogado Tertúlio é arrolado como testemunha por uma das partes. No dia designado para o seu depoimento, alega que estaria impossibilitado de realizar o ato porque uma das pessoas envolvidas poderia contratá-lo como profissional, embora, naquele momento, nenhuma delas tivesse manifestado qualquer intenção nesse sentido. A respeito do tema, é correto dizer que', '["A) o advogado é suspeito para prestar depoimento no caso em tela.", "B) a possibilidade decorre da ausência de efetiva atuação profissional.", "C) o depoimento do advogado, no caso, é facultativo.", "D) somente poderia prestar depoimento após a intervenção de todas as partes no processo."]'::jsonb, 'B', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'O magistrado Mévio, de larga experiência forense, buscando organizar o serviço do seu cartório, edita Portaria disciplinando o horário de atendimento das partes e dos advogados não coincidente com o horário forense. Os processos passam a ser distribuídos, por numeração, com a responsabilização individual de determinados servidores. Estabeleceu-se que os autos de final 0 a 3 teriam atendimento ao público, aí incluídos advogados, das 11h às 13h, e daí sucessivamente. Com tal organização, obteve o cumprimento de todas as metas estabelecidas pela Corregedoria do Tribunal. À luz da legislação estatutária, assinale a alternativa correta quanto a essa atitude.', '["A) O ato normativo do magistrado colide frontalmente com o direito dos advogados de serem atendidos a qualquer momento pelo Magistrado e servidores públicos.", "B) A Administração dos órgãos do Poder Judiciário é autônoma, podendo ocorrer ato do magistrado impondo restrições ao advogado.", "C) O princípio da eficiência sobrepõe-se aos interesses das partes e dos advogados, seguindo moderna tendência da Administração Pública.", "D) As metas de produção determinadas pelos órgãos de controle do Poder Judiciário justificam a restrição dos direitos dos advogados de acesso aos autos e aos agentes públicos."]'::jsonb, 'A', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'Xisto, advogado, é convidado a ocupar o prestigiado cargo de Procurador-Geral de um município, cargo de confiança do Prefeito Municipal passível de exoneração ad nutum. O cargo é privativo de advogado. No entanto, ao assumir o referido cargo, ocorrerá o (a)', '["A) cancelamento da sua inscrição.", "B) exercício limitado da advocacia.", "C) suspensão do exercício da atividade advocatícia.", "D) anotação de impedimento."]'::jsonb, 'B', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'O advogado Caio resolve implementar mudanças administrativas no seu escritório, ao passar a compor o grupo de profissionais escolhido para gerenciá-lo. Uma das atividades consiste na elaboração de um boletim de notícias comunicando aos clientes, parceiros e advogados, a mudança na legislação e os julgamentos de maior repercussão. Para ampliar a divulgação, contrata jovens de ambos os sexos para distribuição gratuita, nos cruzamentos das mais importantes capitais do País. Diante do narrado, é correto afirmar que', '["A) se trata de publicidade moderada.", "B) o boletim de notícias é meio adequado de publicidade quando o público-alvo são clientes do escritório.", "C) a distribuição indiscriminada, se for gratuita, é permitida.", "D) é admissível a distribuição do boletim mediante pagamento de anuidade."]'::jsonb, 'B', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'O advogado Ademar é surpreendido por mandado de busca e apreensão dos documentos guardados no seu escritório, de forma indiscriminada. Após pesquisa, verifica que existe processo investigando um dos seus clientes e a ele mesmo. Apesar disso, os documentos de toda a sua clientela foram apreendidos.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'Terência, jovem advogada, conhecida pela energia com que defende os seus clientes, obtém sucesso em ação indenizatória, com proveito econômico correspondente a R$ 3.000.000,00 (três milhões de reais). Buscando adequação dos seus honorários, marca reunião com seu cliente, e este exige detalhada prestação de contas, o que é negado pela advogada. Nesse momento, há amplo desentendimento. O valor da indenização fora levantado pela advogada e depositado em caderneta de poupança, no aguardo do desfecho da discussão sobre os valores que deveriam ser repassados. Terência não apresentou as contas ao cliente nem direta, nem judicialmente.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'Marcelo promove ação de procedimento ordinário em face de Paus e Cupins Ltda. com o fito de compelir a ré à prestação de determinado fato, diante de contrato anteriormente estabelecido pelas partes e descumprido pela ré. Houve regular citação, com a apresentação de defesa, tendo o processo permanecido paralisado por oito anos por inércia das partes. Dez anos após a paralisação, o réu ingressa no processo requerendo a declaração de prescrição intercorrente, que é declarada, não tendo havido recurso do autor. Após consultas processuais, o autor descobre a real situação do processo e apresenta representação disciplinar à OAB contra o seu advogado. Nos termos da legislação estatutária e do Código de Ética, é correto afirmar que', '["A) o advogado não pode ser sancionado pela demora do processo, mesmo que tenha sido inerte.", "B) está perfeitamente caracterizado o abandono da causa.", "C) os atos referidos se esgotam no processo judicial.", "D) a inércia das partes não pode atingir os advogados, como no enunciado."]'::jsonb, 'B', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'Heitor, advogado regularmente inscrito na OAB, é surpreendido com a notícia de que seu ex adverso havia sido suspenso em processo disciplinar regular, mas que não havia devolvido os documentos oficiais nem comunicado a punição ao juiz dirigente do processo.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'O advogado Rodrigo é surpreendido com notificação do Conselho de Ética da OAB para esclarecer determinados fatos que foram comunicados ao órgão mediante denúncia anônima. Apresenta sua defesa e, desde logo, postula a extinção do processo, que não poderia ser instaurado por ter sido a denúncia anônima.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Em 7 de fevereiro de 2010, Ana, utilizando-se do emprego de grave ameaça, constrange seu amigo Lucas, bem-sucedido advogado, a com ela praticar ato libidinoso diverso da conjunção carnal. Em 7 de agosto de 2010, Lucas comparece à delegacia policial para noticiar o crime, tendo sido instaurado inquérito a fim de apurar as circunstâncias do delito.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Ao concluir o curso de Engenharia, Arli, visando fazer uma brincadeira, inseriu, à caneta, em seu diploma, declaração falsa sobre fato juridicamente relevante.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Guiando o seu automóvel na contramão de direção, em outubro de 2010, Tício é perseguido por uma viatura da polícia militar. Após ser parado pelos agentes da lei, Tício realiza, espontaneamente, o exame do etilômetro e fornece aos militares sua habilitação e o documento do automóvel.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Marcus, visando roubar Maria, a agride, causando-lhe lesões corporais de natureza leve. Antes, contudo, de subtrair qualquer pertence, Marcus decide abandonar a empreitada criminosa, pedindo desculpas à vítima e se evadindo do local. Maria, então, comparece à delegacia mais próxima e narra os fatos à autoridade policial.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Tomás decide matar seu pai, Joaquim. Sabendo da intenção de Tomás de executar o genitor, Pedro oferece, graciosamente, carona ao agente até o local em que ocorre o crime.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Pedro, não observando seu dever objetivo de cuidado na condução de uma bicicleta, choca-se com um telefone público e o destrói totalmente. Nesse caso, é correto afirmar que Pedro', '["A) deverá ser responsabilizado pelo crime de dano simples, somente.", "B) deverá ser responsabilizado pelo crime de dano qualificado, somente.", "C) deverá ser responsabilizado pelo crime de dano qualificado, sem prejuízo da obrigação de reparar o dano causado.", "D) não será responsabilizado penalmente."]'::jsonb, 'D', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Joaquim, desejoso de tirar a vida da própria mãe, acaba causando a morte de uma tia (por confundi-la com aquela). Tendo como referência a situação acima, é correto afirmar que Joaquim incorre em erro', '["A) de tipo essencial escusável – inevitável – e deverá responder pelo crime de homicídio sem a incidência da agravante relativa ao crime praticado contra ascendente (haja vista que a vítima, de fato, não era a sua genitora).", "B) de tipo acidental na modalidade error in persona e deverá responder pelo crime de homicídio com a incidência da agravante relativa ao crime praticado contra ascendente (mesmo que a vítima não seja, de fato, a sua genitora).", "C) de proibição e deverá responder pelo crime de homicídio qualificado pelo fato de ter objetivado atingir ascendente (preserva-se o dolo, independente da identidade da vítima).", "D) de tipo essencial inescusável – evitável –, mas não deverá responder pelo crime de homicídio qualificado, uma vez que a pessoa atingida não era a sua ascendente."]'::jsonb, 'B', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A tortura, conduta expressamente proibida pela Constituição Federal e lei específica,', '["A) pode ser praticada por meio de uma conduta comissiva (positiva, por via de uma ação) ou omissiva (negativa, por via de uma abstenção).", "B) é crime inafiançável, imprescritível e insuscetível de graça ou anistia.", "C) exige, na sua configuração, que o autor provoque lesões corporais na vítima ao lhe proporcionar sofrimento físico com o emprego de violência.", "D) se reconhecida, não implicará aumento de pena, caso seja cometida por agente público."]'::jsonb, 'A', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Com relação às modalidades de prisão, assinale a alternativa correta.', '["A) A prisão em flagrante delito somente poderá ser realizada dentro do período de vinte e quatro horas, contadas do momento em que se inicia a execução do crime.", "B) A prisão temporária poderá ser decretada a qualquer tempo, desde que se mostre imprescindível para a produção da prova.", "C) A prisão preventiva poderá ser decretada durante o inquérito policial.", "D) Em caso de descumprimento de medida protetiva prevista na Lei 11.340/06, o juiz não poderá decretar a prisão preventiva do acusado."]'::jsonb, 'C', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Ao proferir sentença, o magistrado, reputando irrelevantes os argumentos desenvolvidos pela defesa, deixa de apreciá-los, vindo a condenar o acusado.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Em relação aos procedimentos previstos atualmente no Código de Processo Penal, assinale a alternativa correta.', '["A) No rito ordinário, oferecida a denúncia, se o juiz não a rejeitar liminarmente, recebê-la-á e designará dia e hora para a realização do interrogatório, ocasião em que o acusado deverá estar assistido por defensor.", "B) No rito sumário, oferecida a denúncia, se o juiz não a rejeitar liminarmente, recebê-la-á e designará dia e hora para a realização do interrogatório, ocasião em que o acusado deverá estar assistido por defensor.", "C) No rito ordinário, oferecida a denúncia, se o juiz não a rejeitar liminarmente, recebê-la-á e ordenará a citação do acusado para responder à acusação, por escrito, no prazo de 15 (quinze) dias.", "D) No rito sumário, oferecida a denúncia, se o juiz não a rejeitar liminarmente, recebê-la-á e ordenará a citação do acusado para responder à acusação, por escrito, no prazo de 10 (dez) dias."]'::jsonb, 'D', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'José é denunciado sob a acusação de que teria praticado o crime de roubo simples contra Ana Maria. Na audiência de instrução e julgamento, o magistrado indefere, imotivadamente, que sejam ouvidas duas testemunhas de defesa. Ao proferir sentença, o juiz condena José a pena de quatro anos de reclusão, a ser cumprida em regime aberto. Após a sentença passar em julgado para a acusação, a defesa interpõe recurso de apelação, arguindo, preliminarmente, a nulidade do processo em razão do indeferimento imotivado de se ouvirem duas testemunhas, e alegando, no mérito, a improcedência da acusação. Analisando o caso, o Tribunal de Justiça dá provimento ao recurso e declara nulo o processo desde a Audiência de Instrução e Julgamento. Realizado o ato e apresentadas novas alegações finais por meio de memoriais, o juiz profere outra sentença, desta vez condenando José a pena de quatro anos de reclusão a ser cumprida em regime inicialmente semiaberto, pois, sendo reincidente, não poderia iniciar o cumprimento de sua reprimenda em regime aberto. Com base no relatado acima, é correto afirmar que o juiz agiu', '["A) equivocadamente, pois a primeira sentença transitou em julgado para a acusação, de sorte que não poderia a segunda decisão trazer consequência mais gravosa para o réu em razão da interposição de recurso exclusivo da defesa.", "B) equivocadamente, pois, por ser praticado com violência ou grave ameaça contra a pessoa, o crime de roubo impõe o início do cumprimento da pena em regime fechado.", "C) corretamente, pois a pena atribuída proíbe a imposição do regimento aberto para o início do cumprimento de pena.", "D) corretamente, pois, embora a pena atribuída permita a fixação do regime aberto para o início do cumprimento de pena, o fato de ser o réu reincidente impede tal providência, não se podendo falar em prejuízo para o réu uma vez que o recurso de apelação da defesa foi provido pelo Tribunal de Justiça."]'::jsonb, 'A', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Tendo como referência a competência ratione personae, assinale a alternativa correta.', '["A) Caio, vereador de um determinado município, pratica um crime comum previsto na parte especial do Código Penal. Será, pois, julgado no Tribunal de Justiça do Estado onde exerce suas funções, uma vez que goza do foro por prerrogativa de função.", "B) Tício, juiz estadual, pratica um crime eleitoral. Por ter foro por prerrogativa de função, será julgado no Tribunal de Justiça do Estado onde exerce suas atividades.", "C) Mévio é governador do Distrito Federal e pratica um crime comum. Por uma questão de competência originária decorrente da prerrogativa de função, será julgado pelo Superior Tribunal de Justiça.", "D) Terêncio é prefeito e pratica um crime comum, devendo ser julgado pelo Tribunal de Justiça do respectivo Estado. Segundo entendimento do STF, a situação não se alteraria se o crime praticado por Terêncio fosse um crime eleitoral."]'::jsonb, 'C', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Como se sabe, a prisão processual (provisória ou cautelar) é a decretada antes do trânsito em julgado de sentença penal condenatória, nas hipóteses previstas em lei. A respeito de tal modalidade de prisão, é correto afirmar que', '["A) em nosso ordenamento jurídico, a prisão processual contempla as seguintes modalidades: prisão em flagrante, preventiva, temporária, por pronúncia e em virtude de sentença condenatória recorrível.", "B) a prisão temporária tem como pressupostos a existência de indícios de autoria e prova da materialidade, e como fundamentos a necessidade de garantia da ordem pública, a conveniência da instrução criminal, a necessidade de garantir a futura aplicação da lei penal e a garantia da ordem pública.", "C) o prazo de duração da prisão temporária é de cinco dias, prorrogável por mais cinco em caso de extrema e comprovada necessidade. Em se tratando, todavia, de crime hediondo, a prisão temporária poderá ser decretada pelo prazo de trinta dias, prorrogável por igual período.", "D) são requisitos da prisão preventiva a sua imprescindibilidade para as investigações do inquérito policial e o fato de o indiciado não ter residência fixa ou não fornecer elementos necessários ao esclarecimento de sua identidade."]'::jsonb, 'C', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Assinale a alternativa correta à luz da doutrina referente ao Tribunal do Júri.', '["A) São princípios que informam o Tribunal do Júri: a plenitude de defesa, o sigilo das votações, a soberania dos veredictos e a competência exclusiva para julgamento dos crimes dolosos contra a vida.", "B) A natureza jurídica da sentença de pronúncia (em que o magistrado se convence da existência material do fato criminoso e de indícios suficientes de autoria) é de decisão interlocutória mista não terminativa.", "C) O rito das ações de competência do Tribunal do Júri se desenvolve em duas fases: judicium causae e judicium accusacionis. O judicium accusacionis se inicia com a intimação das partes para indicação das provas que pretendem produzir e tem fim com o trânsito em julgado da decisão do Tribunal do Júri.", "D) Alcançada a etapa decisória do sumário da culpa, o juiz poderá exarar quatro espécies de decisão, a saber: pronúncia, impronúncia, absolvição sumária e condenação."]'::jsonb, 'B', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Paulo possuía uma casa de campo, situada em região rural da cidade de Muzambinho – MG, onde costumava passar todos os finais de semana e as férias com a sua família. Contratou Francisco para cuidar de algumas cabeças de gado destinadas à venda de carne e de leite ao mercado local. Francisco trabalhava com pessoalidade e subordinação, de segunda a sábado, das 11h às 21h, recebendo um salário mínimo mensal. Dispensado sem justa causa, ajuizou reclamação trabalhista em face de Paulo, postulando o pagamento de horas extraordinárias, de adicional noturno e dos respectivos reflexos nas verbas decorrentes da execução e da ruptura do contrato de trabalho. Aduziu, ainda, que não era observada pelo empregador a redução da hora noturna. Diante dessa situação hipotética e considerando que as verbas postuladas não foram efetivamente pagas pelo empregador, assinale a alternativa correta.', '["A) Francisco tem direito ao pagamento de horas extraordinárias e de adicional noturno, não lhe assistindo o direito à redução da hora noturna.", "B) Francisco tem direito ao pagamento de horas extraordinárias, mas não lhe assiste o direito ao pagamento de adicional noturno, já que não houve prestação de serviços entre as 22h de um dia e as 5h do dia seguinte.", "C) Francisco não tem direito ao pagamento de horas extraordinárias e de adicional noturno, por se tratar de empregado doméstico.", "D) A redução da hora noturna deveria ter sido observada pelo empregador."]'::jsonb, 'A', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Em se tratando de salário e remuneração, é correto afirmar que', '["A) o salário-maternidade tem natureza salarial.", "B) as gorjetas integram a base de cálculo do aviso prévio, das horas extraordinárias, do adicional noturno e do repouso semanal remunerado.", "C) o plano de saúde fornecido pelo empregador ao empregado, em razão de seu caráter contraprestativo, consiste em salário in natura.", "D) a parcela de participação nos lucros ou resultados, habitualmente paga, não integra a remuneração do empregado."]'::jsonb, 'D', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Com relação às estabilidades e às garantias provisórias de emprego, é correto afirmar que', '["A) o servidor público celetista da administração direta, autárquica ou fundacional não é beneficiário da estabilidade prevista na Constituição da República de 1988, que se restringe ao ocupante de cargo de provimento efetivo em virtude de concurso público.", "B) a empregada gestante tem direito à estabilidade provisória na hipótese de admissão mediante contrato de experiência, uma vez que se visa à proteção do instituto da maternidade.", "C) os membros do Conselho Curador do FGTS representantes dos trabalhadores, efetivos e suplentes, têm direito à estabilidade no emprego, da nomeação até um ano após o término do mandato de representação, somente podendo ser dispensados por motivo de falta grave, regularmente comprovada por processo sindical.", "D) o registro da candidatura do empregado a cargo de dirigente sindical durante o período de aviso prévio não obsta a estabilidade sindical, porque ainda vigente o contrato de trabalho."]'::jsonb, 'C', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'João da Silva decidiu ampliar o seu consultório médico e, para isso, contratou o serviço do empreiteiro Vivaldo Fortuna. Ambos ajustaram o valor de R$ 5.000,00, cujo pagamento seria feito da seguinte maneira: metade de imediato e a outra metade quando do encerramento do serviço. Logo no início dos trabalhos, Vivaldo contratou os serventes Reginaldo Nonato e Simplício de Deus, prometendo-lhes o pagamento de um salário mínimo mensal. Ocorre que, passados três meses, Reginaldo e Simplício nada receberam. Tentaram entrar em contato com Vivaldo, mas este tinha desaparecido. Por conta disso, abandonaram a obra e ajuizaram uma ação trabalhista em face de João da Silva, pleiteando os três meses de salários atrasados, além das verbas resilitórias decorrentes da rescisão indireta provocada por Vivaldo. Diante desse caso concreto, é correto afirmar que João da Silva', '["A) deve ser condenado a pagar os salários atrasados e as verbas resilitórias decorrentes da rescisão indireta, uma vez que é o sucessor trabalhista de Vivaldo Fortuna.", "B) deve ser condenado a pagar apenas os salários atrasados, mas não as verbas resilitórias, uma vez que não foi ele quem deu causa à rescisão indireta.", "C) não deve ser condenado a pagar os salários atrasados e as verbas resilitórias decorrentes da rescisão indireta, uma vez que a obra não foi devidamente encerrada.", "D) não deve ser condenado a pagar os salários atrasados e as verbas resilitórias decorrentes da rescisão indireta, uma vez que é o dono da obra e não desenvolve atividade de construção ou incorporação."]'::jsonb, 'D', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'O empregado Vicente de Morais foi dispensado sem justa causa. Sete dias depois, requereu a liberação do cumprimento do aviso prévio, pois já havia obtido um novo emprego. O antigo empregador concordou com o seu pedido, exigindo apenas que ele fosse feito por escrito, junto com a cópia da sua CTPS registrada pelo novo empregador, o que foi realizado por Vicente. Diante dessa situação, o antigo empregador deverá', '["A) integrar o aviso prévio ao pagamento de todas as verbas rescisórias por ele devidas, uma vez que o aviso prévio é irrenunciável.", "B) deduzir o aviso prévio do pagamento de parte das verbas rescisórias devidas, uma vez que o empregado renunciou livremente a esse direito, mas o aviso prévio continuará incidindo sobre as parcelas de natureza salarial.", "C) deduzir o aviso prévio do pagamento de parte das verbas rescisórias devidas, uma vez que o empregado renunciou livremente a esse direito, mas o aviso prévio continuará incidindo sobre as parcelas de natureza indenizatória.", "D) pagar as verbas rescisórias, excluindo o valor equivalente ao dos dias remanescentes do aviso prévio."]'::jsonb, 'D', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Uma Fundação Municipal de Direito Público decidiu implementar uma reestruturação administrativa, a fim de produzir melhores resultados, com proveito para a sociedade como um todo, prestigiando a sua função social e o princípio da eficiência. Para tanto, desenvolveu um Plano de Incentivo à Demissão Voluntária (PIDV), por meio do qual o empregado que aderisse receberia as verbas resilitórias, acrescidas de um bônus de 80% sobre o seu valor. Ao ler atentamente os termos do PIDV, o empregado Josué de Souza constatou a existência de uma cláusula em que se previa a expressa e geral quitação das obrigações oriundas do contrato de trabalho, nada mais havendo a reclamar depois de efetuado o ajuste. Após refletir cuidadosamente sobre a questão, Josué resolveu aderir ao PIDV. Ocorre que, tão logo recebeu as verbas resilitórias e o bônus de 80%, Josué ajuizou uma ação trabalhista em face da Fundação, pleiteando o pagamento de horas extraordinárias e os reflexos delas decorrentes, sob o argumento de que essas parcelas não foram englobadas expressamente pelo PIDV. Em defesa, o antigo empregador reconheceu a existência de trabalho extraordinário, mas afirmou que as querelas oriundas do contrato de emprego já haviam sido definitivamente solucionadas pelo PIDV. Diante dessa situação concreta, é correto afirmar que o pedido de pagamento de horas extraordinárias e reflexos deve ser julgado', '["A) procedente, uma vez que o PIDV efetua a quitação exclusivamente das parcelas e valores dele constantes.", "B) improcedente, haja vista a cláusula de quitação geral prevista no PIDV.", "C) improcedente, haja vista a natureza jurídica de renúncia do PIDV.", "D) procedente, uma vez que Josué de Souza possui prazo de cinco anos após o término do contrato para pleitear tudo o que entender cabível."]'::jsonb, 'A', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Em relação aos embargos de terceiro na execução por carta precatória, é correto afirmar que', '["A) devem ser oferecidos no juízo deprecante, exceto quando se tratar de vício ou irregularidade de penhora, avaliação ou alienação dos bens, praticados pelo juízo deprecado.", "B) devem ser oferecidos no juízo deprecado, que possui competência por delegação para a execução em outra localidade.", "C) devem ser oferecidos no juízo deprecante, pois a carta precatória se presta apenas para que se pratiquem atos em outra localidade, mantida a competência para atos decisórios no juízo principal da execução.", "D) podem ser oferecidos no juízo deprecante ou deprecado, sendo do juízo deprecante a competência para julgamento, exceto quando se tratar de vício ou irregularidade de penhora, avaliação ou alienação dos bens, praticados pelo juízo deprecado."]'::jsonb, 'D', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Tício, gerente de operações da empresa Metalúrgica Comercial, foi eleito dirigente sindical do Sindicato dos Metalúrgicos. Seis meses depois, juntamente com Mévio, empregado representante da CIPA (Comissão Interna para Prevenção de Acidentes) da empresa por parte dos empregados, arquitetaram um plano para descobrir determinado segredo industrial do seu empregador e repassá-lo ao concorrente mediante pagamento de numerário considerável. Contudo, o plano foi descoberto antes da venda, e a empresa, agora, pretende dispensar ambos por falta grave.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Determinada turma do Tribunal Superior do Trabalho não conheceu de recurso de revista interposto pela empresa Alfa Empreendimentos Ltda. em razão de a decisão recorrida proferida por Tribunal Regional do Trabalho em sede de recurso ordinário, em dissídio individual) estar em perfeita consonância com enunciado de súmula de direito material daquela Corte Superior. Transcorrido in albis o prazo recursal, essa decisão transitou em julgado.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'O sindicato representante de determinada categoria profissional ajuizou ação civil pública em face da Construtora Beta Ltda., postulando sua condenação na obrigação de se abster de coagir seus empregados a deixarem de se filiar ao respectivo ente sindical. A pretensão foi julgada procedente, tendo transitado em julgado a decisão condenatória. Diante dessa situação hipotética, assinale a alternativa correta.', '["A) Seria obrigatória a intervenção do Ministério Público do Trabalho como fiscal da lei nesse processo.", "B) O ajuizamento dessa ação civil pública visou à tutela de interesses ou direitos meramente individuais.", "C) A sentença fará coisa julgada às partes entre as quais é dada (inter partes), não beneficiando nem prejudicando terceiros.", "D) A competência funcional para julgamento dessa ação civil pública é do Tribunal Regional do Trabalho que tenha jurisdição no local onde se situa a sede da empresa."]'::jsonb, 'A', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Contratado para trabalhar no Município de Boa-Fé pela empresa X, Marcos da Silva, residente no Município de Última Instância, estava obrigado a utilizar duas linhas de ônibus para ir e para voltar do trabalho para casa, ao custo de R$ 16,00 por dia. Em virtude dos gastos com as passagens, Marcos requereu ao seu empregador que lhe fornecesse vale-transporte, ao que lhe foi dito que seria providenciado. Passados oito meses, Marcos foi dispensado sem justa causa, recebendo as verbas resilitórias, sem qualquer menção ao vale-transporte. Inconformado, Marcos ajuizou ação trabalhista pleiteando o pagamento de vale-transporte, pois nunca recebeu essa prestação. Em contestação, o empregador alegou que Marcos nunca fez qualquer requerimento nesse sentido, apesar de morador de outro município da região metropolitana.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Segundo o texto da Consolidação das Leis do Trabalho, é correto afirmar que a lei de execução fiscal', '["A) é fonte subsidiária para a aplicação das normas na execução trabalhista.", "B) somente é fonte subsidiária para aplicação das normas na execução trabalhista caso não exista regramento sobre o assunto no Código de Processo Civil, que é a primeira fonte subsidiária da legislação processual do trabalho.", "C) somente é fonte subsidiária do Processo do Trabalho na execução das contribuições previdenciárias.", "D) somente é fonte subsidiária do Processo do Trabalho na execução das contribuições previdenciárias e sindicais."]'::jsonb, 'A', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Segundo o Código Tributário Nacional, remissão é', '["A) uma modalidade de extinção dos créditos tributários e consiste na liberação da dívida por parte do credor, respaldada em lei autorizativa.", "B) a perda do direito de constituir o crédito tributário pelo decurso do prazo.", "C) uma modalidade de exclusão dos créditos tributários com a liberação das penalidades aplicadas ao sujeito passivo, respaldada em lei autorizativa.", "D) uma modalidade de extinção dos créditos tributários em razão da compensação de créditos entre o sujeito ativo e o sujeito passivo, respaldada em lei autorizativa."]'::jsonb, 'A', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Na denúncia espontânea, o sujeito passivo tem direito à exclusão', '["A) da multa e dos juros.", "B) da multa e da correção monetária.", "C) apenas dos juros.", "D) apenas da multa."]'::jsonb, 'D', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Conforme a Constituição Federal, o veículo legislativo adequado para dispor sobre conflitos de competência entre os entes políticos em matéria tributária é a', '["A) medida provisória.", "B) lei complementar.", "C) emenda constitucional.", "D) lei ordinária."]'::jsonb, 'B', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Visando fomentar a indústria brasileira, uma nova lei, publicada em 18/02/2010, majorou a alíquota do Imposto sobre Produtos Industrializados (IPI), bem como majorou a alíquota do Imposto sobre Exportação (IE). A partir de que data a nova alíquota poderá ser exigida para o IPI e para o IE?', '["A) Imediatamente para ambos.", "B) No exercício financeiro seguinte para ambos.", "C) 90 dias após a publicação da lei para o IPI e imediatamente para o IE.", "D) 90 dias após o exercício financeiro seguinte para o IPI e no exercício financeiro seguinte para o IE."]'::jsonb, 'C', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Determinada pessoa, havendo arrematado imóvel em leilão judicial ocorrido em processo de execução fiscal para a cobrança de Imposto Predial Urbano, vem a sofrer a exigência pelo saldo devedor da execução não coberto pelo preço da arrematação.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Nos autos de uma ação de divórcio, os ex-cônjuges, casados em regime de comunhão total de bens, dividiram o patrimônio total existente da seguinte maneira: o imóvel situado no Município X, no valor de R$ 50.000,00, pertencerá ao ex-marido, enquanto o imóvel situado no Município Y, no valor de R$ 30.000,00, pertencerá à ex-esposa. Assinale a alternativa correta quanto à tributação incidente nessa partilha.', '["A) O tributo a ser recolhido será o ITCMD, de competência do Estado, e incidirá sobre a base de cálculo no valor de R$ 10.000,00.", "B) O tributo a ser recolhido será o ITBI, sobre ambos os imóveis, cada qual para o município de localização do bem.", "C) O tributo a ser recolhido será o ITBI, de competência do Município, e incidirá sobre a base de cálculo no valor de R$ 10.000,00.", "D) Não há tributo a ser recolhido, pois, como o regime de casamento era o da comunhão total de bens, não há transferência de bens, mas simples repartição do patrimônio comum de cada ex-cônjuge."]'::jsonb, 'A', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Uma construtora com sede no Município do Rio de Janeiro constrói um edifício sob regime de empreitada na cidade de Nova Iguaçu, onde não possui estabelecimento. A competência para a imposição do Imposto Municipal Sobre Serviços (ISS) caberá à municipalidade', '["A) do Rio de Janeiro, porque é o município onde a construtora tem a sua sede social.", "B) de Nova Iguaçu, porque é o local onde foi construído o edifício.", "C) do Rio de Janeiro, porque construção civil não é prestação de serviços.", "D) do Rio de Janeiro, porque a construtora não tem estabelecimento em Nova Iguaçu e, em razão do princípio da territorialidade, não pode ser exigido o tributo sobre contribuintes estabelecidos fora do território de cada Ente Federado."]'::jsonb, 'B', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A imunidade recíproca impede que', '["A) a União cobre Imposto de Renda sobre os juros das aplicações financeiras dos Estados e dos Municípios.", "B) o Município cobre a taxa de licenciamento de obra da União.", "C) o Estado cobre contribuição de melhoria em relação a bem do Município valorizado em decorrência de obra pública.", "D) o Estado cobre tarifa de água consumida em imóvel da União."]'::jsonb, 'A', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A Lei 9.985/2001, que instituiu o Sistema Nacional de Unidades de Conservação – SNUC, previu que as unidades de conservação devem dispor de uma zona de amortecimento definida no plano de manejo.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'O Estudo de Impacto de Vizinhança – EIV é uma espécie do gênero Avaliação de Impacto Ambiental e está disciplinado no Estatuto da Cidade, que estabelece e enumera os instrumentos da política de desenvolvimento urbano, de acordo com seus arts. 4º e 36 a 38. A esse respeito, assinale a alternativa correta.', '["A) As atividades de relevante e significativo impacto ambiental que atingem mais de um Município são precedidas de estudo de impacto de vizinhança.", "B) O estudo de impacto de vizinhança só pode ser exigido em área rural pelo órgão ambiental municipal.", "C) A Avaliação de Impacto Ambiental é exigida para analisar o adensamento populacional e a geração de tráfego e demanda por transporte público advindos da edificação de um prédio.", "D) A elaboração de estudo de impacto de vizinhança não substitui a elaboração de estudo prévio de impacto ambiental, requerida nos termos da legislação ambiental."]'::jsonb, 'D', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'O prazo para reclamar sobre vício oculto de produto durável é de', '["A) 90 (noventa) dias a contar da aquisição do produto.", "B) 90 (noventa) dias a contar da entrega do produto.", "C) 30 (trinta) dias a contar da entrega do produto.", "D) 90 (noventa) dias a contar de quando ficar evidenciado o vício."]'::jsonb, 'D', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A supressão de vegetação primária e secundária no estágio avançado de regeneração somente poderá ser autorizada em caso de utilidade pública, sendo que a vegetação secundária em estágio médio de regeneração poderá ser suprimida nos casos de utilidade pública e interesse social, em todos os casos devidamente caracterizados e motivados em procedimento administrativo próprio, quando inexistir alternativa técnica e locacional ao empreendimento proposto, conforme o disposto no art. 14 da Lei 11.428/2006, que dispõe sobre a utilização e proteção da vegetação nativa do bioma Mata Atlântica. A esse respeito, assinale a alternativa correta.', '["A) Um advogado de proprietário de terreno urbano afirma ser possível a obtenção de licença ambiental para edificação de condomínio residencial com supressão de Mata Atlântica com base em utilidade pública.", "B) A licença ambiental de empreendimento de relevante e significativo impacto ambiental localizado em terreno recoberto de Mata Atlântica não pode ser concedida em hipótese alguma.", "C) Um produtor de pequena propriedade ou posse rural entende que é possível a obtenção de licença ambiental para atividade agroflorestal sustentável, tendo como motivo o interesse social.", "D) Desde que obtida a autorização de supressão de vegetação de Mata Atlântica, com base na Lei 11.428/2006, não é aplicável a legislação que exige a licença ambiental, de acordo com a CRFB/88, a Lei 6.938/81 e o Decreto 99.274/90."]'::jsonb, 'C', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Em sua primeira viagem com seu carro zero quilômetro, Joaquim, fechado por outro veículo, precisa dar uma freada brusca para evitar um acidente. O freio não funciona, o que leva Joaquim, transtornado, a jogar o carro para o acostamento e, em seguida, abandonar a estrada. Felizmente, nenhum dano material ou físico acontece ao carro nem ao motorista, que, muito abalado, mal consegue acessar seu celular para pedir auxílio. Com a ajuda de moradores locais, se recupera do imenso susto e entra em contato com seus familiares.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Considerando a prática de ato infracional por criança ou adolescente, é correto afirmar que', '["A) a prestação de serviços comunitários consiste na realização de tarefas gratuitas de interesse geral, por período não excedente a 1 (um) ano, em entidades assistenciais, hospitais, escolas e outros estabelecimentos congêneres, bem como em programas comunitários ou governamentais.", "B) em se tratando de ato infracional com reflexos patrimoniais, a autoridade poderá determinar, se for o caso, que o adolescente restitua a coisa, promova o ressarcimento do dano, ou, por outra forma, compense o prejuízo da vítima.", "C) a internação, por constituir medida privativa de liberdade do menor, não poderá exceder o período de 5 (cinco) anos.", "D) entre as garantias processuais garantidas ao adolescente encontra-se o direito de solicitar a presença de seus pais ou responsável em qualquer fase do procedimento. Contudo, não poderá o menor ser ouvido pessoalmente pela autoridade competente, devendo em todo o caso ser assistido pelos genitores."]'::jsonb, 'B', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Pierre de Oliveira nasceu na França, filho de pai brasileiro que à época se encontrava em viagem privada de estudos) e mãe francesa. Viveu até os 25 anos em Paris, onde se formou em análise de sistemas e se pós-graduou em segurança de rede. Em 2007, Pierre foi convidado por uma universidade brasileira para fazer parte de um projeto de pesquisa destinado a desenvolver um sistema de segurança para uso de instituições financeiras. Embora viajasse com frequência para a França, Pierre passou a residir no Brasil, optando, em 2008, pela nacionalidade brasileira. No início de 2010, uma investigação conjunta entre as polícias brasileira e francesa descobriu que Pierre fez parte, no passado, de uma quadrilha internacional de hackers. Detido em São Paulo, ele confessou que, entre 2004 e 2005, quando ainda vivia em Paris, invadiu mais de uma vez a rede de um grande banco francês, desviando recursos para contas localizadas em paraísos fiscais.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Com relação aos procedimentos para a perda e a suspensão do poder familiar regulados pelo Estatuto da Criança e do Adolescente, é correto afirmar que', '["A) a autoridade judiciária, ouvido o Ministério Público, poderá decretar liminar ou incidentalmente a suspensão do poder familiar, independentemente da gravidade do motivo.", "B) o procedimento para perda ou suspensão do poder familiar dispensa que os pais sejam ouvidos, mesmo se estes forem identificados e estiverem em local conhecido.", "C) o procedimento para perda ou suspensão do poder familiar terá início por provocação do Ministério Público ou de quem tenha legítimo interesse.", "D) em conformidade com a nova redação dada pela Lei 12.010, de 3 de agosto de 2009, o prazo máximo para a conclusão do procedimento de perda ou suspensão do poder familiar será de 180 (cento e oitenta) dias."]'::jsonb, 'C', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Em relação aos princípios previstos no Código de Defesa do Consumidor, assinale a alternativa correta.', '["A) O CDC é uma norma tipificadora de condutas, prevendo expressamente o comportamento dos consumidores e dos fornecedores.", "B) A boa-fé prevista no CDC é a boa-fé subjetiva.", "C) O princípio da vulnerabilidade, que presume ser o consumidor o elo mais fraco da relação de consumo, diz respeito apenas à vulnerabilidade técnica.", "D) O princípio da transparência impõe um dever comissivo e um omissivo, ou seja, não pode o fornecedor deixar de apresentar o produto tal como ele se encontra nem pode dizer mais do que ele faz; não pode, portanto, mais existir o dolus bonus."]'::jsonb, 'D', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A Conferência de Bretton Woods (1944), realizada no ocaso da Segunda Guerra Mundial, é considerada um marco na história do Direito Internacional no século XX porque', '["A) estabeleceu as bases do sistema econômico e financeiro internacional, por meio da criação do Banco Mundial – BIRD, do Fundo Monetário Internacional - FMI e do Acordo Geral de Tarifas Aduaneiras e Comércio - GATT.", "B) inaugurou uma nova etapa na cooperação política internacional ao extinguir a Liga das Nações e transferir a Corte Internacional de Justiça para a estrutura da então recém-criada Organização das Nações Unidas – ONU.", "C) criou o sistema internacional de proteção aos direitos humanos, a partir da adoção da Declaração Universal dos Direitos Humanos, do Pacto Internacional de Direitos Civis e Políticos e do Pacto Internacional de Direitos Econômicos, Sociais e Culturais.", "D) criou o Tribunal de Nuremberg, corte ad hoc responsável pelo julgamento dos principais comandantes nazistas e seus colaboradores diretos pelos crimes de guerra cometidos durante a Segunda Guerra Mundial."]'::jsonb, 'A', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Em junho de 2009, uma construtora brasileira assina, na Cidade do Cabo, África do Sul, contrato de empreitada com uma empresa local, tendo por objeto a duplicação de um trecho da rodovia que liga a Cidade do Cabo à capital do país, Pretória. As contratantes elegem o foro da comarca de São Paulo para dirimir eventuais dúvidas. Um ano depois, as partes se desentendem quanto aos critérios técnicos de medição das obras e não conseguem chegar a uma solução amigável. A construtora brasileira decide, então, ajuizar, na justiça paulista, uma ação rescisória com o objetivo de colocar termo ao contrato.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'Esculápio, advogado, inscrito, há longos anos, na OAB, após aprovação em Exame de Ordem, é surpreendido com a notícia de que o advogado Sófocles, que atua no seu escritório em algumas causas, fora entrevistado por jornalista profissional, tendo afirmado ser usuário habitual de drogas. A entrevista foi divulgada amplamente. Após conversas reservadas entre os advogados, os termos da entrevista são confirmados, bem como o vício portado. Não há acordo quanto a eventual tratamento de saúde, afirmando o advogado Sófocles que continuaria a praticar os atos referidos.  Diante dessa narrativa, à luz da legislação aplicável aos advogados, é correto afirmar que', '["A) não há penalidade prevista, uma vez que se trata de questão circunscrita à Saúde Pública.", "B) o advogado pode ser excluído dos quadros da OAB.", "C) a sanção disciplinar se aplica a eventual uso de drogas.", "D) no caso em tela, há sanção disciplinar aplicável."]'::jsonb, 'D', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'Os advogados Pedro e João desejam estabelecer sociedade de advogados com o fito de regularizar o controle dos seus fluxos de honorários e otimizar despesas. Estabelecem contrato e requerem o seu registro no órgão competente. À luz da legislação aplicável aos advogados, é correto afirmar que', '["A) é possível a participação de advogados em sociedades sediadas em áreas territoriais de seccionais diversas.", "B) o Código de Ética não se aplica individualmente aos profissionais que compõem sociedade de advogados.", "C) podem existir sociedades mistas de advogados e contadores.", "D) a procuração é sempre coletiva quando atuante sociedade de advogados."]'::jsonb, 'A', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'Hércules, advogado recém-formado, é procurado por familiares de uma pessoa que descobriu, por vias transversas, estar sendo investigada em processo sigiloso, mas não tem ciência do objeto da investigação. Sem portar instrumento de procuração, dirige-se ao órgão investigador competente para obter informações, identificando-se como advogado do investigado. A autoridade competente, em decisão escrita, indefere o postulado, por estar ausente o instrumento do mandato e, ainda, ser a investigação sigilosa. Diante dessas circunstâncias, à luz da legislação aplicável, é correto afirmar que', '["A) o acesso a processo sigiloso é possível aos advogados somente quando requeiram a prática de ato.", "B) o acesso dos advogados dos interessados a processos sigilosos romperia com a proteção que eles mereceriam.", "C) o processo sigiloso é acessível a advogado portando instrumento de mandato.", "D) mesmo sem urgência, a atuação do advogado poderia ocorrer, sem mandato, em processo sigiloso."]'::jsonb, 'C', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'O advogado Walter recebe correspondência eletrônica relatando fatos que o seu cliente apresentou como importantes para constar em processo judicial a ser iniciado. Expressamente, em outra mensagem também eletrônica, autorizou a utilização das informações nas peças judiciais. Proposta a ação, os fatos foram publicizados, vindo o cliente a se arrepender da autorização dada. Com isso, busca reverter a situação por ele criada. Diante da informação de que, uma vez nos autos processuais, não poderia haver retirada das petições apresentadas, ameaça o profissional com futura representação disciplinar. O cliente não negou ter autorizado a utilização das informações.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'Juvenal, estagiário regularmente inscrito nos Quadros da OAB, em processo no qual se encontra indicado como tal, retira do cartório os autos do processo, deixando de devolvê-los no prazo legal. Regularmente intimado, mantém a sua inércia. Em termos disciplinares, é correto afirmar que', '["A) o estagiário não sofre sanções disciplinares.", "B) o advogado responsável pelo estagiário é o destinatário das sanções nesse caso.", "C) não há diferença na atuação do estagiário e do advogado para efeito de sanções disciplinares.", "D) no caso em tela, não haverá qualquer sanção nem ao advogado nem ao estagiário."]'::jsonb, 'B', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'Túlio, advogado, é surpreendido ao praticar crime inafiançável, sendo preso em flagrante pela autoridade policial. A OAB é comunicada, e, por meio de membro da Comissão de Prerrogativas, acorre advogado ao local onde estão sendo realizados os trâmites procedimentais. Nos termos das normas estatutárias, é correto afirmar que', '["A) a prisão do advogado que demanda a intervenção da OAB é a originária do exercício profissional.", "B) o fato de a prisão atingir advogado indica a presença do representante da OAB.", "C) só a prisão determinada pelo juiz é que permite a participação dos representantes da OAB.", "D) a prisão preventiva é aquela que está circunscrita na atuação da OAB."]'::jsonb, 'A', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'Em termos de processo disciplinar perante a OAB, é correto dizer que, havendo representação contra presidente de seccional, o órgão competente será o', '["A) próprio Conselho Seccional, impedido o presidente.", "B) Conselho Federal da OAB.", "C) Conselho Federal da OAB, quando houver impedimento de dois terços do Conselho Seccional de origem para o julgamento.", "D) Conselho Seccional que for escolhido pelo Conselho Federal da OAB, por maioria absoluta."]'::jsonb, 'B', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'Semprônio reside no Estado W, onde mantém o seu escritório de advocacia, mas requer sua inscrição principal no Estado K, onde, em alguns anos, pretende estabelecer domicílio. No concernente ao tema, à luz das normas estatutárias, é correto afirmar que', '["A) o advogado pode eleger qualquer seccional para inscrição principal ao seu arbítrio.", "B) o Conselho Federal pode autorizar a inscrição principal fora da sede do escritório do advogado.", "C) na dúvida entre domicílios, prevalece o da sede principal do exercício da advocacia.", "D) a inscrição principal está subordinada ao domicílio profissional do advogado."]'::jsonb, 'D', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'A prescrição para a cobrança de honorários advocatícios tem como termo inicial, consoante as normas estatutárias,', '["A) o início do contrato de prestação de serviços.", "B) a sentença que julga procedente o pedido em favor do cliente do advogado.", "C) a data da revogação do mandato.", "D) o dia do primeiro ato extrajudicial."]'::jsonb, 'C', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'Caio é eleito Senador da República e escolhido para compor a mesa do referido órgão legislativo. Como advogado regularmente inscrito nos quadros da OAB, pretende atuar em causa própria e realiza consulta nesse sentido à OAB. Quanto ao tema em foco, de acordo com as regras estatutárias, é correto afirmar que a atuação de Caio', '["A) é possível, pois a função exercida caracteriza mero impedimento.", "B) não é possível, sendo o caso de incompatibilidade mesmo em causa própria.", "C) em causa própria constitui uma exceção aplicável ao caso.", "D) poderá ocorrer, nessa situação, mediante autorização especial."]'::jsonb, 'B', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'Caio, professor vinculado à Universidade Federal, ministrando aulas no curso de Direito, resolve atuar, em causa própria, pleiteando benefícios tributários em face da União Federal. Nos termos do Estatuto, é correto afirmar que', '["A) é situação peculiar que permite o exercício da advocacia mesmo contra entidade vinculada.", "B) a situação caracteriza impedimento, uma vez que há vínculo da Universidade com a União Federal.", "C) o docente em cursos de Direito não pode exercer a advocacia, sendo circunstância de incompatibilidade.", "D) enquanto durar o exercício do magistério, a inscrição na OAB permanecerá suspensa."]'::jsonb, 'A', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'Mévio aceita defender um cliente. Após ampla pesquisa, verifica que a legislação ordinária não acolhe a pretensão dele. Elabora, pois, a tese de que a legislação que não permite o acolhimento da pretensão do seu constituído padeceria do vício de inconstitucionalidade e recomenda que não haja o cumprimento da referida norma. À luz das normas estatutárias, é correto afirmar que', '["A) a situação é permitida, diante do possível vício alegado pelo advogado.", "B) se caracteriza a hipótese de postulação com má-fé contra literal disposição de lei.", "C) mesmo sendo a lei eivada de vício, não seria possível presumir boa-fé.", "D) ao pleitear contra expressa disposição de lei no caso referido, presume-se a má-fé."]'::jsonb, 'A', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Em 2010, o Congresso Nacional aprovou por Decreto Legislativo a Convenção Internacional sobre os Direitos das Pessoas com Deficiência. Essa convenção já foi aprovada na forma do artigo 5º, § 3º, da Constituição, sendo sua hierarquia normativa de', '["A) lei federal ordinária.", "B) emenda constitucional.", "C) lei complementar.", "D) status supralegal."]'::jsonb, 'B', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Com relação aos chamados “direitos econômicos, sociais e culturais”, é correto afirmar que', '["A) são direitos humanos de segunda geração, o que significa que não são juridicamente exigíveis, diferentemente do que ocorre com os direitos civis e políticos.", "B) são previstos, no âmbito do sistema interamericano, no texto original da Convenção Americana sobre Direitos Humanos (Pacto de San José da Costa Rica).", "C) formam, juntamente com os direitos civis e políticos, um conjunto indivisível de direitos fundamentais, entre os quais não há qualquer relação hierárquica.", "D) incluem o direito à participação no processo eleitoral, à educação, à alimentação e à previdência social."]'::jsonb, 'C', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Determinado congressista é flagrado afirmando em entrevista pública que não se relaciona com pessoas de etnia diversa da sua e não permite que, no seu prédio residencial, onde atua como síndico, pessoas de etnia negra frequentem as áreas comuns, os elevadores sociais e a piscina do condomínio. Ciente desses atos, a ONG TudoAfro relaciona as pessoas prejudicadas e concita a representação para fins criminais com o intuito de coibir os atos descritos. À luz das normas constitucionais e dos direitos humanos, é correto afirmar que', '["A) o crime de racismo é afiançável, sendo o valor fixado por decisão judicial.", "B) o prazo de prescrição incidente sobre o crime de racismo é de vinte anos.", "C) nos casos de crime de racismo, a pena cominada é de detenção.", "D) o crime de racismo não está sujeito a prazo extintivo de prescrição."]'::jsonb, 'D', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Roberta Caballero, de nacionalidade argentina, está no Brasil desde 2008, como correspondente estrangeira do jornal “El Diário”, sediado em Buenos Aires. Roberta possui visto temporário, válido por quatro anos. Em 2011, pouco antes do vencimento do visto, Roberta recebe um convite do editor de um jornal brasileiro, sediado em São Paulo, para ali trabalhar na condição de repórter, sob sua supervisão, mediante contrato de trabalho.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Com relação à chamada “norma imperativa de Direito Internacional geral”, ou jus cogens, é correto afirmar que é a norma', '["A) prevista no corpo de um tratado que tenha sido ratificado por todos os signatários, segundo o direito interno de cada um.", "B) reconhecida pela comunidade internacional como aplicável a todos os Estados, da qual nenhuma derrogação é permitida.", "C) aprovada pela Assembleia Geral das Nações Unidas e aplicável a todos os Estados membros, salvo os que apresentarem reserva expressa.", "D) de direito humanitário, expressamente reconhecida pela Corte Internacional de Justiça, aplicável a todo e qualquer Estado em situação de conflito."]'::jsonb, 'B', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A respeito do regime de responsabilidade do Presidente da República, assinale a alternativa correta.', '["A) O ato do Presidente da República que atenta contra o livre exercício do Poder Legislativo, do Poder Judiciário, do Ministério Público e dos Poderes constitucionais das unidades da Federação é considerado crime de responsabilidade.", "B) O Presidente ficará suspenso de suas funções nos crimes de responsabilidade somente após a condenação pelo órgão competente.", "C) Compete ao Congresso Nacional processar e julgar o Presidente da República nos crimes de responsabilidade.", "D) Só se admite acusação contra o Presidente da República por três quintos da Câmara dos Deputados."]'::jsonb, 'A', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A respeito da garantia constitucional do acesso ao Poder Judiciário, assinale a alternativa correta.', '["A) O Poder Judiciário admitirá ações relativas à disciplina e às competições desportivas paralelamente às ações movidas nas instâncias da justiça desportiva.", "B) De acordo com posição consolidada do Supremo Tribunal Federal, não ofende a garantia de acesso ao Poder Judiciário a exigência de depósito prévio como requisito de admissibilidade de ação judicial na qual se pretenda discutir a exigibilidade de crédito tributário.", "C) A todos, no âmbito judicial e administrativo, são assegurados a razoável duração do processo e os meios que garantam a celeridade de sua tramitação.", "D) É assegurado a todos, mediante pagamento de taxas, o direito de petição aos Poderes Públicos em defesa de direitos ou contra ilegalidade ou abuso de poder."]'::jsonb, 'C', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Em relação ao controle de constitucionalidade em face da Constituição Estadual, assinale a alternativa correta.', '["A) Compete aos Estados a instituição de representação de inconstitucionalidade de leis ou atos normativos estaduais ou municipais em face da Constituição Estadual, reconhecida a legitimação para agir aos mesmos órgãos e entidades legitimados a propositura de ação direta de inconstitucionalidade.", "B) A decisão do Tribunal de Justiça que declara a inconstitucionalidade de lei local em face da Constituição Estadual é irrecorrível, ressalvada a oposição de embargos declaratórios.", "C) Não ofende a Constituição da República norma de Constituição Estadual que atribui legitimidade para a propositura de representação de inconstitucionalidade aos Deputados Estaduais e ao Procurador-Geral do Estado.", "D) Não é possível o controle de constitucionalidade no plano estadual, no modo concentrado, se a norma constitucional estadual tomada como parâmetro reproduzir idêntico conteúdo de norma constitucional federal."]'::jsonb, 'C', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'As alternativas a seguir apontam diferenças entre a ADI e a ADC, À EXCEÇÃO DE UMA. Assinale-a.', '["A) Rol de legitimados para a propositura da ação.", "B) Objeto da ação.", "C) Exigência de controvérsia judicial relevante.", "D) Manifestação do Advogado-Geral da União."]'::jsonb, 'A', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A respeito da distribuição de competências adotada pela Constituição brasileira, assinale a alternativa correta.', '["A) A competência material da União pode ser delegada aos Estados, por lei complementar.", "B) À União compete legislar sobre direito processual e normas gerais de procedimentos.", "C) A competência para legislar sobre direito urbanístico é privativa dos Municípios, pois é matéria de interesse local.", "D) A competência para legislar sobre defesa dos recursos naturais é privativa da União, pois é matéria de interesse nacional."]'::jsonb, 'B', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Os direitos políticos não podem ser cassados. Podem, no entanto, sofrer perda ou suspensão à luz das normas constitucionais pelo seguinte fundamento:', '["A) condenação cível sem trânsito em julgado.", "B) incapacidade civil relativa, declarada judicialmente.", "C) cancelamento de naturalização por decisão administrativa.", "D) improbidade administrativa."]'::jsonb, 'D', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Considere a hipótese de Deputado Federal que cometeu crime (comum) após a diplomação. Nesse caso, é correto afirmar que', '["A) a Câmara dos Deputados pode sustar o andamento da ação penal.", "B) o STF só pode receber a denúncia após a licença da Câmara dos Deputados.", "C) o STF só pode receber a denúncia após a licença do Congresso Nacional.", "D) o Congresso Nacional pode sustar o andamento da ação penal."]'::jsonb, 'A', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Washington, adolescente com 14 (quatorze) anos, movido pelo desejo de ajudar seus genitores no sustento do núcleo familiar pobre, pretende iniciar atividade laborativa como ensacador de compras na pequena mercearia Tudo Tem, que funciona 24h, localizada em sua comunidade. Recentemente, esta foi pacificada pelas Forças de Segurança Nacional. Tendo como substrato a tutela do Estatuto da Criança e do Adolescente no tocante ao Direito à Profissionalização e à Proteção no Trabalho, assinale a alternativa correta.', '["A) Washington poderá ser contratado como ensacador de compras, mesmo não sendo tal atividade de aprendizagem, pois, como já possui 14 (quatorze) anos, tem discernimento suficiente para firmar o contrato de trabalho e, assim, prestar auxílio material aos seus pais, adotando a louvável atitude de preferir o trabalho às ruas.", "B) Como a comunidade onde reside Washington foi pacificada pelas forças de paz, não há falar em local perigoso ou insalubre para o menor; assim, poderá o adolescente exercer a carga horária laborativa no período das 22h às 24h, sem qualquer restrição legal, desde que procure outra atividade laborativa que seja de formação técnico-profissional.", "C) Washington não poderá trabalhar na mercearia como ensacador de compras, pois tal atividade não é enquadrada como de formação técnico-profissional; portanto, não se pode afirmar que o menor exercerá atividade laborativa na condição de aprendiz.", "D) Na condição de aprendiz, não é necessário que o adolescente goze de horário especial compatível com a garantia de acesso e frequência obrigatória ao ensino regular."]'::jsonb, 'C', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'No tocante às normas contidas no Estatuto da Criança e do Adolescente, é correto afirmar que', '["A) a medida socioeducativa de internação aplicada em razão do descumprimento reiterado e injustificável da medida anteriormente imposta ao adolescente infrator não poderá ser superior a três meses.", "B) o adolescente apreendido em flagrante de ato infracional será imediatamente encaminhado ao Juiz de Direito em exercício na Vara da Infância e Juventude, que decidirá sobre a necessidade ou não de seu acautelamento provisório.", "C) a concessão da remissão, que prescinde da homologação da Autoridade Judiciária, é medida que o membro do Ministério Público atribuído poderá adotar no processamento de ato infracional.", "D) ao ato infracional praticado por crianças corresponderão as seguintes medidas socioeducativas: advertência, obrigação de reparar o dano, prestação de serviços à comunidade, liberdade assistida e inserção em regime de semiliberdade."]'::jsonb, 'A', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Em âmbito federal, o direito de a Administração Pública anular atos administrativos eivados de vício de ilegalidade, dos quais decorram efeitos favoráveis para destinatários de boa-fé', '["A) não se submete a prazo prescricional.", "B) não se submete a prazo decadencial.", "C) prescreve em 10 (dez) anos, contados da data em que praticado o ato.", "D) decai em 5 (cinco) anos, contados da data em que praticado o ato."]'::jsonb, 'D', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A qualificação como Organizações da Sociedade Civil de Interesse Público (OSCIPs) de pessoas jurídicas de direito privado, sem fins lucrativos, cujos objetivos sociais e normas estatutárias atendam aos requisitos previstos na respectiva lei é ato', '["A) vinculado ao cumprimento dos requisitos estabelecidos em lei.", "B) complexo, uma vez que somente se aperfeiçoa com a instituição do Termo de Parceria.", "C) discricionário, uma vez que depende de avaliação administrativa quanto à sua conveniência e oportunidade.", "D) composto, subordinando-se à homologação da Chefia do Poder Executivo."]'::jsonb, 'A', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'O contrato de prestação de serviços de que a Administração Pública seja a usuária direta ou indireta, ainda que envolva a execução de obra ou fornecimento e instalação de bens, denomina-se concessão', '["A) comum.", "B) patrocinada.", "C) administrativa.", "D) de uso de bem público."]'::jsonb, 'C', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Ao tomar conhecimento de que o serviço público de transporte aquaviário concedido estava sendo prestado de forma inadequada, causando gravíssimos transtornos aos usuários, o ente público, na qualidade de poder concedente, instaurou regular processo administrativo de verificação da inadimplência da concessionária, assegurando-lhe o contraditório e a ampla defesa. Ao final do processo administrativo, restou efetivamente comprovada a inadimplência, e o poder concedente deseja extinguir a concessão por inexecução contratual.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A Lei 11.107, de 6 de abril de 2005, dispõe sobre normas gerais para a União, os Estados, o Distrito Federal e os Municípios contratarem consórcios públicos para a realização de objetivos de interesse comum. A respeito do regime jurídico aplicável a tais consórcios públicos, assinale a alternativa correta.', '["A) É vedada a celebração de contrato de consórcio público cujo valor seja inferior a R$ 20.000.000,00 vinte milhões) de reais.", "B) Os consórcios públicos na área de saúde, em razão do regime de gestão associada, são dispensados de obedecer aos princípios que regulam o Sistema Único de Saúde.", "C) É vedada a celebração de contrato de consórcio público para a prestação de serviços cujo período seja inferior a 5 (cinco) anos.", "D) A União somente participará de consórcios públicos em que também façam parte todos os Estados em cujos territórios estejam situados os Municípios consorciados."]'::jsonb, 'D', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Antônio, vítima em acidente automobilístico, foi atendido em hospital da rede pública do Município de Mar Azul e, por imperícia do médico que o assistiu, teve amputado um terço de sua perna direita. Nessa situação hipotética, respondem pelo dano causado a Antônio', '["A) o Município de Mar Azul e o médico, solidária e objetivamente.", "B) o Município de Mar Azul, objetivamente, e o médico, regressivamente, em caso de dolo ou culpa.", "C) o Município de Mar Azul, objetivamente, e o médico, subsidiariamente.", "D) o Município de Mar Azul, objetivamente, e o médico, solidária e subjetivamente."]'::jsonb, 'B', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Noêmia, proprietária de uma casa litorânea, regularmente constituiu usufruto sobre o aludido imóvel em favor de Luísa, mantendo, contudo, a sua propriedade. Inesperadamente, sobreveio uma severa ressaca marítima, que destruiu por completo o imóvel. Ciente do ocorrido, Noêmia decidiu reconstruir integralmente a casa às suas expensas, tendo em vista que o imóvel não se encontrava segurado.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Jonas, maior e capaz, confiou em depósito a Silas, também maior e capaz, por instrumento particular, dois automóveis de sua propriedade para serem conservados por seis meses, estabelecendo, como remuneração, o pagamento de certa quantia em dinheiro a Silas. Findo o prazo, caberia a Silas restituir os automóveis na residência de Jonas. Na vigência do depósito, Silas decidiu, certo dia, utilizar um dos automóveis para ir ao trabalho e, quando já regressava, foi abalroado, sem culpa sua, por seu vizinho Francisco, em uma moto, amassando a porta lateral direita. Transcorrido o prazo ajustado, Silas providenciou a entrega dos dois automóveis no local estipulado.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Rodolfo, brasileiro, engenheiro, solteiro, sem ascendentes ou descendentes, desapareceu de seu domicílio há 11 (onze) meses e até então não houve qualquer notícia sobre seu paradeiro. Embora tenha desaparecido, deixou Lisa, uma amiga, como mandatária para a finalidade de administrar-lhe os bens. Todavia, por motivos de ordem pessoal, Lisa não quis exercer os poderes outorgados por Rodolfo em seu favor, renunciando expressamente ao mandato.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'O negócio jurídico depende da regular manifestação de vontade do agente envolvido. Nesse sentido, o art. 138 do Código Civil dispõe que “são anuláveis os negócios jurídicos quando as declarações de vontade emanarem de erro substancial que poderia ser percebido por pessoa de diligência normal, em face das circunstâncias do negócio”.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Gustavo tornou-se fiador do seu amigo Henrique, em razão de operação de empréstimo bancário que este tomou com o Banco Pechincha. No entanto, Gustavo, apreensivo, descobriu que Henrique está desempregado há algum tempo e que deixou de pagar várias parcelas do referido empréstimo. Sem o consentimento de Gustavo, Henrique e o Banco Pechincha aditaram o contrato original, tendo sido concedida moratória a Henrique.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Acerca da servidão de aqueduto, assinale a alternativa correta.', '["A) Não se aplicam à servidão de aqueduto as regras pertinentes à passagem de cabos e tubulações.", "B) O aqueduto deverá ser construído de maneira que cause o menor prejuízo aos proprietários dos imóveis vizinhos, e a expensas do seu dono, mas a quem não incumbem as despesas de conservação.", "C) Se o uso das águas não se destinar à satisfação das exigências primárias, o proprietário do aqueduto não deverá ser indenizado pela retirada das águas supérfluas aos seus interesses de consumo.", "D) O proprietário do prédio serviente, ainda que devidamente indenizado pela passagem da servidão do aqueduto, poderá exigir que seja subterrânea a canalização que atravessa áreas edificadas, pátios, jardins ou quintais."]'::jsonb, 'D', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Suponha que tenha sido publicada no Diário Oficial da União, do dia 26 de abril de 2011 (terça-feira), uma lei federal, com o seguinte teor:
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Quando a sentença que reconhece obrigação de pagar não determina o valor devido, procede-se à sua liquidação, para que, então, possa dar-se o seu cumprimento. Em relação à sistemática da liquidação no direito brasileiro, assinale a alternativa correta.', '["A) A liquidação de sentença tem natureza jurídica de ação autônoma.", "B) A liquidação pode ser requerida mesmo na pendência de recurso ainda não julgado pelo tribunal, hipótese em que deve ser processada em autos apartados no juízo de origem.", "C) Requerida a liquidação, deve a parte contrária ser pessoalmente intimada.", "D) Sempre que o pedido for genérico, o juiz pode proferir sentença ilíquida."]'::jsonb, 'B', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Júlia ingressou com ação de indenização por danos morais e materiais em face da Gráfica Bela Escrita, bem como do Ateliê Alta-Costura, sob a alegação de que o seu casamento não pôde ser realizado tendo em vista que a Gráfica escreveu o endereço errado do local da cerimônia em todos os convites confeccionados, e o Ateliê, por sua vez, não entregou o vestido de noiva no dia do casamento. Tendo sido ambos os réus regularmente citados, o Ateliê Alta-Costura apresentou contestação tempestiva, em que afirmou se isentar de responsabilidade, uma vez que o vestido de noiva já estava praticamente pronto, quando, na véspera da cerimônia, a noiva subitamente decidiu solicitar inúmeras alterações no modelo da roupa, o que inviabilizou a sua tempestiva entrega. A Gráfica Bela Escrita, por seu turno, não se manifestou nos autos.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'No âmbito do Direito Processual Civil, os legitimados ativos que proponham ação e interponham recursos poderão desistir deles, desde que respeitados os seguintes termos:', '["A) o credor poderá desistir de toda execução ou apenas de algumas medidas executivas, desde que suporte as custas e honorários advocatícios decorrentes da extinção dos embargos que versarem somente sobre questões processuais e, nos demais casos, quando houver anuência do embargante.", "B) o recorrente poderá desistir do recurso interposto a qualquer tempo, desde que não se trate de litisconsórcio e que a parte contrária, uma vez intimada, manifeste expressamente sua anuência.", "C) na intervenção de terceiros, a assistência obsta a que a parte principal desista da ação, que somente poderá ocorrer com a anuência expressa do assistente. Nesse caso, a desistência independe de homologação por sentença.", "D) a desistência da ação, que produz efeitos somente depois de homologada por sentença, implica extinção do processo com resolução do mérito. Caso tenha transcorrido o prazo para resposta do réu, o pedido de desistência estará sujeito ao seu consentimento."]'::jsonb, 'A', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'O rito comum sumário tem suas hipóteses de incidência expressamente disciplinadas no sistema processual civil pátrio. Tal rito apresenta trâmite mais célere que o observado pelo rito comum ordinário, e, exatamente por isso, as causas que o observam têm menor complexidade se comparadas às que tramitam pelo rito comum ordinário.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Em uma ação fundada na responsabilidade civil por suposto erro médico praticado por Cláudio, este foi regularmente citado e, no prazo legal, ofereceu contestação. Em razão do seu falecimento, no curso da lide, foi determinada a suspensão do processo e a habilitação de seus herdeiros ou sucessores no polo passivo. Sendo certo que tal irregularidade não foi sanada no prazo fixado pelo juízo, é correto afirmar, em relação ao processo, que', '["A) deve ser julgado extinto, sem resolução do mérito, por falta de pressupostos de constituição e de desenvolvimento válido e regular.", "B) deve ter regular prosseguimento, com a declaração da revelia e a consequente presunção de veracidade dos fatos alegados na inicial.", "C) deve prosseguir, com a declaração da revelia, cuja consequência ficará restrita à fluência de prazos independentemente de intimação.", "D) deve ser julgado extinto, sem resolução do mérito, por falta de uma das condições da ação."]'::jsonb, 'C', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A respeito das ações possessórias, assinale a alternativa correta.', '["A) A propositura da ação de reintegração de posse, quando cabível manutenção de posse, torna impossível o acolhimento do pedido, impondo a extinção sem resolução do mérito.", "B) Quando for ordenada a justificação prévia, o prazo para contestar contar-se-á da intimação do despacho que deferir ou não a medida liminar.", "C) É vedada a cumulação de pedidos com o pedido possessório.", "D) O possuidor tem direito a ser mantido na posse em caso de esbulho e reintegrado no de turbação."]'::jsonb, 'B', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'No âmbito do Código de Defesa do Consumidor, em relação ao princípio da boa-fé objetiva, é correto afirmar que', '["A) sua aplicação se restringe aos contratos de consumo.", "B) para a caracterização de sua violação imprescindível se faz a análise do caráter volitivo das partes.", "C) não se aplica à fase pré-contratual.", "D) importa em reconhecimento de um direito a cumprir em favor do titular passivo da obrigação."]'::jsonb, 'D', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Analisando o artigo 6º, V, do Código de Defesa do Consumidor, que prescreve: “São direitos básicos do consumidor: V – a modificação das cláusulas contratuais que estabeleçam prestações desproporcionais ou sua revisão em razão de fatos supervenientes que as tornem excessivamente onerosas”, assinale a alternativa correta.', '["A) Não traduz a relativização do princípio contratual da autonomia da vontade das partes.", "B) Almeja, em análise sistemática, precipuamente, a resolução do contrato firmado entre consumidor e fornecedor.", "C) Admite a incidência da cláusula rebus sic stantibus.", "D) Exige a imprevisibilidade do fato superveniente."]'::jsonb, 'C', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Contrato oneroso, em que alguém assume, em caráter profissional e sem vínculo de dependência, a obrigação de promover, em nome de outrem, mediante retribuição, a efetivação de certos negócios, em determinado território ou zona de mercado.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'É uma cláusula acessória ao contrato de comissão, no qual o comissário assume o gravame de responder solidariamente pela insolvência das pessoas com quem contratar em nome do comitente.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Em relação ao Direito Cambiário, é correto afirmar que', '["A) o aceite no cheque é dado pelo banco ou instituição financeira a ele equivalente, devendo ser firmado no verso do título.", "B) a duplicata, quando de prestação de serviços, pode ser emitida com vencimento a tempo certo da vista.", "C) o protesto é necessário para garantir o direito de regresso contra o(s) endossante(s) e o(s) avalista(s) do aceitante de uma letra de câmbio.", "D) o aval dado em uma nota promissória pode ser parcial, ainda que sucessivo."]'::jsonb, 'D', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Em relação à modificação do capital social das sociedades limitadas, assinale a alternativa correta.', '["A) Há direito de preferência do sócio no caso de aumento do capital social, exercendo, primeiro, esse direito o sócio majoritário, que poderá adquirir todas as quotas ou quantas lhe interessarem. Após exercido esse direito, caso restem quotas a serem adquiridas, terá preferência sobre os demais quem tiver maior número de quotas, e assim sucessivamente.", "B) Para que haja aumento do capital social, não há necessidade de os sócios terem integralizado totalmente suas quotas.", "C) Uma das hipóteses para que haja diminuição do capital social é que a sociedade tenha tido prejuízos que não serão mais recuperados, devendo-se, nesse caso, haver diminuição proporcional do valor das quotas, tornando-se efetiva essa diminuição a partir do momento em que for feita a averbação no cartório competente da ata da assembleia que a aprovou.", "D) A diminuição do valor do capital social é direito da sociedade, não podendo haver objeção por parte dos credores."]'::jsonb, 'C', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A sociedade empresária XYZ Computação Gráfica S.A. teve sua falência decretada. Na correspondente sentença, foi autorizada a continuação provisória das atividades da falida com o administrador judicial, fato esse que perdurou por um período de 10 (dez) meses.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A Empresa ABC Ltda. foi incorporada pela Empresa XYZ Ltda., em 15/06/2011, sendo que os sócios da empresa incorporada se aposentaram 7 (sete) dias após a data da realização do negócio jurídico. Em 30/06/2011, a Fiscalização da Secretaria da Receita Federal apurou crédito tributário, anterior à data da incorporação, resultante do não recolhimento de IRPJ, CSLL, entre outros tributos devidos da responsabilidade da Empresa ABC Ltda.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'O Imposto sobre Operações Relativas à Circulação de Mercadorias e sobre a Prestação de Serviços de Transporte Interestadual e Intermunicipal e de Comunicação tem seus princípios delineados na Constituição, que é complementada pela Lei Complementar 87/1996, com as alterações posteriores.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'José dos Anjos ajuíza ação anulatória de débito fiscal após realizar depósito do montante integral do crédito que busca a anulação. Nesse sentido, é correto afirmar que', '["A) o depósito prévio do montante integral é requisito de admissibilidade da ação ajuizada por José dos Anjos.", "B) o depósito do montante objeto de discussão judicial poderá ser levantado caso José dos Santos tenha seu pedido julgado procedente perante o juízo de primeiro grau.", "C) o depósito prévio do montante integral produz os efeitos de impedir a propositura da execução fiscal, bem como evita a fluência dos juros e a imposição de multa.", "D) caso o contribuinte saia vencido, caberá à Fazenda promover execução fiscal para fins de receber o crédito que lhe é devido."]'::jsonb, 'C', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A redação da Súmula Vinculante 28 ("É inconstitucional a exigência de depósito prévio como requisito de admissibilidade de ação judicial na qual se pretenda discutir a exigibilidade do crédito tributário") tem por escopo impedir a adoção de que princípio jurídico?', '["A) Venire Contra Factum Proprium.", "B) Exceção de contrato não cumprido.", "C) Solve et Repete.", "D) Contraditório e ampla defesa."]'::jsonb, 'C', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'O inciso VII do §1º do art. 225 da Constituição da República prevê a proteção da fauna e da flora, vedadas as práticas que coloquem em risco sua função ecológica, enquanto que o §1º do art. 231 do referido texto constitucional estabelece que são terras indígenas as habitadas por eles em caráter permanente e que podem ser utilizadas por esses povos, desde que necessárias ao seu bem-estar e à sua reprodução física e cultural.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Assinale a alternativa correta quanto ao licenciamento ambiental e ao acesso aos dados e informações existentes nos órgãos e entidades integrantes do Sisnama.', '["A) Caso a área que sofrerá o impacto ambiental seja considerada estratégica para o zoneamento industrial nacional de petróleo e gás e em áreas do pré-sal, o órgão ambiental poderá elaborar estudo prévio de impacto ambiental sigiloso.", "B) Um cidadão brasileiro pode solicitar informações sobre a qualidade do meio ambiente em um município aos órgãos integrantes do Sisnama, mediante a apresentação de título de eleitor e comprovação de domicílio eleitoral no local.", "C) A exigência de Estudo Prévio de Impacto Ambiental para aterros sanitários depende de decisão discricionária do órgão ambiental, que avaliará no caso concreto o potencial ofensivo da obra.", "D) Uma pessoa jurídica com sede na França poderá solicitar, aos órgãos integrantes do Sisnama, mediante requerimento escrito, mesmo sem comprovação de interesse específico, informações sobre resultados de monitoramento e auditoria nos sistemas de controle de poluição e de atividades potencialmente poluidoras das empresas brasileiras."]'::jsonb, 'D', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Com relação aos critérios para substituição da pena privativa de liberdade por restritiva de direitos, assinale a alternativa correta.', '["A) A substituição nunca poderá ocorrer se o réu for reincidente em crime doloso.", "B) Somente fará jus à substituição o réu que for condenado a pena não superior a 4 (quatro) anos.", "C) Em caso de descumprimento injustificado da pena restritiva de direitos, esta será convertida em privativa de liberdade, reiniciando-se o cumprimento da integralidade da pena fixada em sentença.", "D) Se superior a um ano, a pena privativa de liberdade pode ser substituída por uma pena restritiva de direitos e multa ou por duas restritivas de direitos."]'::jsonb, 'D', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'À luz da lei que dispõe sobre os Juizados Especiais Criminais Lei 9.099/95), assinale a alternativa correta.', '["A) A competência do juizado será determinada pelo lugar em que se consumar a infração penal.", "B) A citação será pessoal e se fará no próprio juizado, sempre que possível, ou por edital.", "C) O instituto da transação penal pode ser concedido pelo juiz sem a anuência do Ministério Público.", "D) Tratando-se de crime de ação penal pública incondicionada, não sendo caso de arquivamento, o Ministério Público poderá propor a aplicação imediata de pena restritiva de direitos ou multas, a ser especificada na proposta."]'::jsonb, 'D', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Tício praticou um crime de furto (art. 155 do Código Penal) no dia 10/01/2000, um crime de roubo (art. 157 do Código Penal) no dia 25/11/2001 e um crime de extorsão (art. 158 do Código Penal) no dia 30/5/2003. Tício foi condenado pelo crime de furto em 20/11/2001, e a sentença penal condenatória transitou definitivamente em julgado no dia 31/3/2002. Pelo crime de roubo, foi condenado em 30/01/2002, com sentença transitada em julgado definitivamente em 10/06/2003 e, pelo crime de extorsão, foi condenado em 20/8/2004, com sentença transitando definitivamente em julgado no dia 10/6/2006. Com base nos dados acima, bem como nos estudos acerca da reincidência e dos maus antecedentes, é correto afirmar que', '["A) na sentença do crime de furto, Tício é considerado portador de maus antecedentes e, na sentença do crime de roubo, é considerado reincidente.", "B) na sentença do crime de extorsão, Tício possui maus antecedentes em relação ao crime de roubo e é reincidente em relação ao crime de furto.", "C) cinco anos após o trânsito em julgado definitivo da última condenação, Tício será considerado primário, mas os maus antecedentes persistem.", "D) nosso ordenamento jurídico-penal prevê como tempo máximo para configuração dos maus antecedentes o prazo de cinco anos a contar do cumprimento ou extinção da pena e eventual infração posterior."]'::jsonb, 'B', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Osíris, jovem universitária de Medicina, soube estar gestante. Todavia, tratava-se de gravidez indesejada, e Osíris queria saber qual substância deveria ingerir para interromper a gestação. Objetivando tal informação, Osíris estimulou uma discussão em sala de aula sobre o aborto. O professor de Osíris, então, bastante animado com o interesse dos alunos sobre o assunto, passou também a emitir sua opinião, a qual era claramente favorável ao aborto. Referido professor mencionou, naquele momento, diversas substâncias capazes de provocar a interrupção prematura da gravidez, inclusive fornecendo os nomes de inúmeros remédios abortivos e indicando os que achava mais eficazes. Além disso, também afirmou que as mulheres deveriam ter o direito de praticar aborto sempre que achassem indesejável uma gestação. Nesse sentido, considerando-se apenas os dados mencionados, é correto afirmar que o professor de Osíris praticou', '["A) a contravenção penal prevista no art. 20 do Decreto-Lei 3.688/41, que dispõe: “anunciar processo, substância ou objeto destinado a provocar aborto”.", "B) o crime previsto no art. 286 do Código Penal, que dispõe: “incitar, publicamente, a prática de crime”.", "C) o crime previsto no art. 68 da Lei 8.078/90, que dispõe: “fazer ou promover publicidade que sabe ou deveria saber ser capaz de induzir o consumidor a se comportar de forma prejudicial ou perigosa à sua saúde ou segurança”.", "D) fato atípico."]'::jsonb, 'D', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Em relação ao cálculo da pena, é correto afirmar que', '["A) a análise da reincidência precede à verificação dos maus antecedentes, e eventual acréscimo de pena com base na reincidência deve ser posterior à redução pela participação de menor importância.", "B) é defeso ao juiz fixar a pena intermediária em patamar acima do máximo previsto, ainda que haja circunstância agravante a ser considerada.", "C) o acréscimo de pena pela embriaguez preordenada deve se feito posteriormente à redução pela confissão espontânea.", "D) é possível que o juiz, analisando as circunstâncias judiciais do art. 59 do Código Penal, fixe pena-base em patamar acima do máximo previsto."]'::jsonb, 'B', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Configura modalidade de peculato prevista no Código Penal', '["A) o peculato por erro de outrem, consistente na apropriação de bem ou valores que o funcionário tenha recebido pela facilidade que seu cargo lhe proporciona.", "B) o peculato eletrônico, modalidade anômala de peculato, consistente em inserir dados falsos, alterar ou modificar dados no sistema de informações da administração pública.", "C) o peculato-culposo, consistente na apropriação de bens ou valores que o funcionário tenha recebido por erro de outrem em razão do cargo público que exerce.", "D) o peculato-desvio, consistente no desvio de bens ou valores, pelo funcionário público, em benefício de terceiro."]'::jsonb, 'B', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Levando em consideração as modificações trazidas pela Lei 11.719/08, assinale a alternativa correta.', '["A) O Código de Processo Penal admite a figura da citação com hora certa, tal como ocorre no Código de Processo Civil.", "B) O rito comum ordinário é o reservado aos crimes apenados com reclusão, independentemente do montante da pena para eles prevista.", "C) Na mutatio libelli (em que a denúncia descreve determinado fato, mas as provas apontam que o fato delituoso é diverso), o Ministério Público deverá, após encerrada a instrução probatória, aditar a denúncia no prazo de 5 (cinco) dias sob pena de se operar a preclusão temporal.", "D) O rito sumário é o reservado para as infrações penais de menor potencial ofensivo."]'::jsonb, 'A', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A Lei 7.492/86 define os Crimes contra o Sistema Financeiro Nacional. Acerca do procedimento previsto para tais crimes, é correto afirmar que', '["A) quando a denúncia não for intentada no prazo legal, o ofendido poderá representar ao Procurador-Geral da República, para que este a ofereça, designe outro órgão do Ministério Público para oferecê-la ou determine o arquivamento das peças de informações recebidas.", "B) nos crimes previstos nessa lei, cometidos em quadrilha ou coautoria, o coautor ou partícipe que, por meio de confissão espontânea, revelar à autoridade policial ou judicial toda a trama delituosa terá sua pena reduzida de 1 (um) a 2/5 (dois quintos).", "C) a ação penal será promovida perante a Justiça Federal quando a infração for praticada em detrimento de bens e serviços de entes federais. Nos demais casos, será proposta perante a Justiça Estadual.", "D) os órgãos dos Ministérios Públicos Federal e Estadual, sempre que julgarem necessário, poderão requisitar, a qualquer autoridade, informação, documento ou diligência relativa à prova dos crimes previstos na Lei 7.492/86."]'::jsonb, 'A', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Em relação ao incidente de falsidade, é correto afirmar que', '["A) se reconhecida a falsidade por decisão irrecorrível, mandará desentranhar o documento e remetê-lo, com os autos do processo incidente, ao Ministério Público.", "B) arguida, por escrito, a falsidade de documento constante dos autos, o juiz observará o seguinte processo: mandará autuar em apartado a impugnação e em seguida ouvirá a parte contrária, que, num prazo de 24 (vinte a quatro) horas, oferecerá resposta.", "C) a arguição de falsidade, feita por procurador, não exige poderes especiais.", "D) o juiz não poderá, de ofício, proceder à verificação da falsidade."]'::jsonb, 'A', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Em relação às exceções previstas na legislação processual penal, assinale a alternativa correta.', '["A) A arguição de suspeição sempre precederá a qualquer outra.", "B) Se for arguida a suspeição do órgão do Ministério Público, o juiz, depois de ouvi-lo, decidirá, sem recurso, podendo antes admitir a produção de provas no prazo de 10 (dez) dias.", "C) Poderá se opor suspeição às autoridades policiais nos atos do inquérito.", "D) As exceções serão processadas em autos apartados e não suspenderão, em regra, o andamento da ação penal."]'::jsonb, 'D', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Acerca das disposições contidas na Lei Processual sobre o Inquérito Policial, assinale a alternativa correta.', '["A) Nos crimes de ação privada, a autoridade policial poderá proceder a inquérito a requerimento de qualquer pessoa do povo que tiver conhecimento da existência de infração penal.", "B) Do despacho que indeferir o requerimento de abertura de inquérito caberá recurso para o tribunal competente.", "C) Para verificar a possibilidade de haver a infração sido praticada de determinado modo, a autoridade policial poderá proceder à reprodução simulada dos fatos, desde que esta não contrarie a moralidade ou a ordem pública.", "D) A autoridade policial poderá mandar arquivar autos de inquérito."]'::jsonb, 'C', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'João da Silva ajuizou reclamação trabalhista em face da empresa Alfa Empreendimentos Ltda., alegando ter sido dispensado sem justa causa. Postulou a condenação da reclamada no pagamento de aviso prévio, décimo terceiro salário, férias proporcionais acrescidas do terço constitucional e indenização compensatória de 40% (quarenta por cento) sobre os depósitos do FGTS, bem como na obrigação de fornecimento das guias para levantamento dos depósitos do FGTS e obtenção do benefício do seguro-desemprego. Na peça de defesa, a empresa afirma que o reclamante foi dispensado motivadamente, por desídia no desempenho de suas funções (artigo 482, alínea “e”, da CLT), e que, por essa razão, não efetuou o pagamento das verbas postuladas e não forneceu as guias para a movimentação dos depósitos do FGTS e percepção do seguro-desemprego. Considerando que, após a instrução processual, o juiz se convenceu da configuração de culpa recíproca, assinale a alternativa correta.', '["A) A culpa recíproca é modalidade de resilição unilateral do contrato de trabalho.", "B) O reclamante tem direito a 50% do valor do aviso prévio, do décimo terceiro salário e das férias proporcionais.", "C) O reclamante não poderá movimentar a conta vinculada do FGTS.", "D) O reclamante não tem direito ao pagamento de indenização compensatória sobre os depósitos do FGTS."]'::jsonb, 'B', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Assinale a alternativa correta em relação ao Fundo de Garantia do Tempo de Serviço – FGTS.', '["A) Durante a prestação do serviço militar obrigatório pelo empregado, ainda que se trate de período de suspensão do contrato de trabalho, é devido o depósito em sua conta vinculada do FGTS.", "B) Na hipótese de falecimento do empregado, o saldo de sua conta vinculada do FGTS deve ser pago ao representante legal do espólio, a fim de que proceda à partilha entre todos os sucessores do trabalhador falecido.", "C) Não é devido o pagamento de indenização compensatória sobre os depósitos do FGTS quando o contrato de trabalho se extingue por força maior reconhecida pela Justiça do Trabalho.", "D) A prescrição da pretensão relativa às parcelas remuneratórias não alcança o respectivo recolhimento da contribuição para o FGTS, posto ser trintenária a prescrição para a cobrança deste último."]'::jsonb, 'A', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'José Antônio de Souza, integrante da categoria profissional dos eletricitários, é empregado de uma empresa do setor elétrico, expondo-se, de forma intermitente, a condições de risco acentuado.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Paulo, empregado da empresa Alegria Ltda., trabalha para a empresa Boa Sorte Ltda., em decorrência de contrato de prestação de serviços celebrado entre as respectivas empresas. As atribuições por ele exercidas inserem-se na atividade-meio da tomadora, a qual efetua o controle de sua jornada de trabalho e dirige a prestação pessoal dos serviços, emitindo ordens diretas ao trabalhador no desempenho de suas tarefas.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Com relação ao contrato de aprendizagem, assinale a alternativa correta.', '["A) É um contrato especial de trabalho que pode ser ajustado de forma expressa ou tácita.", "B) É um contrato por prazo determinado cuja duração jamais poderá ser superior a dois anos.", "C) Salvo condição mais favorável, ao menor aprendiz deve ser assegurado o salário mínimo hora.", "D) A duração do trabalho do aprendiz não pode exceder de quatro horas diárias, sendo vedada a prorrogação e a compensação de jornada."]'::jsonb, 'C', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Foi celebrada convenção coletiva que fixa jornada em sete horas diárias. Posteriormente, na mesma vigência dessa convenção, foi celebrado acordo coletivo prevendo redução da referida jornada em 30 minutos. Assim, os empregados das empresas que subscrevem o acordo coletivo e a convenção coletiva deverão trabalhar, por dia,', '["A) 8 horas, pois a CRFB prevê jornada de 8 horas por dia e 44 horas semanais, não podendo ser derrogada por norma hierarquicamente inferior.", "B) 7 horas e 30 minutos, porque o acordo coletivo, por ser mais específico, prevalece sobre a convenção coletiva, sendo aplicada a redução de 30 minutos sobre a jornada de 8 horas por dia prevista na CRFB.", "C) 7 horas, pois as condições estabelecidas na convenção coletiva, por serem mais abrangentes, prevalecem sobre as estipuladas no acordo coletivo.", "D) 6 horas e 30 minutos, pela aplicação do princípio da prevalência da norma mais favorável ao trabalhador."]'::jsonb, 'D', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A respeito do recurso de revista, é correto afirmar que', '["A) é cabível para corrigir injustiças de decisões em recurso ordinário, havendo apreciação das provas produzidas nos autos do processo.", "B) é cabível nas causas sujeitas ao procedimento sumaríssimo, somente por contrariedade à súmula de jurisprudência uniforme do Tribunal Superior do Trabalho e violação direta à Constituição da República.", "C) é cabível em sede de execução, de decisão em embargos à execução, nas mesmas hipóteses de cabimento das decisões decorrentes de recurso ordinário.", "D) não é cabível para reforma de decisão visando à uniformização de jurisprudência e restabelecimento da lei federal violada."]'::jsonb, 'B', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Quanto ao cabimento do mandado de segurança na Justiça do Trabalho, assinale a alternativa correta.', '["A) O mandado de segurança impetrado contra decisão liminar que concedeu a tutela antecipada perde o objeto quando da superveniência de sentença nos autos originários.", "B) É permitido o exercício do jus postulandi das partes quando da impetração do mandado de segurança na Justiça do Trabalho.", "C) Tratando-se de execução provisória, não fere direito líquido e certo do impetrante a determinação de penhora em dinheiro, ainda que nomeados outros bens à penhora, uma vez que obedece à gradação da lei processual.", "D) Cabe a impetração de mandado de segurança da decisão que indefere liminar ou homologação de acordo."]'::jsonb, 'A', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Assinale a alternativa correta no que diz respeito à execução trabalhista.', '["A) As partes devem ser previamente intimadas para a apresentação do cálculo de liquidação, exceto da contribuição previdenciária incidente, que ficará a cargo da União.", "B) Tratando-se de prestações sucessivas, por tempo indeterminado, a execução compreenderá inicialmente as prestações devidas até a data do ingresso na execução.", "C) Na execução por carta precatória, os embargos de terceiro serão oferecidos no juízo deprecante ou no juízo deprecado, mas a competência para julgá-los será sempre do juízo deprecante.", "D) Em se tratando de execução provisória, não fere direito líquido e certo do impetrante a determinação de penhora em dinheiro, quando nomeados outros bens à penhora, uma vez que obedece à gradação prevista em lei."]'::jsonb, 'B', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Em audiência de conciliação, instrução e julgamento, o reclamado não respondeu ao pregão, mas compareceu o seu advogado, munido de procuração e dos atos constitutivos da empresa. Dada a palavra ao reclamante, seu advogado requereu que a empresa fosse considerada revel e confessa, pelo que o juiz indeferiu a juntada da defesa escrita que o advogado da parte reclamada pretendia apresentar.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Lavrado auto de infração contra uma empresa por alegada violação às normas da CLT, o valor da multa importa em R$ 5.000,00. Pretendendo recorrer administrativamente da multa, a empresa', '["A) deverá recolher o valor da multa, que ficará retida até o julgamento do recurso administrativo.", "B) não precisará recolher qualquer multa para ter apreciado o seu recurso administrativo.", "C) para ser isenta do depósito da multa, deverá valer-se de ação própria requerendo judicialmente a isenção até o julgamento do recurso administrativo.", "D) não precisará depositar a multa, pois isso somente será obrigatório se desejar ajuizar ação anulatória perante a Justiça do Trabalho."]'::jsonb, 'B', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'Alcides, advogado de longa data, resolve realizar concurso para o Ministério Público, vindo a ser aprovado em primeiro lugar. Após os trâmites legais, é designada data para a sua posse, circunstância que acarreta seu requerimento para suspender sua inscrição nos quadros da OAB, o que vem a ser indeferido. No caso em comento, em relação a Alcides, configura-se situação de', '["A) cancelamento da inscrição por assunção de cargo incompatível.", "B) suspensão da inscrição até a aposentadoria do membro do Ministério Público.", "C) suspeição enquanto permanecer no cargo.", "D) incompatibilidade, podendo atuar, como advogado, em determinadas situações."]'::jsonb, 'A', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'Na Secretaria Municipal de Fazenda, tramita procedimento administrativo relacionado à imposição do IPTU em determinada área urbana. O proprietário do imóvel contrata o advogado Juliano para solucionar a questão. Portando mandato extrajudicial, o advogado dirige-se ao local e, em face dos seus conhecimentos pessoais, obtém o ingresso no recinto da secretaria e recebe as informações pertinentes, apresentando, por petição, os esclarecimentos necessários.  Em um dos dias em que atuava profissionalmente, viu-se interpelado por um dos chefes de seção, que questionou sua permanência no local, proibida por atos regulamentares.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'A empresa Frios e Gelados S.A. promove ação de responsabilidade civil em face da empresa Calor e Chaud Ltda.  No curso do processo, surge decisão judicial, atacada por recurso apresentado pelo representante judicial da empresa autora, o advogado Lúcio. Tal recurso não tem previsão legal de sustentação oral. Apesar disso, o advogado comparece à sessão de julgamento e requer ao tribunal o tempo necessário para a sustentação referida.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'Manoel, empresário, promove ação de separação judicial litigiosa em face de Maria, sua esposa, alegando graves violações aos deveres do casamento, entre as quais abandono material e moral das duas filhas do casal. Anexa documento comprovando que sua esposa deixara as menores em casa para comparecer a festas em locais distantes, o que lhes causou riscos à saúde física e mental. Apesar de as normas sobre o tema determinarem o sigilo, o processo tramita como se fosse público. O advogado do autor comunica o fato ao juiz que preside o processo e ao escrivão que chefia o cartório judicial. Baldados foram os seus esforços.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'A Administração Pública, por meio de determinado órgão, promove processo administrativo de natureza disciplinar em face do servidor público Francisco. O servidor contrata o advogado Sócrates para defendê-lo. Munido do instrumento de mandato, Sócrates requer vista dos autos do processo administrativo e posteriores intimações. O requerimento foi indeferido pela desnecessidade de advogado atuar no referido processo.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'José foi condenado criminalmente, com sentença transitada em julgado, e, paralelamente, punido também em processo disciplinar perante a OAB em função dos mesmos atos que resultaram naquela condenação criminal.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'Conceição promove ação possessória em face de vários réus que ocuparam imóvel sem construção, de sua propriedade, em área urbana. Houve a designação de audiência de conciliação, com a presença dos réus e dos seus advogados. Na audiência, visando organizar o ato, o magistrado proibiu que os advogados se mantivessem de pé, bem como saíssem do local durante a sua realização.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'No julgamento da ação envolvendo Manoel e Joaquim, o relator do processo assacou diversas acusações contra os representantes judiciais das partes, inclusive relacionadas à litigância de má-fé. Os advogados requereram a palavra, que foi indeferida, sendo retirados do recinto por servidores do Tribunal. Requereram, então, as medidas próprias à OAB.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'Ademir, formado em Jornalismo e Direito e exercendo ambas as profissões, publica, em seu espaço jornalístico, alegações forenses por ele apresentadas em juízo. Instado por outros profissionais do Direito a também apresentar os trabalhos dos colegas, Ademir alega que o espaço é exclusivamente dedicado à divulgação dos seus próprios trabalhos forenses.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'O advogado Antônio é convocado para prestar depoimento como testemunha em ação em que um dos seus clientes é parte. Inquirido pelo magistrado, passa a tecer considerações sobre fatos apresentados pelo seu cliente durante as consultas profissionais, mesmo sobre estratégias que havia sugerido para a defesa do seu cliente. Não omitiu quaisquer informações. Posteriormente à audiência, foi notificado da abertura de processo disciplinar pelo depoimento prestado. Em relação ao caso acima, com base nas normas estatutárias, é correto afirmar que', '["A) no caso em tela, houve justa causa, capaz de permitir a revelação de dados sigilosos.", "B) inquirido pelo magistrado, o advogado não pode se escusar de depor e prestar informações.", "C) a quebra do sigilo profissional, ainda que judicialmente, como no caso, é infração disciplinar.", "D) o sigilo profissional é uma faculdade do advogado."]'::jsonb, 'C', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'Tício é advogado regularmente inscrito nos quadros da OAB e conhecido pela energia e vivacidade com que defende a pretensão dos seus clientes. Atuando em defesa de um dos seus clientes, exalta-se em audiência, mas mantém, apesar disso, a cortesia com o magistrado presidente do ato e com o advogado da parte contrária. Mesmo assim, sofreu representação perante o órgão disciplinar da OAB. Em relação a tais fatos, é correto afirmar que', '["A) a atuação de Tício desborda os limites normais do exercício da advocacia.", "B) inexistindo atividade injuriosa, os atos do advogado são imunes ao controle disciplinar.", "C) a defesa do cliente deve ser pautada pelo dirigente da audiência, o magistrado.", "D) no processo judicial, os atos do advogado constituem múnus privado."]'::jsonb, 'B', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'Crésio é procurado por cliente que já possui advogado constituído nos autos. Prontamente recusa a atuação até que seu cliente apresente a quitação dos honorários acordados e proceda à revogação dos poderes que foram conferidos para o exercício do mandato. Após cumpridas essas formalidades, comprovadas documentalmente, Crésio apresenta sua procuração nos autos e requer o prosseguimento do processo. À luz das normas aplicáveis, é correto afirmar que', '["A) a revogação do mandato exime o cliente do pagamento de honorários acordados.", "B) permite-se o ingresso do advogado no processo mesmo que atuando outro, sem sua ciência.", "C) o advogado deve, antes de assumir mandato, procurar a ciência e autorização do antecessor.", "D) a verba de sucumbência deixa de ser devida após a revogação do mandato pelo cliente."]'::jsonb, 'C', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A respeito da internacionalização dos direitos humanos, assinale a alternativa correta.', '["A) Já antes do fim da II Guerra Mundial ocorreu a internacionalização dos direitos humanos, com a limitação dos poderes do Estado a fim de garantir o respeito integral aos direitos fundamentais da pessoa humana.", "B) A limitação do poder, quando previsto na Constituição, garante por si só o respeito aos direitos humanos.", "C) A criação de normas de proteção internacional no âmbito dos direitos humanos possibilita a responsabilização do Estado quando as normas nacionais forem omissas.", "D) A internacionalização dos direitos humanos impõe que o Estado, e não o indivíduo, seja sujeito de direitos internacional."]'::jsonb, 'C', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'As Constituições brasileiras se mostraram com avanços e retrocessos em relação aos direitos humanos. A esse respeito assinale a alternativa correta.', '["A) A Constituição de 1946 apresentou diversos retrocessos em relação aos direitos humanos, principalmente no tocante aos direitos sociais.", "B) A Constituição de 1967 consolidou arbitrariedades decretadas nos Atos Institucionais, caracterizando diversos retrocessos em relação aos direitos humanos.", "C) A Constituição de 1934 se revelou retrógrada ao ignorar normas de proteção social ao trabalhador.", "D) A Constituição de 1969, mesmo incorporando as medidas dos Atos Institucionais, se revelou mais atenta aos direitos humanos que a Constituição de 1967."]'::jsonb, 'B', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'No âmbito dos direitos humanos, a respeito do Incidente de Deslocamento de Competência, instituído pela Emenda Constitucional 45, assinale a alternativa correta.', '["A) Para assegurar o cumprimento de obrigações decorrentes de tratados internacionais de direitos humanos de que o Brasil seja parte, o Procurador-Geral da República pode suscitar, perante o Superior Tribunal de Justiça, incidente de deslocamento de competência para a Justiça Federal, nas hipóteses de graves violações aos direitos humanos.", "B) O incidente de deslocamento de competência, embora garanta o cumprimento de obrigações do Estado brasileiro em relação aos tratados internacionais de direitos humanos, não está relacionado com a razoável duração do processo para a consecução da finalidade de efetiva proteção dos direitos humanos.", "C) Pelo incidente de deslocamento de competência, a Justiça Federal só julgaria os casos relativos aos direitos humanos após o Brasil ser responsabilizado internacionalmente.", "D) O incidente de deslocamento de competência se efetiva contrariamente ao princípio do federalismo cooperativo por não obedecer à hierarquia de competência para julgamento dos crimes comuns, mesmo no âmbito de ferimento aos direitos humanos."]'::jsonb, 'A', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A embaixada de um estado estrangeiro localizada no Brasil contratou um empregado brasileiro para os serviços gerais. No final do ano, não pagou o 13º salário, por entender que, em seu país, este não era devido. O empregado, insatisfeito, recorreu à Justiça do Trabalho. A ação foi julgada procedente, mas a embaixada não cumpriu a sentença. Por isso, o reclamante solicitou a penhora de um carro da embaixada. Com base no relatado acima, o Juiz do Trabalho decidiu', '["A) deferir a penhora, pois a Constituição atribui competência à justiça brasileira para ações de execução contra Estados estrangeiros.", "B) indeferir a penhora, pois o Estado estrangeiro, no que diz respeito à execução, possui imunidade, e seus bens são invioláveis.", "C) extinguir o feito sem julgamento do mérito por entender que o Estado estrangeiro tem imunidade de jurisdição.", "D) deferir a penhora, pois o Estado estrangeiro não goza de nenhuma imunidade quando se tratar de ações trabalhistas."]'::jsonb, 'B', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Em janeiro de 2003, Martin e Clarisse Green, cidadãos britânicos domiciliados no Rio de Janeiro, casam-se no Consulado-Geral britânico, localizado na Praia do Flamengo. Em meados de 2010, decidem se divorciar. Na ausência de um pacto antenupcial, Clarisse requer, em petição à Vara de Família do Rio de Janeiro, metade dos bens adquiridos pelo casal desde a celebração do matrimônio, alegando que o regime legal vigente no Brasil é o da comunhão parcial de bens. Martin, no entanto, contesta a pretensão de Clarisse, argumentando que o casamento foi realizado no consulado britânico e que, portanto, deve ser aplicado o regime legal de bens vigente no Reino Unido, que lhe é mais favorável. Com base no caso hipotético acima e nos termos da Lei de Introdução às Normas do Direito Brasileiro, assinale a alternativa correta.', '["A) O juiz brasileiro não poderá conhecer e julgar a lide, pois o casamento não foi realizado perante a autoridade competente.", "B) Clarisse tem razão em sua demanda, pois o regime de bens é regido pela lex domicilli dos nubentes e, ao tempo do casamento, ambos eram domiciliados no Brasil.", "C) Martin tem razão em sua contestação, pois o regime de bens se rege pela lei do local da celebração (lex loci celebrationis), e o casamento foi celebrado no consulado britânico.", "D) O regime de bens obedecerá à lex domicilli dos cônjuges quanto aos bens móveis e à lex rei sitae (ou seja, a lei do lugar onde estão) quanto aos bens imóveis, se houver."]'::jsonb, 'B', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Se Governador de Estado desejar se insurgir contra súmula vinculante que, a seu juízo, foi formulada com enunciado normativo que extrapolou os limites dos precedentes que a originaram, poderá, dentro dos instrumentos processuais constitucionais existentes,', '["A) ajuizar ADI contra a súmula vinculante.", "B) ajuizar ADPF contra a súmula vinculante.", "C) interpor reclamação contra a súmula vinculante.", "D) requerer o cancelamento da súmula vinculante."]'::jsonb, 'D', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Os Estados são autônomos e compõem a Federação com a União, os Municípios e o Distrito Federal. À luz das normas constitucionais, quanto aos Estados, é correto afirmar que', '["A) podem incorporar-se entre si mediante aprovação em referendo.", "B) a subdivisão não pode gerar a formação de novos territórios.", "C) o desmembramento deve ser precedido de autorização por lei ordinária.", "D) se requer lei complementar federal aprovando a criação de novos entes estaduais."]'::jsonb, 'D', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'No processo de impedimento do Presidente da República, ocorre a necessidade de preenchimento de alguns requisitos. Com base nas normas constitucionais, é correto afirmar que', '["A) a Câmara autoriza a instauração do processo pelo voto da maioria absoluta dos seus membros.", "B) o julgamento ocorre pelo Senado Federal, cuja decisão deverá ocorrer pela maioria simples.", "C) condenado o Presidente, cumprirá sua pena privativa de liberdade em regime semiaberto.", "D) no julgamento ocorrido no Senado, funcionará como Presidente o do Supremo Tribunal Federal."]'::jsonb, 'D', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Lei estadual que regulamenta o serviço de mototáxi é', '["A) constitucional porque se trata de competência legislativa reservada aos Estados.", "B) constitucional porque se trata de competência legislativa remanescente dos Estados.", "C) inconstitucional porque se trata de competência legislativa dos Municípios.", "D) inconstitucional porque se trata de competência legislativa privativa da União."]'::jsonb, 'D', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'No que tange ao direito de nacionalidade, assinale a alternativa correta.', '["A) O brasileiro nato não pode perder a nacionalidade.", "B) O filho de pais alemães que estão no Brasil a serviço de empresa privada alemã será brasileiro nato caso venha a nascer no Brasil.", "C) O brasileiro naturalizado pode ser extraditado pela prática de crime comum após a naturalização.", "D) O brasileiro nato somente poderá ser extraditado no caso de envolvimento com o tráfico de entorpecentes."]'::jsonb, 'B', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A iniciativa popular é uma das formas de exercício da soberania previstas na Constituição da República. O projeto de lei resultante de iniciativa popular deve', '["A) ser dirigido à Mesa do Congresso Nacional.", "B) ser subscrito por, no mínimo, 2% do eleitorado nacional.", "C) ser subscrito por eleitores de cinco Estados da Federação.", "D) dispor sobre matéria de lei ordinária."]'::jsonb, 'C', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'O habeas data não pode ser impetrado em favor de terceiro PORQUE visa tutelar direito à informação relativa à pessoa do impetrante.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Com nítida inspiração na doutrina da proteção integral, o ECA garantiu à criança e ao adolescente o mais amplo acesso à Justiça, como forma de viabilizar a efetivação de seus direitos, consagrou-lhes o acesso a todos os órgãos do Poder Judiciário, assim como lhes assegurou o acesso a órgãos que exercem funções essenciais à Justiça, como o Ministério Público e a Defensoria. Tendo em conta tal ampla proteção, assinale a alternativa correta.', '["A) As custas e emolumentos nas ações de destituição do poder familiar, perda ou modificação da tutela deverão ser custeadas pela parte sucumbente ao final do processo.", "B) Na hipótese de colisão de interesses entre a criança ou adolescente e seus pais ou responsável, a autoridade judiciária lhes dará curador especial, o mesmo ocorrendo nas hipóteses de carência de representação ou assistência legal, ainda que eventual.", "C) Em obediência ao princípio da publicidade, é permitida a divulgação de atos judiciais e administrativos que digam respeito à autoria de ato infracional praticado por adolescente, podendo ser expedida certidão ou extraída cópia dos autos, independentemente da demonstração do interesse e justificativa acerca da finalidade. Tais fatos, no entanto, se noticiados pela imprensa escrita ou falada, devem conter apenas as iniciais do nome e sobrenome do menor, sendo vedadas as demais formas expositivas, como fotografia, referência ao nome, apelido, etc.", "D) A assistência judiciária gratuita será prestada aos que dela necessitarem por defensor público, sendo admitida a nomeação pelo juiz de advogado se o adolescente não tiver defensor, não podendo, posteriormente, o adolescente constituir outro de sua preferência."]'::jsonb, 'B', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Fernando e Eulália decidiram adotar uma menina. Iniciaram o processo de adoção em maio de 2010. Com o estágio de convivência em curso, o casal se divorciou. Diante do fim do casamento dos pretendentes à adoção, é correto afirmar que', '["A) a adoção deverá ser suspensa, e outro casal adotará a menor, segundo o princípio do melhor interesse do menor, pois a adoção é medida geradora do vínculo familiar.", "B) a adoção poderá prosseguir, contanto que o casal opte pela guarda compartilhada no acordo de divórcio, mesmo que o estágio de convivência não tenha sido iniciado na constância do período de convivência.", "C) a adoção será deferida, contanto que o casal acorde sobre a guarda, regime de visitas e desde que o estágio de convivência tenha sido iniciado na constância do período de convivência e que seja comprovada a existência de vínculo de afinidade e afetividade com aquele que não seja o detentor da guarda que justifique a excepcionalidade da concessão.", "D) a lei não prevê tal hipótese, pois está em desacordo com os ditames constitucionais da paternidade responsável."]'::jsonb, 'C', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'No que tange à chamada ação de improbidade administrativa, assinale a definição correta segundo a doutrina do Direito Administrativo.', '["A) Trata-se de ação de natureza civil e penal, uma vez que a Lei 8.429/92 prevê sanções de ambas as naturezas.", "B) Trata-se de ação meramente administrativa, uma vez que a Lei 8.429/92 prevê apenas sanções de caráter administrativo.", "C) Trata-se de ação civil, muito embora as sanções previstas pela Lei 8.429/92 ultrapassem o âmbito da simples ação de ressarcimento e importem em penalidades de natureza penal e administrativa.", "D) Não se trata de uma ação judicial e sim de uma ação administrativa, com a previsão legal (Lei 8.429/92) de sanções penais e administrativas."]'::jsonb, 'C', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A estruturação da Administração traz a presença, necessária, de centros de competências denominados Órgãos Públicos ou, simplesmente, Órgãos. Quanto a estes, é correto afirmar que', '["A) possuem personalidade jurídica própria, respondendo diretamente por seus atos.", "B) suas atuações são imputadas às pessoas jurídicas a que pertencem.", "C) não possuem cargos, apenas funções, e estas são criadas por atos normativos do ocupante do respectivo órgão.", "D) não possuem cargos nem funções."]'::jsonb, 'B', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A revogação representa uma das formas de extinção de um ato administrativo. Quanto a esse instituto, é correto afirmar que', '["A) pode se dar tanto em relação a atos viciados de ilegalidade ou não, desde que praticados dentro de uma competência discricionária.", "B) produz efeitos retroativos, retirando o ato do mundo, de forma a nunca ter existido.", "C) apenas pode se dar em relação aos atos válidos, praticados dentro de uma competência discricionária, produzindo efeitos ex nunc.", "D) pode se dar em relação aos atos vinculados ou discricionários, produzindo ora efeito ex tunc, ora efeito ex nunc."]'::jsonb, 'C', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Tendo o agente público atuado nesta qualidade e dado causa a dano a terceiro, por dolo ou culpa, vindo a administração a ser condenada, terá esta o direito de regresso. A respeito da ação regressiva, é correto afirmar que', '["A) em regra deve ser exercida, sob pena de afronta ao princípio da indisponibilidade.", "B) o prazo prescricional tem início a contar do fato que gerou a ação indenizatória contra a Administração.", "C) a prescrição será decenal, com base na regra geral da legislação civil.", "D) o prazo prescricional será o mesmo constante da esfera penal para o tipo criminal correspondente."]'::jsonb, 'A', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'O art. 37, II, da Constituição da República Federativa do Brasil de 1988, condiciona a investidura em cargo ou emprego público à prévia aprovação em concurso público de provas ou de provas e títulos, ressalvadas as nomeações para os cargos em comissão.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'De acordo com o critério da titularidade, consideram-se públicos os bens do domínio nacional pertencentes', '["A) às entidades da Administração Pública Direta e Indireta.", "B) às entidades da Administração Pública Direta, às autarquias e às empresas públicas.", "C) às pessoas jurídicas de direito público interno e às pessoas jurídicas de direito privado prestadoras de serviços públicos.", "D) às pessoas jurídicas de direito público interno."]'::jsonb, 'D', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Em relação à união estável, assinale a alternativa correta.', '["A) Para que fique caracterizada a união estável, é necessário, entre outros requisitos, tempo de convivência mínima de cinco anos, desde que durante esse período a convivência tenha sido pública e duradoura.", "B) Quem estiver separado apenas de fato não pode constituir união estável, sendo necessária, antes, a dissolução do anterior vínculo conjugal; nesse caso, haverá simples concubinato.", "C) Não há presunção legal de paternidade no caso de filho nascido na constância da união estável.", "D) O contrato de união estável é solene, rigorosamente formal e sempre público."]'::jsonb, 'C', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'João trafegava com seu veículo com velocidade incompatível para o local e avançou o sinal vermelho. José, que atravessava normalmente na faixa de pedestre, foi atropelado por João, sofrendo vários ferimentos. Para se recuperar, José, trabalhador autônomo, teve que ficar internado por 10 dias, sem possibilidade de trabalhar, além de ter ficado com várias cicatrizes no corpo. Em virtude do ocorrido, José ajuizou ação, pleiteando danos morais, estéticos e materiais. Com base na situação acima, assinale a alternativa correta.', '["A) José não poderá receber a indenização na forma pleiteada, já que o dano moral e o dano estético são inacumuláveis. Assim, terá direito apenas ao dano moral, em razão do sofrimento e das cicatrizes, e ao dano material, em razão do tempo que ficou sem trabalhar.", "B) José terá direito apenas ao dano moral, já que o tempo que ficou sem trabalhar é considerado lucros cessantes, os quais não foram expressamente requeridos, e não podem ser concedidos. Quanto ao dano estético, esse é inacumulável com o dano moral, já estando incluído neste.", "C) José terá direito a receber a indenização na forma pleiteada: o dano moral em razão das lesões e do sofrimento por ele sentido, o dano material em virtude do tempo que ficou sem trabalhar e o dano estético em razão das cicatrizes com que ficou.", "D) José terá direito apenas ao dano moral, em razão do sofrimento, e ao dano estético, em razão das cicatrizes. Quanto ao tempo em que ficou sem trabalhar, isso se traduz em lucros cessantes, que não foram pedidos, não podendo ser concedidos."]'::jsonb, 'C', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Heitor, solteiro e pai de dois filhos também solteiros (Roberto, com trinta anos de idade, e Leonardo, com vinte e oito anos de idade), vem a falecer, sem deixar testamento. Roberto, não tendo interesse em receber a herança deixada pelo pai, a ela renuncia formalmente por meio de instrumento público. Leonardo, por sua vez, manifesta inequivocamente o seu interesse em receber a herança que lhe caiba. Sabendo-se que Margarida, mãe de Heitor, ainda é viva e que Roberto possui um filho, João, de dois anos de idade, assinale a alternativa correta.', '["A) Roberto não pode renunciar à herança, pois acarretará prejuízos a seu filho, João, menor de idade.", "B) Roberto pode renunciar à herança, o que ocasionará a transferência de seu quinhão para João, seu filho.", "C) Roberto pode renunciar à herança, e, com isso, o seu quinhão será acrescido à parte da herança a ser recebida por Leonardo, seu irmão.", "D) Roberto pode renunciar à herança, ocasionando a transferência de seu quinhão para Margarida, sua avó, desde que ela aceite receber a herança."]'::jsonb, 'C', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Durante assembleia realizada em condomínio edilício residencial, que conta com um apartamento por andar, Giovana, nova proprietária do apartamento situado no andar térreo, solicitou explicações sobre a cobrança condominial, por ter verificado que o valor dela cobrado era superior àquele exigido dos demais condôminos. O síndico prontamente esclareceu que a cobrança a ela dirigida é realmente superior à cobrança das demais unidades, tendo em vista que o apartamento de Giovana tem acesso exclusivo, por meio de uma porta situada em sua área de serviço, a um pequeno pátio localizado nos fundos do condomínio, conforme consta nas configurações originais do edifício devidamente registradas. Desse modo, segundo afirmado pelo síndico, podendo Giovana usar o pátio com exclusividade, apesar de constituir área comum do condomínio, caberia a ela arcar com as respectivas despesas de manutenção.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'O decurso do tempo exerce efeitos sobre as relações jurídicas. Com o propósito de suprir uma deficiência apontada pela doutrina em relação ao Código velho, o novo Código Civil, a exemplo do Código Civil italiano e português, define o que é prescrição e institui disciplina específica para a decadência.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Em instrumento particular, subscrito por duas testemunhas, um menor de 16 anos, sem bens, não estabelecido com economia própria nem exercendo atividade laborativa e sendo apenas estudante do curso secundário, tomou por empréstimo a uma vizinha, sua amiga, a quantia de R$ 5.000,00 (cinco mil reais) para participar de uma campanha de doação de fundos para seu time de futebol, autorizando que a referida mutuante entregasse, em nome do mutuário, a referida importância diretamente ao clube esportivo, o que foi feito. Não foi fixado prazo para pagamento do mútuo, nem houve previsão de juros, exigindo, entretanto, a credora, a fiança de dois amigos do mutuário, solteiros, maiores e capazes. Recusando-se a pagar o empréstimo, foram procurados o pai e a mãe do mutuário, os quais se negaram a ratificar o empréstimo e se negaram a honrá-lo, sob o argumento de que não o haviam autorizado. Em face disso, assinale a alternativa correta.', '["A) Esse mútuo não pode ser reavido nem do mutuário, nem de seus fiadores.", "B) Presumem-se devidos os juros pelo mutuário e por seus fiadores.", "C) Esse mútuo é uma obrigação que apenas vincula o menor e, assim, quando vencido e não restituído, poderá ser cobrado apenas do mutuário, não sendo exigível dos fiadores, perante os quais é absolutamente ineficaz.", "D) Não é válida, no caso, a negativa dos pais em honrar o empréstimo, que poderá ser cobrado deles, mas sem juros."]'::jsonb, 'A', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A dação em pagamento é', '["A) modalidade de obrigação facultativa, na qual o credor consente em receber objeto diverso ao da prestação originariamente pactuada.", "B) modalidade de adimplemento direto, na qual o credor consente em receber objeto diverso ao da prestação originariamente pactuada.", "C) causa extintiva da obrigação, na qual o credor consente em receber objeto diverso ao da prestação originariamente pactuada.", "D) modalidade de obrigação alternativa, na qual o credor consente em receber objeto diverso ao da prestação originariamente pactuada."]'::jsonb, 'C', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Numa ação de reintegração de posse em que o esbulho ocorreu há menos de 1 ano e 1 dia, ao examinar o pedido de liminar constante da petição inicial, o juiz', '["A) deve sempre realizar a inspeção judicial no local, sendo tal diligência requisito para a concessão da liminar.", "B) deve deferir de plano, sem ouvir o réu, se a petição inicial estiver devidamente instruída e sendo a ação entre particulares.", "C) deve sempre designar audiência prévia ou de justificação, citando o réu, para, então, avaliar o pedido liminar.", "D) pode deferir a liminar de plano, sem ouvir o réu, desde que haja parecer favorável do Ministério Público."]'::jsonb, 'B', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Considerando a ação de execução de título extrajudicial, é correto afirmar que', '["A) caso a petição inicial se ache desacompanhada do título executivo, deverá ser indeferida de plano, não se admitindo prazo para correção, dada a natureza sumária das ações executivas.", "B) caberá ao devedor indicar a espécie de execução que prefere, quando de mais de um modo puder ser efetuada.", "C) deverá ser extinta se o título não corresponder a obrigação certa, líquida e exigível.", "D) cabe ao devedor provar que o credor não adimpliu a contraprestação, quando a satisfação da obrigação do executado estiver condicionada à realização daquela."]'::jsonb, 'C', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'O Ministério Público ajuizou ação rescisória a fim de desconstituir sentença transitada em julgado, ao argumento de que teria havido colusão entre ambas as partes do processo originário no intuito de fraudar a lei. Diante disso, requereu o Ministério Público, na petição inicial da ação rescisória, a citação tanto da parte autora quanto da parte ré do processo originário.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Zélia e Joaquim são vizinhos há cerca de sete anos. Determinada parede foi construída por Joaquim, mas, por defeitos na execução da obra, está permitindo a infiltração da água da chuva, gerando danos à parede limítrofe construída por Zélia. Inconformada, Zélia procura você como advogado(a) a fim de ingressar com a medida judicial cabível. Analisando a hipótese e, estando Zélia de acordo com o seu parecer técnico, você afora ação judicial para o desfazimento da construção ou a reparação da obra defeituosa. Nessa hipótese, como será fixado o valor da causa?', '["A) Deverá ser considerado o menor valor, por se tratar de pedido subsidiário.", "B) Será a soma dos valores de todos os pedidos, por se tratar da hipótese de cumulação de pedidos.", "C) Por se tratar de pedidos alternativos, será considerado o de maior valor.", "D) Por se tratar de ação para cumprimento do negócio jurídico, será considerado o valor da soma do principal, da pena e dos juros vencidos."]'::jsonb, 'C', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'No curso dos processos, os juízes são dotados de poderes que lhes permitem conduzir os feitos de maneira adequada, garantindo, ao término do processo, a prestação da tutela jurisdicional de maneira eficaz.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A respeito da liquidação de sentença, assinale a alternativa correta.', '["A) Para que a sentença arbitral seja liquidada, será necessária a instauração de processo judicial, com a citação da parte sucumbente.", "B) É cabível a liquidação de sentença no procedimento dos Juizados Especiais Cíveis Estaduais.", "C) É incabível a liquidação de sentença antes do trânsito em julgado da sentença liquidanda.", "D) A liquidação por artigos corresponde à espécie de liquidação de sentença em que não poderá ser produzida prova pericial para a apuração do valor da condenação."]'::jsonb, 'A', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Quando a contratação ocorre por site da internet, o consumidor pode desistir da compra?', '["A) Sim. Quando a compra é feita pela internet, o consumidor pode desistir da compra em até 30 dias depois que recebe o produto.", "B) Não. Quando a compra é feita pela internet, o consumidor é obrigado a ficar com o produto, a menos que ele apresente vício. Só nessa hipótese o consumidor pode desistir.", "C) Não. O direito de arrependimento só existe para as compras feitas na própria loja, e não pela internet.", "D) Sim. Quando a compra é feita fora do estabelecimento comercial, o consumidor pode desistir do contrato no prazo de sete dias, mesmo sem apresentar seus motivos para a desistência."]'::jsonb, 'D', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Ao instalar um novo aparelho de televisão no quarto de seu filho, o consumidor verifica que a tecla de volume do controle remoto não está funcionando bem. Em contato com a loja onde adquiriu o produto, é encaminhado à autorizada. O que esse consumidor pode exigir com base na lei, nesse momento, do comerciante?', '["A) A imediata substituição do produto por outro novo.", "B) O dinheiro de volta.", "C) O conserto do produto no prazo máximo de 30 dias.", "D) Um produto idêntico emprestado enquanto durar o conserto."]'::jsonb, 'C', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A respeito da deliberação dos sócios na Sociedade Limitada, é correto afirmar que', '["A) a assembleia somente pode ser convocada pelos administradores eleitos no contrato social.", "B) as formalidades legais de convocação são dispensadas quando todos os sócios se declararem, por escrito, cientes do local, data, hora e ordem do dia.", "C) a deliberação em assembleia será obrigatória se o número dos sócios for superior a cinco.", "D) as deliberações tomadas de conformidade com a lei e o contrato vinculam os sócios ausentes, mas não os dissidentes."]'::jsonb, 'B', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Conforme art. 4º da Lei 6404/76, as companhias podem ser classificadas em abertas ou fechadas, dependendo se seus valores mobiliários podem ou não ser negociados no Mercado de Valores Mobiliários. Em relação aos valores mobiliários das companhias abertas e fechadas, assinale a alternativa correta.', '["A) Valores mobiliários são títulos que concedem a seu titular certos direitos em relação à companhia. São exemplos de valores mobiliários as ações, as debêntures, os bônus de subscrição e o certificado de valores mobiliários.", "B) O Mercado de Valores Mobiliários (MVM) compreende as bolsas de valores, o mercado de balcão e o mercado de balcão organizado. Para a companhia poder negociar no MVM, deverá preencher certos requisitos e obter autorização da Comissão de Valores Mobiliários e da Junta Comercial.", "C) As companhias abertas, caso queiram negociar suas ações, devem sempre fazê-lo por meio do mercado de valores mobiliários, ou seja, suas negociações serão sempre por oferta ao público em geral.", "D) Partes beneficiárias são títulos emitidos tanto pela companhia aberta quanto pela fechada que dão a seu titular direito a percentual no lucro da companhia."]'::jsonb, 'A', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Em relação à incapacidade e proibição para o exercício da empresa, assinale a alternativa correta.', '["A) Caso a pessoa proibida de exercer a atividade de empresário praticar tal atividade, deverá responder pelas obrigações contraídas, podendo até ser declarada falida.", "B) Aquele que tenha impedimento legal para ser empresário está impedido de ser sócio ou acionista de uma sociedade empresária.", "C) Entre as pessoas impedidas de exercer a empresa está o incapaz, que não poderá exercer tal atividade.", "D) Por se tratar de matéria de ordem pública e considerando que a continuação da empresa interessa a toda a sociedade, quer em razão da arrecadação de impostos, quer em razão da geração de empregos, caso a pessoa proibida de exercer a atividade empresarial o faça, poderá requerer a recuperação judicial."]'::jsonb, 'A', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A respeito da sociedade em comum, é correto afirmar que', '["A) os sócios respondem individual e ilimitadamente pelas obrigações sociais.", "B) são regidas pelas disposições das sociedades simples.", "C) na relação com terceiros, os sócios podem comprovar a existência da sociedade de qualquer modo.", "D) os sócios são titulares em comum das dívidas sociais."]'::jsonb, 'D', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A respeito do Administrador Judicial, no âmbito da recuperação judicial, é correto afirmar que', '["A) somente pode ser destituído pelo Juízo da Falência na hipótese de, após intimado, não apresentar, no prazo de 5 (cinco) dias, suas contas ou os relatórios previstos na Lei 11.101/2005.", "B) o Administrador Judicial, pessoa física, pode ser formado em Engenharia.", "C) será escolhido pela Assembleia Geral de Credores.", "D) perceberá remuneração fixada pelo Comitê de Credores."]'::jsonb, 'B', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'No exercício de 1995, um contribuinte deixou de recolher determinado tributo. Na ocasião, a lei impunha a multa moratória de 30% do valor do débito. Em 1997, houve alteração legislativa, que reduziu a multa moratória para 20%.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A respeito do ICMS, é correto afirmar que', '["A) é não cumulativo, significando que, em qualquer hipótese, deverá ser assegurado o crédito para compensação com o montante devido nas operações ou prestações seguintes.", "B) incide sobre prestação de serviços de transporte interestadual e intermunicipal e de comunicação, assim como sobre o valor total da operação, quando as mercadorias forem fornecidas com serviços não compreendidos na competência impositiva municipal.", "C) sendo de competência tributária do Estado-Membro, somente a legislação estadual pode excluir da incidência do imposto, nas exportações para o exterior, serviços e produtos determinados.", "D) tem as suas alíquotas estabelecidas pelo Senado Federal, aplicáveis às operações e prestações internas, interestaduais e de exportação."]'::jsonb, 'B', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A obrigação tributária principal tem por objeto', '["A) a escrituração de livros contábeis.", "B) o pagamento de tributo ou penalidade pecuniária.", "C) a prestação de informações tributárias perante a autoridade fiscal competente.", "D) a inscrição da pessoa jurídica junto ao Cadastro Nacional de Pessoa Jurídica – CNPJ."]'::jsonb, 'B', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Determinada Lei Municipal, publicada em 17/01/2011, fixou o aumento das multas e alíquotas relativo aos fatos jurídicos tributáveis e ilícitos pertinentes ao ISS daquele ente federativo. Considerando que determinado contribuinte tenha sido autuado pela autoridade administrativa local em 23/12/2010, em razão da falta de pagamento do ISS dos meses de abril de 2010 a novembro de 2010, assinale a alternativa correta a respeito de como se procederia a aplicação da legislação tributária para a situação em tela.', '["A) Seriam mantidas as alíquotas e multas nos valores previstos na data do fato gerador.", "B) Seriam aplicadas as alíquotas previstas na lei nova e as multas seriam aplicadas nos valores previstos na data do fato gerador.", "C) Seriam mantidas as alíquotas nos valores previstos na data do fato gerador e as multas seriam aplicadas nos valores previstos de acordo com a nova lei.", "D) Seriam aplicadas as alíquotas e multas nos valores previstos de acordo com a nova lei."]'::jsonb, 'A', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'João adquiriu em maio de 2000 um imóvel em área rural, banhado pelo Rio Formoso. Em 2010, foi citado para responder a uma ação civil pública proposta pelo Município de Belas Veredas, que o responsabiliza civilmente por ter cometido corte raso na mata ciliar da propriedade. João alega que o desmatamento foi cometido pelo antigo proprietário da fazenda, que já praticava o plantio de milho no local. Em razão do exposto, é correto afirmar que', '["A) a responsabilidade por dano ambiental é objetiva, mas, como não há nexo de causalidade entre a ação do novo proprietário e o corte raso na área, verifica-se a excludente de responsabilidade, e João não será obrigado a reparar o dano.", "B) a responsabilidade civil por dano ambiental difuso prescreve em cinco anos por força da Lei 9.873/99. Logo, João não será obrigado a reparar o dano.", "C) João será obrigado a recuperar a área, mas, como não poderá mais utilizá-la para o plantio do milho, terá direito a indenização, a ser paga pelo Poder Público, por força do princípio do protetor-recebedor.", "D) a manutenção de área de mata ciliar é obrigação propter rem; sendo obrigação de conservação, é automaticamente transferida do alienante ao adquirente. Logo, João terá que reparar a área."]'::jsonb, 'D', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A Lei 9.605/98, regulamentada pelo Decreto 6.514/2008, que dispõe sobre sanções penais e administrativas derivadas de condutas e atividades lesivas ao meio ambiente, trouxe novidades nas normas ambientais.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Ao tomar conhecimento de um roubo ocorrido nas adjacências de sua residência, Caio compareceu à delegacia de polícia e noticiou o crime, alegando que vira Tício, seu inimigo capital, praticar o delito, mesmo sabendo que seu desafeto se encontrava na Europa na data do fato. Em decorrência do exposto, foi instaurado inquérito policial para apurar as circunstâncias do ocorrido.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'As regras do concurso formal perfeito (em que se adota o sistema da exasperação da pena) foram adotadas pelo Código Penal com o objetivo de beneficiar o agente que, mediante uma só conduta, praticou dois ou mais crimes. No entanto, quando o sistema da exasperação for prejudicial ao acusado, deverá prevalecer o sistema do cúmulo material (em que a soma das penas será mais vantajosa do que o aumento de uma delas com determinado percentual, ainda que no patamar mínimo).
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Joaquim, conduzindo seu veículo automotor (que se encontrava sem as placas de identificação) em velocidade superior à máxima permitida para a via – 50km/h –, pratica o crime de lesões corporais culposas em virtude da sua não observância ao dever objetivo de cuidado no trânsito. Com base na situação acima e à luz do Código de Trânsito Brasileiro, assinale a alternativa correta.', '["A) Por se tratar a lesão corporal culposa praticada na direção de veículo automotor de uma infração de menor potencial ofensivo, Joaquim responderá pelo seu crime no Juizado Especial Criminal.", "B) Sem prejuízo da pena de detenção correspondente, Joaquim estará sujeito à suspensão ou proibição de se obter a permissão ou a habilitação para dirigir veículo automotor.", "C) Pelo fato de Joaquim praticar o fato na condução de veículo automotor sem placas de identificação, o Juiz poderá, caso entenda necessário, agravar a penalidade do crime.", "D) A pena a que Joaquim estará sujeito não se alterará se a lesão corporal culposa for praticada em faixa de pedestres ou mesmo na calçada."]'::jsonb, 'B', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Acerca da aplicação da lei penal no tempo e no espaço, assinale a alternativa correta.', '["A) Se um funcionário público a serviço do Brasil na Itália praticar, naquele país, crime de corrupção passiva (art. 317 do Código Penal), ficará sujeito à lei penal brasileira em face do princípio da extraterritorialidade.", "B) O ordenamento jurídico-penal brasileiro prevê a combinação de leis sucessivas sempre que a fusão puder beneficiar o réu.", "C) Na ocorrência de sucessão de leis penais no tempo, não será possível a aplicação da lei penal intermediária mesmo se ela configurar a lei mais favorável.", "D) As leis penais temporárias e excepcionais são dotadas de ultra-atividade. Por tal motivo, são aplicáveis a qualquer delito, desde que seus resultados tenham ocorrido durante sua vigência."]'::jsonb, 'A', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Apolo foi ameaçado de morte por Hades, conhecido matador de aluguel. Tendo tido ciência, por fontes seguras, que Hades o mataria naquela noite e, com o intuito de defender-se, Apolo saiu de casa com uma faca no bolso de seu casaco. Naquela noite, ao encontrar Hades em uma rua vazia e escura e, vendo que este colocava a mão no bolso, Apolo precipita-se e, objetivando impedir o ataque que imaginava iminente, esfaqueia Hades, provocando-lhe as lesões corporais que desejava. Todavia, após o ocorrido, o próprio Hades contou a Apolo que não ia matá-lo, pois havia desistido de seu intento e, naquela noite, foi ao seu encontro justamente para dar-lhe a notícia. Nesse sentido, é correto afirmar que', '["A) havia dolo na conduta de Apolo.", "B) mesmo sendo o erro escusável, Apolo não é isento de pena.", "C) Apolo não agiu em legítima defesa putativa.", "D) mesmo sendo o erro inescusável, Apolo responde a título de dolo."]'::jsonb, 'A', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Jefferson, segurança da mais famosa rede de supermercados do Brasil, percebeu que João escondera em suas vestes três sabonetes, de valor aproximado de R$ 12,00 (doze reais). Ao tentar sair do estabelecimento, entretanto, João é preso em flagrante delito pelo segurança, que chama a polícia. A esse respeito, assinale a alternativa correta.', '["A) A conduta de João não constitui crime, uma vez que este agiu em estado de necessidade.", "B) A conduta de João não constitui crime, uma vez que o fato é materialmente atípico.", "C) A conduta de João constitui crime, uma vez que se enquadra no artigo 155 do Código Penal, não estando presente nenhuma das causas de exclusão de ilicitude ou culpabilidade, razão pela qual este deverá ser condenado.", "D) Embora sua conduta constitua crime, João deverá ser absolvido, uma vez que a prisão em flagrante é nula, por ter sido realizada por um segurança particular."]'::jsonb, 'B', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Tendo em vista o enunciado da súmula vinculante n. 14 do Supremo Tribunal Federal, quanto ao sigilo do inquérito policial, é correto afirmar que a autoridade policial poderá negar ao advogado', '["A) a vista dos autos, sempre que entender pertinente.", "B) a vista dos autos, somente quando o suspeito tiver sido indiciado formalmente.", "C) do indiciado que esteja atuando com procuração o acesso aos depoimentos prestados pelas vítimas, se entender pertinente.", "D) o acesso aos elementos de prova que ainda não tenham sido documentados no procedimento investigatório."]'::jsonb, 'D', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Quando se tratar de acusação relativa à prática de infração penal de menor potencial ofensivo, cometida por estudante de direito, a competência jurisdicional será determinada pelo(a)', '["A) natureza da infração praticada e pelo local em que tiver se consumado o delito.", "B) local em que tiver se consumado o delito.", "C) natureza da infração praticada.", "D) natureza da infração praticada e pela prevenção."]'::jsonb, 'A', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Aristóteles, juiz de uma vara criminal da justiça comum, profere sentença em processo-crime cuja competência era da justiça militar.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A respeito da prova no processo penal, assinale a alternativa correta.', '["A) A prova objetiva demonstra a existência/inexistência de um determinado fato ou a veracidade/falsidade de uma determinada alegação. Todos os fatos, em sede de processo penal, devem ser provados.", "B) São consideradas provas ilícitas aquelas obtidas com a violação do direito processual. Por outro lado, são consideradas provas ilegítimas as obtidas com a violação das regras de direito material.", "C) As leis em geral e os costumes não precisam ser comprovados.", "D) A lei processual pátria prevê expressamente a inadmissibilidade da prova ilícita por derivação, perfilhando-se à “teoria dos frutos da árvore envenenada” (“fruits of poisonous tree”)."]'::jsonb, 'D', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Da sentença que absolver sumariamente o réu caberá(ão)', '["A) recurso em sentido estrito.", "B) embargos.", "C) revisão criminal.", "D) apelação."]'::jsonb, 'D', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A respeito do pagamento das verbas rescisórias, assinale a alternativa correta.', '["A) No caso de pedido de demissão em contrato por prazo indeterminado, o prazo para pagamento das verbas rescisórias é de 10 dias contados da data da notificação da demissão, quando dispensado o empregado do cumprimento do aviso prévio pelo empregador.", "B) O empregador que descumpre o prazo de pagamento das verbas rescisórias deverá pagá-las posteriormente acrescidas de 50% de multa, nos termos do artigo 467 da Consolidação das Leis do Trabalho.", "C) O pagamento das verbas rescisórias ocorrerá no primeiro dia útil imediato ao término do contrato de trabalho quando o empregador indenizar o aviso prévio.", "D) As verbas rescisórias devidas após decurso normal de prazo de contrato a termo deverão ser pagas até o décimo dia contado do término, em face da inexistência do aviso prévio."]'::jsonb, 'A', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'João da Silva, empregado da empresa Alfa Ltda., exerce suas atribuições funcionais em dois turnos de trabalho alternados de oito horas cada, que compreendem o horário diurno e o noturno. Considerando que a atividade de seu empregador não se desenvolve de forma ininterrupta e que não existe norma coletiva disciplinando a jornada de trabalho, assinale a alternativa correta.', '["A) João não tem direito ao pagamento de horas extras e à redução da hora noturna.", "B) João tem direito ao pagamento de horas extras, mas não tem direito à redução da hora noturna.", "C) João não tem direito ao pagamento de horas extras, mas tem direito à redução da hora noturna.", "D) João tem direito ao pagamento de horas extras e à redução da hora noturna."]'::jsonb, 'D', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Maria da Silva foi contratada para trabalhar como cozinheira na residência de Márcio dos Santos, percebendo um salário mínimo. Passados dois anos, Márcio ficou desempregado e decidiu iniciar um negócio próprio de venda de doces e salgados. Para atingir seu objetivo, aproveitou-se dos serviços de Maria, oferecendo-lhe um acréscimo de R$ 100,00 na remuneração. Assim, além de preparar as refeições da família de Márcio, a empregada Maria também dedicava parte de seu tempo preparando os doces e salgados que seriam vendidos por ele posteriormente. Durante três anos, Márcio desenvolveu essa atividade comercial com base em sua residência. Contudo, em virtude de uma proposta de emprego, Márcio encerrou a venda de quitutes e retirou o acréscimo de R$ 100,00 da remuneração de Maria. Inconformada, Maria reclamou ao longo de seis meses com o seu empregador, a fim de ver restabelecida a gratificação.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Uma empresa põe anúncio em jornal oferecendo emprego para a função de vendedor, exigindo que o candidato tenha experiência anterior de 11 meses nessa função. Diante disso, assinale a alternativa correta.', '["A) A exigência é legal, pois a experiência até 1 ano pode ser exigida do candidato a qualquer emprego, estando inserida no poder diretivo do futuro empregador.", "B) A exigência não traduz discriminação no emprego, de modo que poderia ser exigido qualquer período de experiência anterior.", "C) A exigência é ilegal, pois o máximo que o futuro empregador poderia exigir seriam 3 meses de experiência.", "D) A exigência é ilegal, pois o máximo que o futuro empregador poderia exigir seriam 6 meses de experiência."]'::jsonb, 'D', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'O sindicato dos empregados de empresa de transporte e o sindicato das empresas de transporte firmaram convenção coletiva, na qual foi estipulado aviso prévio de 60 dias por tempo de serviço, no caso de dispensa sem justa causa. Dois meses depois de esse instrumento normativo estar em vigor, o motorista Sílvio de Albuquerque foi despedido imotivadamente pela Transportadora Carga Pesada Ltda. Em virtude de não ter a CTPS assinada e de não terem sido pagas suas verbas rescisórias, Sílvio ajuizou ação trabalhista, pleiteando o reconhecimento do vínculo de emprego, assim como o pagamento das verbas rescisórias, observando-se o aviso prévio de 60 dias, bem como a projeção de 2/12 nas suas férias proporcionais, 13º proporcional e FGTS, além da contagem desse período no registro do termo final do contrato em sua CTPS. Em contestação, a transportadora impugnou a pretensão de Sílvio, sob o argumento de que ele era autônomo e, ainda que não o fosse, o instituto do aviso prévio, tal como previsto no art. 7º, XXI, da CRFB, é de trinta dias, inexistindo lei que o regulamente. Argumentou, ainda, que convenção coletiva não é lei em sentido formal e que, portanto, seria inválida a regulamentação da Constituição por meio da autonomia coletiva sindical.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Para equiparação salarial, é necessário que', '["A) haja identidade de funções, trabalho de igual valor para o mesmo empregador, na mesma localidade, com contemporaneidade na prestação dos serviços na mesma função e a qualquer tempo, inexistindo quadro de carreira organizado.", "B) haja identidade de funções, trabalho com a mesma produtividade e perfeição técnica, para o mesmo empregador, na mesma região metropolitana, com contemporaneidade na prestação de serviços na mesma função e a qualquer tempo, e quadro de carreira homologado pelo Ministério do Trabalho e Emprego.", "C) haja identidade de funções, trabalho de igual valor para o mesmo empregador, na mesma região metropolitana, sendo a prestação de serviços entre o empregado e o modelo contemporânea na mesma função, mas com diferença não superior a 2 anos, inexistindo quadro de carreira organizado.", "D) os empregados comparados tenham a mesma função, pois todo trabalho deve ser igualmente remunerado de acordo com o princípio da isonomia consagrado constitucionalmente."]'::jsonb, 'C', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A respeito das nulidades no processo do trabalho, é correto afirmar que', '["A) declarada a nulidade, por qualquer fundamento, todos os atos processuais posteriores serão nulos.", "B) as partes poderão alegar nulidade enquanto estiver aberta a instrução, mesmo que já tenham tido oportunidade de manifestação nos autos.", "C) é desnecessária a provocação da parte para a declaração de nulidade.", "D) só serão considerados nulos os atos que alegadamente causarem manifesto prejuízo às partes litigantes."]'::jsonb, 'D', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A respeito da prova testemunhal no processo do trabalho, é correto afirmar que', '["A) em se tratando de ação trabalhista pelo rito ordinário ou sumaríssimo, as partes poderão ouvir no máximo três testemunhas cada; sendo inquérito, o número é elevado para seis.", "B) apenas as testemunhas arroladas previamente poderão comparecer à audiência a fim de serem ouvidas.", "C) no processo do trabalho sumaríssimo, a simples ausência da testemunha na audiência enseja a sua condução coercitiva.", "D) as testemunhas comparecerão à audiência independentemente de intimação e, no caso de não comparecimento, serão intimadas ex officio ou a requerimento da parte."]'::jsonb, 'D', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'No dia 22/7/2009 (quarta-feira), foi publicada a sentença de improcedência do pedido. O advogado do autor tomou ciência da decisão, mas, como estava viajando, localizando-se em outro Estado da federação, interpôs recurso ordinário via fac-símile no dia 27/7/2009 (segunda-feira). Ao retornar de viagem, o advogado do autor requereu a juntada do recurso original no dia 04/8/2009 (terça-feira). Entretanto, após este último ato do advogado do autor, o juiz considerou intempestiva a interposição do recurso ordinário, negando-lhe seguimento.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Caio, metalúrgico, ajuizou ação trabalhista em face da empresa Ômega postulando sua reintegração ao emprego, pois, segundo suas alegações, teria sido dispensado no curso de estabilidade sindical. Postulou ainda a concessão de medida liminar visando a tal reintegração até o final do processo, com base no art. 659, X, da CLT. O juiz, ao apreciar o pedido de medida liminar antes da citação da ré, decidiu pela sua denegação, dando prosseguimento ao feito. A esse respeito, assinale a alternativa correta.', '["A) A natureza jurídica da decisão denegatória da liminar é de decisão interlocutória, não cabendo interposição de recurso imediato, devendo ser deferida a liminar.", "B) A natureza jurídica da decisão denegatória da liminar é de decisão interlocutória, não cabendo interposição de recurso imediato, razão pela qual é cabível a impetração de mandado de segurança.", "C) A natureza jurídica da decisão denegatória da liminar é de decisão terminativa, cabendo interposição de recurso ordinário, razão pela qual é incabível a impetração de mandado de segurança por haver recurso próprio.", "D) A natureza jurídica da decisão denegatória da liminar é de decisão definitiva, cabendo impetração de mandado de segurança, pois não há recurso próprio no caso."]'::jsonb, 'A', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Com relação à competência material da Justiça do Trabalho, é correto afirmar que', '["A) não compete à Justiça do Trabalho, mas à Justiça Federal, o julgamento de ação anulatória de auto de infração lavrado por auditor fiscal do trabalho.", "B) é da competência da Justiça do Trabalho o julgamento das ações ajuizadas em face da Previdência Social que versem sobre litígios ou medidas cautelares relativos a acidentes do trabalho.", "C) de acordo com o entendimento do Superior Tribunal de Justiça, é da competência da Justiça do Trabalho processar e julgar a ação de cobrança ajuizada por profissional liberal contra cliente.", "D) a Justiça do Trabalho é competente para julgar ação ajuizada por sindicato de categoria profissional em face de determinada empresa para que esta seja condenada a repassar-lhe as contribuições assistenciais descontadas dos salários dos empregados sindicalizados."]'::jsonb, 'D', 'Questão do Exame da OAB 2011.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'Mévio é advogado empregado de empresa de grande porte atuando como diretor jurídico e tendo vários colegas vinculados à sua direção. Instado por um dos diretores, escala um dos seus advogados para atuar em processo judicial litigioso, no interesse de uma das filhas do referido diretor. À luz das normas estatutárias, é correto afirmar que', '["A) a defesa dos interesses dos familiares dos dirigentes da empresa está ínsita na atuação profissional do advogado empregado.", "B) a atuação do advogado empregado nesses casos pode ocorrer voluntariamente, sem relação com o seu emprego.", "C) a relação de emprego retira do advogado sua independência profissional, pois deve defender os interesses do patrão.", "D) em casos de dedicação exclusiva, a jornada de trabalho máxima do advogado será de quatro horas diárias e de vinte horas semanais."]'::jsonb, 'B', 'Questão do Exame da OAB 2012.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'Terêncio, após intensa atividade advocatícia, é acometido por mal de origem psiquiátrica, mas diagnosticado como passível de cura após tratamento prolongado. Não podendo exercer os atos da vida civil, apresenta requerimento à OAB. No concernente ao tema, à luz das normas aplicáveis, é correto afirmar que é caso de', '["A) cancelamento da inscrição como advogado.", "B) impedimento ao exercício profissional, mantida a inscrição na OAB.", "C) licença do exercício da atividade profissional.", "D) penalidade de exclusão por doença."]'::jsonb, 'C', 'Questão do Exame da OAB 2012.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'Mévio, advogado, é procurado por Eulâmpia, que realiza consulta sobre determinado tema jurídico. Alguns meses depois, o advogado recebe uma intimação para prestar depoimento como testemunha em processo no qual Eulâmpia é ré, pelos fatos relatados por ela em consulta profissional. No concernente ao tema, à luz das normas estatutárias, é correto afirmar que', '["A) o advogado deve comparecer ao ato e prestar depoimento como testemunha dos fatos.", "B) é caso de recusa justificada ao depoimento por ter tido o advogado ciência dos fatos em virtude do exercício da profissão.", "C) a simples consulta jurídica não é privativa de advogado, equiparada a mero aconselhamento protocolar.", "D) o advogado poderá prestar o depoimento, mesmo contra sua vontade, desde que autorizado pelo cliente."]'::jsonb, 'B', 'Questão do Exame da OAB 2012.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'Após recebida representação disciplinar sem fundamentos, cabe ao relator designado pelo presidente do Conselho Seccional da OAB, à luz das normas aplicáveis,', '["A) arquivar o processo ato contínuo.", "B) propor ao presidente o arquivamento do processo.", "C) designar data para a defesa oral pelo advogado.", "D) julgar improcedente a representação."]'::jsonb, 'B', 'Questão do Exame da OAB 2012.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'Caio, próspero comerciante, contrata, para prestação de serviços profissionais de advocacia, Mévio, que se apresenta como advogado. O cliente outorga a devida procuração com poderes gerais para o foro. Usando o referido instrumento, ocorre a propositura de ação judicial em face de Trácio. Na contestação, o advogado do réu alega vício na representação, uma vez que Mévio não possui registro na OAB, consoante certidão que apresenta nos autos judiciais. Diante de tal circunstância, é correto afirmar que', '["A) os atos praticados pelo suposto advogado não ofendem qualquer dispositivo legal.", "B) verificada a ausência de inscrição profissional, deverá ser outorgado prazo para sua regularização.", "C) os atos praticados por Mévio são nulos, pois foram praticados por pessoa não inscrita na OAB.", "D) a declaração de nulidade dos atos processuais esgota o rol de atos sancionatórios."]'::jsonb, 'C', 'Questão do Exame da OAB 2012.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'Raul, advogado, é acusado, em processo disciplinar, de ter perdido prazos em diversos processos, de ter atuado contra os interesses dos seus clientes e de ter um número exagerado de indeferimento de petições iniciais, por ineptas, desconexas, com representações sucessivas à OAB. Em relação a tais circunstâncias, à luz das normas estatutárias, é correto afirmar que as condutas imputadas a Raul', '["A) não caracterizam infração disciplinar.", "B) são consideradas desvios processuais exclusivamente.", "C) demandam atuação da OAB no sentido educativo.", "D) caracterizam inépcia da atuação profissional."]'::jsonb, 'D', 'Questão do Exame da OAB 2012.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'Caio ajuíza ação em face da empresa Toupeira e Lontra S.A. buscando a devolução de numerário por ter recebido produto com defeito oculto. O pedido é julgado improcedente por ausência de provas. Houve recurso de apelação. No início do julgamento, o relator apresentou críticas à atuação do advogado do recorrente, que não teria instruído o processo adequadamente. Presente no julgamento, o advogado pediu a palavra, que lhe foi negada, por já ter apresentado sua sustentação oral.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'Mévio, advogado recém-formado com dificuldades de iniciar sua atividade profissional, propõe a colegas de bairro e de escola a participação percentual nos honorários dos clientes que receber para consultas ou que pretendam ajuizar ações judiciais. Consoante as normas aplicáveis, assinale a alternativa correta em relação à conduta de Mévio.', '["A) Caracteriza agenciamento de causas com participação dos honorários.", "B) É possível, desde que conste em contrato escrito entre as partes.", "C) O agenciamento de clientela é admitido em situações peculiares como essa.", "D) Desde que os serviços advocatícios sejam prestados por Mévio, inexiste infração disciplinar."]'::jsonb, 'A', 'Questão do Exame da OAB 2012.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'Daniel, advogado, resolve divulgar seus trabalhos contratando empresa de propaganda e marketing. Esta lhe apresenta um plano de ação, que inclui a contratação de jovens, homens e mulheres, para a distribuição de prospectos de propaganda do escritório, coloridos, indicando as especialidades de atuação e apresentando determinados temas que seriam considerados acessíveis à multidão de interessados. O projeto é realizado.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'Semprônia, advogada há longos anos, é contratada para representar os interesses de Esculápio, que está preso à disposição da Justiça criminal. Ao procurar contatar seu cliente, verifica que ele está em penitenciária, considerado incomunicável, por determinação de normas regulamentares do sistema. Apesar disso, requer o acesso ao seu cliente, que foi indeferido. Consoante as normas legais e estatutárias, é correto afirmar que', '["A) a atuação do advogado deve estar submetida aos regulamentos penitenciários, para a sua própria segurança.", "B) os estabelecimentos penitenciários civis devem organizar as visitas dos advogados por ordem de chegada.", "C) o advogado, quando for contatar o seu cliente em prisão, deve ser acompanhado por representante da OAB.", "D) é ilegal vedar a presença do advogado no contato com seu cliente, ainda que considerado incomunicável."]'::jsonb, 'D', 'Questão do Exame da OAB 2012.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'No caso de arbitramento judicial de honorários, pela ausência de estipulação ou acordo em relação a eles, é correto afirmar, à luz das regras estatutárias, que', '["A) os valores serão livremente arbitrados pelo juiz, sem parâmetros, devendo o advogado percebê-los.", "B) a fixação dos honorários levará em conta o valor econômico da questão.", "C) a tabela organizada pela OAB não é relevante para essa forma de fixação.", "D) havendo acordo escrito, poderá ocorrer o arbitramento judicial de honorários."]'::jsonb, 'B', 'Questão do Exame da OAB 2012.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Ética Profissional', 'Mévio, advogado de longa data, pretendendo despachar uma petição em processo judicial em curso perante a Comarca Y, é surpreendido com aviso afixado na porta do cartório de que o magistrado somente receberia para despacho petições que reputasse urgentes, devendo o advogado dirigir-se ao assessor principal do juiz para uma prévia triagem quanto ao assunto em debate. À luz das normas estatutárias, é correto afirmar que', '["A) a organização do serviço cartorário é da competência do juiz, que pode estabelecer padrões de atendimento aos advogados.", "B) a triagem realizada por assessor do juiz permite melhor eficiência no desempenho da atividade judicial e não colide com as normas estatutárias.", "C) o advogado tem direito de dirigir-se diretamente ao magistrado no seu gabinete para despachar petições sem prévio agendamento.", "D) a duração razoável do processo é princípio que permite a triagem dos atos dos advogados e o exercício dos seus direitos estatutários."]'::jsonb, 'C', 'Questão do Exame da OAB 2012.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A respeito da Convenção sobre Eliminação de Todas as Formas de Discriminação contra a Mulher, ratificada pelo Brasil, assinale a alternativa correta.', '["A) Uma vez que a Convenção tem como objetivo proteger um grupo específico, não pode ser considerada como um documento de proteção internacional dos direitos humanos.", "B) A Convenção possui um protocolo facultativo, que permite a apresentação de denúncias sobre violação dos direitos por ela consagrados.", "C) A Convenção permite que o Estado-parte adote, de forma definitiva, ações afirmativas para garantir a igualdade entre gêneros.", "D) A Convenção traz em seu texto um mecanismo de proteção dos direitos que consagra, por meio de petições sobre violações, que podem ser protocoladas por qualquer Estado-parte."]'::jsonb, 'B', 'Questão do Exame da OAB 2012.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'O Pacto Internacional dos Direitos Econômicos, Sociais e Culturais e o Pacto Internacional dos Direitos Civis e Políticos preveem em seu texto mecanismos de proteção, efetivação e monitoramento dos Direitos Humanos consagrados em seus respectivos textos. É correto afirmar que, em ambos os pactos, encontra-se o seguinte mecanismo:', '["A) envio de relatórios sobre medidas adotadas e progressos alcançados.", "B) acusação de regresso de proteção dos direitos, que poderá ser protocolada por qualquer Estado-parte, inclusive o próprio analisado.", "C) sistemática de petições, que deverão ser elaboradas e protocoladas por um Estado-parte diferente daquele que está sendo acusado.", "D) envio de relatórios sobre medidas adotadas e progressos alcançados, que deverão ser elaborados e protocolados por um Estado-parte diferente daquele que está sendo analisado."]'::jsonb, 'A', 'Questão do Exame da OAB 2012.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A Convenção Interamericana de Direitos Humanos dispõe que toda pessoa tem direito à vida, que deve ser protegida por lei, e que ninguém dela poderá ser privado arbitrariamente. A respeito da pena de morte, o documento afirma que', '["A) é inadmissível a aplicação da pena de morte em qualquer circunstância, já que o direito à vida deve ser protegido por lei desde a concepção.", "B) não se pode aplicar pena de morte aos delitos políticos, exceto se forem conexos a delitos comuns sujeitos a tal pena.", "C) a pena de morte não pode ser imposta àquele que, no momento da perpetração do delito, for menor de dezoito anos, nem aplicada à mulher em estado gestacional.", "D) não se admite que Estados promulguem pena de morte, exceto se já a tiverem aplicado e a tenham abolido, hipótese em que a tal pena poderá ser restabelecida."]'::jsonb, 'C', 'Questão do Exame da OAB 2012.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A respeito dos Procuradores-Gerais de Justiça nos Estados e no Distrito Federal, é INCORRETO afirmar que', '["A) podem ser destituídos pela Assembleia Legislativa (nos Estados) e pela Câmara Legislativa (no Distrito Federal).", "B) podem ser reconduzidos somente uma vez.", "C) devem ser integrantes da carreira e exercem o cargo por mandato de dois anos.", "D) são nomeados pelo Governador (nos Estados) e pelo Presidente da República (no Distrito Federal)."]'::jsonb, 'A', 'Questão do Exame da OAB 2012.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'NÃO pode ser objeto de ação direta de inconstitucionalidade', '["A) decreto que promulga tratado.", "B) decreto legislativo que aprova tratado.", "C) resolução.", "D) súmula vinculante."]'::jsonb, 'D', 'Questão do Exame da OAB 2012.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Suponha que o STF, no exame de um caso concreto (controle difuso), tenha reconhecido a incompatibilidade entre uma lei em vigor desde 1987 e a Constituição de 1988. Nesse caso, é correto afirmar que', '["A) após reiteradas decisões no mesmo sentido, o STF poderá editar súmula vinculante.", "B) o STF deverá encaminhar a decisão ao Senado.", "C) os órgãos fracionários dos tribunais, a partir de então, ficam dispensados de encaminhar a questão ao pleno.", "D) a eficácia da decisão é erga omnes."]'::jsonb, 'A', 'Questão do Exame da OAB 2012.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'João, residente no Brasil há cinco anos, é acusado em outro país de ter cometido crime político. Nesse caso, o Brasil', '["A) pode conceder a extradição se João for estrangeiro.", "B) pode conceder a extradição se João for brasileiro naturalizado e tiver cometido o crime antes da naturalização.", "C) não pode conceder a extradição, independentemente da nacionalidade de João.", "D) não pode conceder a extradição apenas se João for brasileiro nato."]'::jsonb, 'C', 'Questão do Exame da OAB 2012.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A respeito dos direitos políticos, assinale a alternativa correta.', '["A) O cancelamento de naturalização por decisão do Ministério da Justiça é caso de perda de direitos políticos.", "B) A condenação criminal transitada em julgado, enquanto durarem seus efeitos, é caso de cassação de direitos políticos.", "C) A improbidade administrativa é caso de suspensão de direitos políticos.", "D) A incapacidade civil relativa é caso de perda de direitos políticos."]'::jsonb, 'C', 'Questão do Exame da OAB 2012.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A Constituição assegura, entre os direitos e garantias individuais, a inviolabilidade do domicílio, afirmando que “a casa é asilo inviolável do indivíduo, ninguém nela podendo penetrar sem o consentimento do morador” (art. 5º, XI, CRFB).
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Assinale a alternativa que relacione corretamente o cargo político e o sistema eleitoral adotado.', '["A) Governador: sistema proporcional de dois turnos.", "B) Prefeito: sistema majoritário de maioria simples para municípios com menos de 200 mil eleitores.", "C) Congressista: sistema proporcional.", "D) Vereador: sistema distrital."]'::jsonb, 'B', 'Questão do Exame da OAB 2012.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A sociedade empresária do ramo de comunicações A Notícia Brasileira, com sede no Brasil, celebrou contrato internacional de prestação de serviços de informática com a sociedade empresária Santiago Info, com sede em Santiago. O contrato foi celebrado em Buenos Aires, capital argentina, tendo sido estabelecido como foro de eleição pelas partes Santiago, se porventura houver a necessidade de resolução de litígio entre as partes.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Arnaldo Butti, cidadão brasileiro, falece em Roma, Itália, local onde residia e tinha domicílio. Em seu testamento, firmado em sua residência poucos dias antes de sua morte, Butti, que não tinha herdeiros naturais, deixou um imóvel localizado na Avenida Atlântica, na cidade do Rio de Janeiro, para Júlia, neta de sua enfermeira, que vive no Brasil. Inconformada com a partilha, Fernanda, brasileira, sobrinha-neta do falecido, que há dois anos vivia de favor no referido imóvel, questiona no Judiciário brasileiro a validade do testamento. Alega, em síntese, que, embora obedecesse a todas as formalidades previstas na lei italiana, o ato não seguiu todas as formalidades preconizadas pela lei brasileira.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Considerando os princípios norteadores do Estatuto da Criança e do Adolescente, a prática de atos infracionais fica sujeita a medidas que têm objetivos socioeducativos. Nesse sentido, é correto afirmar que', '["A) se Aroldo, que tem 11 anos, subtrair para si coisa alheia pertencente a uma creche, deverá cumprir medida socioeducativa de prestação de serviços comunitários, por período não superior a um ano.", "B) a obrigação de reparar o dano causado pelo ato infracional não é considerada medida socioeducativa, tendo em vista que o adolescente não pode ser responsabilizado civilmente.", "C) o acolhimento institucional e a colocação em família substituta podem ser aplicados como medidas protetivas ou socioeducativas, a depender das características dos atos infracionais praticados.", "D) a internação, como uma das medidas socioeducativas previstas pelo ECA, não poderá exceder o período máximo de três anos, e a liberação será compulsória aos 21 anos de idade."]'::jsonb, 'D', 'Questão do Exame da OAB 2012.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Um famoso casal de artistas residente e domiciliado nos Estados Unidos, em viagem ao Brasil para o lançamento do seu mais novo filme, se encantou por Caio, de 4 anos, a quem pretende adotar. Caio teve sua filiação reconhecida exclusivamente pela mãe Isabel, que, após uma longa conversa com o casal, concluiu que o melhor para o filho era ser adotado, tendo em vista que o famoso casal possuía condições infinitamente melhores de bem criar e educar Caio. Além disso, Isabel ficou convencida do amor espontâneo e sincero que o casal de imediato nutriu pelo menino.  Ante a situação hipotética, é correto afirmar que', '["A) a adoção só é concedida quando for impossível manter a criança ou o adolescente em sua família, razão pela qual o consentimento de Isabel é irrelevante para a apreciação do pedido do famoso casal, que será deferido caso represente o melhor interesse de Caio.", "B) independentemente da manifestação de vontade de Isabel, o famoso casal terá prioridade na adoção de Caio, depois de esgotadas todas as possibilidades de colocação de Caio em uma família brasileira.", "C) tendo em vista o consentimento da mãe de Caio, o famoso casal terá prioridade em sua adoção em face de outros casais já previamente inscritos nos cadastros de interessados na adoção, mantidos pela Justiça da Infância e da Juventude.", "D) a adoção internacional é medida excepcional; entretanto, em virtude do consentimento de Isabel para a adoção de seu filho pelo famoso casal, este só não terá prioridade se houver casal de brasileiro, residente no Brasil, habilitado para a adoção."]'::jsonb, 'D', 'Questão do Exame da OAB 2012.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Luiz Fernando, servidor público estável pertencente aos quadros de uma fundação pública federal, inconformado com a pena de demissão que lhe foi aplicada, ajuizou ação judicial visando à invalidação da decisão administrativa que determinou a perda do seu cargo público. A decisão judicial acolheu a pretensão de Luiz Fernando e invalidou a penalidade disciplinar de demissão. Diante da situação hipotética narrada, Luiz Fernando deverá ser', '["A) reintegrado ao cargo anteriormente ocupado, ou no resultante de sua transformação, com ressarcimento de todas as vantagens.", "B) aproveitado no cargo anteriormente ocupado ou em outro cargo de vencimentos e responsabilidades compatíveis com o anterior, sem ressarcimento das vantagens pecuniárias.", "C) readaptado em cargo de atribuições e responsabilidades compatíveis, com ressarcimento de todas as vantagens.", "D) reconduzido ao cargo anteriormente ocupado ou em outro de vencimentos e responsabilidades compatíveis com o anterior, com ressarcimento de todas as vantagens pecuniárias."]'::jsonb, 'A', 'Questão do Exame da OAB 2012.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Durante competição esportiva (campeonato estadual de futebol), o clube “A” foi punido com a perda de um ponto em virtude de episódios de preconceito por parte de sua torcida. Com essa decisão de primeira instância da justiça desportiva, o clube “B” foi declarado campeão naquele ano. O clube “A” apresentou recurso contra a decisão de primeira instância. Antes mesmo do julgamento desse recurso, distribuiu ação ordinária perante a Justiça Estadual com o objetivo de reaver o ponto que lhe fora retirado pela Justiça arbitral. Diante de tal situação, é correto afirmar que', '["A) como o direito brasileiro adotou o sistema de jurisdição una, tendo o Poder Judiciário o monopólio da apreciação, com força de coisa julgada, de lesão ou ameaça a direito, é cabível a apreciação judicial dessa matéria a qualquer tempo.", "B) as decisões da Justiça Desportiva são inquestionáveis na via judicial, uma vez que vige, no direito brasileiro, sistema pelo qual o Poder Judiciário somente pode decidir matérias para as quais não exista tribunal administrativo específico.", "C) como regra, o ordenamento vigente adota o Princípio da Inafastabilidade da Jurisdição (art. 5º, XXXV, da CRFB); todavia, as decisões da Justiça Desportiva consubstanciam exceção a essa regra, já que são insindicáveis na via judicial.", "D) o Poder Judiciário pode rever decisões proferidas pela Justiça Desportiva; ainda assim, exige-se, anteriormente ao ajuizamento da ação cabível, o esgotamento da instância administrativa, por se tratar de exceção prevista na Constituição."]'::jsonb, 'D', 'Questão do Exame da OAB 2012.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Joana D''Arc, beneficiária de pensão por morte deixada por ex-fiscal de rendas, falecido em 5/1/1999, ajuizou ação ordinária em face da União, alegando que determinado aumento remuneratório genérico concedido aos fiscais de renda em atividade não lhe teria sido repassado. Assim, isso teria violado a regra constitucional da paridade remuneratória entre ativos, inativos e pensionistas. Acerca de tal alegação, é correto afirmar que é manifestamente', '["A) procedente, pois, embora a regra da paridade remuneratória entre ativos, inativos e pensionistas tenha sido revogada pela EC 41/2003, a pensão por morte rege-se pela lei vigente à época do óbito, quando ainda vigia tal regra.", "B) improcedente, pois, nos termos do verbete 339 da Súmula de Jurisprudência do STF, não cabe ao Poder Judiciário, que não tem função legislativa, aumentar vencimentos de servidores públicos sob fundamento de isonomia.", "C) improcedente, pois a regra da paridade remuneratória entre ativos, inativos e pensionistas foi revogada pela EC 41/2003, sendo absolutamente irrelevante o fato de o ex-servidor ter falecido antes da edição da referida emenda.", "D) procedente, pois a CRFB garante o reajustamento da pensão por morte dos benefícios para preservar-lhes, em caráter permanente, o valor real, conforme critérios estabelecidos em lei."]'::jsonb, 'A', 'Questão do Exame da OAB 2012.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Quatro municípios celebram um consórcio público para desenvolverem um projeto comum para o tratamento industrial de lixo coletado em suas respectivas áreas, criando uma pessoa jurídica para gerenciar as atividades do consórcio.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Ambulância do Corpo de Bombeiros envolveu-se em acidente de trânsito com automóvel dirigido por particular, que trafegava na mão contrária de direção. No acidente, o motorista do automóvel sofreu grave lesão, comprometendo a mobilidade de um dos membros superiores. Nesse caso, é correto afirmar que', '["A) existe responsabilidade objetiva do Estado em decorrência da prática de ato ilícito, pois há nexo causal entre o dano sofrido pelo particular e a conduta do agente público.", "B) não haverá o dever de indenizar se ficar configurada a culpa exclusiva da vítima, que dirigia na contramão, excluindo a responsabilidade do Estado.", "C) não se cogita de responsabilidade objetiva do Estado porque não houve a chamada culpa ou falha do serviço. E, de todo modo, a indenização do particular, se cabível, ficaria restrita aos danos materiais, pois o Estado não responde por danos morais.", "D) está plenamente caracterizada a responsabilidade civil do Estado, que se fundamenta na teoria do risco integral."]'::jsonb, 'B', 'Questão do Exame da OAB 2012.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A autorização de uso de bem público por particular caracteriza-se como ato administrativo', '["A) discricionário e bilateral, ensejando indenização ao particular no caso de revogação pela administração.", "B) unilateral, discricionário e precário, para atender interesse predominantemente particular.", "C) bilateral e vinculado, efetivado mediante a celebração de um contrato com a administração pública, de forma a atender interesse eminentemente público.", "D) discricionário e unilateral, empregado para atender a interesse predominantemente público, formalizado após a realização de licitação."]'::jsonb, 'B', 'Questão do Exame da OAB 2012.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Francis, brasileira, empresária, ao se deslocar do Rio de Janeiro para São Paulo em seu helicóptero particular, sofreu terrível acidente que culminou com a queda do aparelho em alto-mar. Após sucessivas e exaustivas buscas, feitas pelas autoridades e por empresas privadas contratadas pela família da vítima, infelizmente não foram encontrados os corpos de Francis e de Adilson, piloto da aeronave. Tendo sido esgotados os procedimentos de buscas e averiguações, de acordo com os artigos do Código Civil que regulam a situação supramencionada, é correto afirmar que o assento de óbito em registro público', '["A) independe de qualquer medida administrativa ou judicial, desde que seja constatada a notória probabilidade de morte de pessoa que estava em perigo de vida.", "B) depende exclusivamente de procedimento administrativo quanto à morte presumida junto ao Registro Civil das Pessoas Naturais.", "C) depende de prévia ação declaratória judicial quanto à morte presumida, sem necessidade de decretação judicial de ausência.", "D) depende de prévia declaração judicial de ausência, por se tratar de desaparecimento de uma pessoa sem dela haver notícia."]'::jsonb, 'C', 'Questão do Exame da OAB 2012.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A condição, o termo e o encargo são considerados elementos acidentais, facultativos ou acessórios do negócio jurídico, e têm o condão de modificar as consequências naturais deles esperadas. A esse respeito, é correto afirmar que', '["A) se considera condição a cláusula que, derivando da vontade das partes ou de terceiros, subordina o efeito do negócio jurídico a evento futuro e incerto.", "B) se for resolutiva a condição, enquanto esta se não realizar, não vigorará o negócio jurídico, não se podendo exercer desde a conclusão deste o direito por ele estabelecido.", "C) o termo inicial suspende o exercício, mas não a aquisição do direito e, salvo disposição legal ou convencional em contrário, computam-se os prazos, incluindo o dia do começo e excluindo o do vencimento.", "D) se considera não escrito o encargo ilícito ou impossível, salvo se constituir o motivo determinante da liberalidade, caso em que se invalida o negócio jurídico."]'::jsonb, 'D', 'Questão do Exame da OAB 2012.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Diogo, proprietário de um terreno urbano localizado no Município de Vila Formosa, autorizou Rafael, dono de uma transportadora, a utilizar parte desse terreno como garagem. Passados alguns meses de uso, Rafael, sem autorização de Diogo, construiu um galpão coberto com objetivo de proteger sua frota da chuva e do sol. Com o crescimento dos negócios, Rafael ampliou o galpão e ali montou uma oficina para realizar a manutenção dos seus veículos. Verificando uma oportunidade de negócio, Rafael passou a prestar serviços mecânicos a terceiros.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Mirtes gosta de decorar a janela de sua sala com vasos de plantas. A síndica do prédio em que Mirtes mora já advertiu a moradora do risco de queda dos vasos e de possível dano aos transeuntes e moradores do prédio. Num dia de forte ventania, os vasos de Mirtes caíram sobre os carros estacionados na rua, causando sérios prejuízos. Nesse caso, é correto afirmar que Mirtes', '["A) poderá alegar motivo de força maior e não deverá indenizar os lesados.", "B) está isenta de responsabilidade, pois não teve a intenção de causar prejuízo.", "C) somente deverá indenizar os lesados se tiver agido dolosamente.", "D) deverá indenizar os lesados, pois é responsável pelo dano causado."]'::jsonb, 'D', 'Questão do Exame da OAB 2012.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'José, solteiro, possui três irmãos: Raul, Ralph e Randolph. Raul era pai de Mauro e Mário. Mário era pai de Augusto e Alberto. Faleceram, em virtude de acidente automobilístico, Raul e Mário, na data de 15/4/2005. Posteriormente, José veio a falecer em 1º/5/2006. Sabendo-se que a herança de José é de R$ 90.000,00, como ficará a partilha de seus bens?', '["A) Como José não possui descendente, a partilha deverá ser feita entre os irmãos. E, como não há direito de representação entre os filhos de irmão, Ralph e Randolph receberão cada um R$ 45.000,00.", "B) Ralph e Randolph devem receber R$ 30.000,00 cada. A parte que caberá a Raul deve ser repartida entre Mauro e Mário. Sendo Mário pré-morto, seus filhos Alberto e Augusto devem receber a quantia que lhe caberia. Assim, Mauro deve receber R$ 15.0000,00, e Alberto e Augusto devem receber R$ 7.500,00 cada um.", "C) Ralph e Randolph receberão R$ 30.000,00 cada um. O restante (R$ 30.000,00) será entregue a Mauro, por direito de representação de seu pai pré-morto.", "D) Ralph e Randolph receberão R$ 30.000,00 cada um. O restante, na falta de outro colateral vivo, será entregue ao Município, Distrito Federal ou União."]'::jsonb, 'C', 'Questão do Exame da OAB 2012.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Marcelo, brasileiro, solteiro, advogado, sem que tenha qualquer impedimento para doar a casa de campo de sua livre propriedade, resolve fazê-lo, sem quaisquer ônus ou encargos, em benefício de Marina, sua amiga, também absolutamente capaz. Todavia, no âmbito do contrato de doação, Marcelo estipula cláusula de reversão por meio da qual o bem doado deverá se destinar ao patrimônio de Rômulo, irmão de Marcelo, caso Rômulo sobreviva à donatária. A respeito dessa situação, é correto afirmar que', '["A) diante de expressa previsão legal, não prevalece a cláusula de reversão estipulada em favor de Rômulo.", "B) no caso, em razão de o contrato de doação, por ser gratuito, comportar interpretação extensiva, a cláusula de reversão em favor de terceiro é válida.", "C) a cláusula em exame não é válida em razão da relação de parentesco entre o doador, Marcelo, e o terceiro beneficiário, Rômulo.", "D) diante de expressa previsão legal, a cláusula de reversão pode ser estipulada em favor do próprio doador ou de terceiro beneficiário por aquele designado, caso qualquer deles, nessa ordem, sobreviva ao donatário."]'::jsonb, 'A', 'Questão do Exame da OAB 2012.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Rejane, solteira, com 16 anos de idade, órfã de mãe e devidamente autorizada por seu pai, casa-se com Jarbas, filho de sua tia materna, sendo ele solteiro e capaz, com 23 anos de idade.
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'Os atos processuais não dependem de forma determinada, salvo se a lei expressamente o exigir e, ainda que realizados de outro modo, serão reputados válidos se preencherem a finalidade essencial. A respeito do tema, é correto afirmar que', '["A) compete às partes alegar nulidade dos atos na primeira oportunidade que lhes couber falar nos autos, sob pena de preclusão, exceto se a parte provar justo impedimento ou se a nulidade tiver que ser conhecida de ofício.", "B) é defesa a distribuição da petição inicial que não esteja acompanhada do instrumento de mandato, ainda que haja procuração junta aos autos principais.", "C) na hipótese de o réu apresentar reconvenção, dispensa-se a determinação de anotação pelo distribuidor, visto que será julgada simultaneamente à ação principal, na mesma sentença.", "D) se um ato for anulado, ou a nulidade afetar apenas parte do ato, nenhum efeito terão os atos subsequentes, prejudicando todos os que com aquele ou com a parte nula guardem ou não dependência."]'::jsonb, 'A', 'Questão do Exame da OAB 2012.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('OAB/FGV', 'Direito Geral', 'A Lei Civil afirma que, a despeito de a personalidade civil da pessoa começar com o nascimento com vida, ao nascituro serão assegurados os seus direitos desde a concepção. Para tanto, é correto afirmar que, na ação de posse em nome de nascituro,', '["A) a nomeação de médico pelo juiz para que emita laudo que comprove o estado de gravidez da requerente, assim previsto na lei processual civil, não poderá ser dispensado em qualquer hipótese.", "B) por se tratar de mera expectativa de nascimento com vida, portanto, não tendo o nascituro personalidade civil, fica dispensada a intervenção do Ministério Público na causa.", "C) reconhecida a gravidez, a sentença declarará que seja a requerente investida na posse dos direitos que assistam ao nascituro; não cabendo àquela o exercício do pátrio poder, o juiz nomeará curador.", "D) são documentos indispensáveis à ação o laudo comprobatório do estado gestacional emitido pelo médico nomeado pelo juiz e a certidão de óbito da pessoa de quem o nascituro é sucessor."]'::jsonb, 'C', 'Questão do Exame da OAB 2012.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('SUS-SP', 'Pediatria', 'Lactente de 6 meses é trazido ao pronto-socorro com história de febre, tosse e taquipneia há 2 dias. Ao exame físico: FR=60 irpm, sibilos difusos e tiragem subcostal. Qual é o agente etiológico mais provável?', '["A) Streptococcus pneumoniae", "B) Vírus Sincicial Respiratório (VSR)", "C) Mycoplasma pneumoniae", "D) Bordetella pertussis", "E) Adenovírus"]'::jsonb, 'B', 'O quadro clínico de sibilância e taquipneia no primeiro ano de vida sugere bronquiolite viral aguda, cujo agente mais comum é o VSR.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('USP', 'Cirurgia Geral', 'Homem de 45 anos, tabagista, apresenta dor abdominal súbita de forte intensidade. No raio-X de abdome agudo, observa-se pneumoperitônio. Qual é o diagnóstico mais provável e a conduta imediata?', '["A) Apendicite aguda / Apendicectomia", "B) Úlcera péptica perfurada / Laparotomia exploradora", "C) Pancreatite aguda / Tratamento conservador", "D) Obstrução intestinal / Sonda nasogástrica", "E) Diverticulite aguda / Antibioticoterapia"]'::jsonb, 'B', 'Pneumoperitônio indica víscera oca perfurada. Úlcera péptica é uma causa comum, especialmente em tabagistas. A conduta é cirúrgica emergencial.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('Enares', 'Ginecologia', 'Paciente de 28 anos, nuligesta, queixa-se de dismenorreia secundária intensa e dispareunia profunda há 2 anos. O ultrassom pélvico mostra cistos ovarianos com aspecto de vidro fosco. Qual é o diagnóstico mais provável?', '["A) Síndrome dos Ovários Policísticos", "B) Miomatose Uterina", "C) Endometriose", "D) Doença Inflamatória Pélvica", "E) Cisto de corpo lúteo"]'::jsonb, 'C', 'Dismenorreia secundária, dispareunia e cistos em vidro fosco (endometriomas) são clássicos de endometriose.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('Residência Bucomaxilofacial', 'Cirurgia Oral', 'Durante a exodontia do dente 48, incluso e impactado, ocorre fratura da raiz distal. Qual é o instrumental mais indicado para a remoção do ápice fraturado?', '["A) Alavanca reta grossa", "B) Extrator de ápice (alavanca apical)", "C) Fórceps 151", "D) Fórceps 17", "E) Lima endodôntica"]'::jsonb, 'B', 'Extratores de ápice são desenhados especificamente para remover pequenos fragmentos radiculares fraturados no interior do alvéolo.');
INSERT INTO question_bank (exam_board, discipline, question_text, options, correct_answer, explanation) VALUES ('UFRJ', 'Periodontia', 'A gengivite induzida pelo biofilme dental tem como característica clínica principal:', '["A) Perda de inserção clínica", "B) Sangramento à sondagem sem perda óssea", "C) Mobilidade dentária grau 3", "D) Reabsorção radicular externa", "E) Formação de abscesso periodontal"]'::jsonb, 'B', 'A gengivite é uma inflamação reversível restrita à gengiva, sem perda de inserção clínica ou perda óssea, sendo o sangramento seu principal sinal clínico.');